    // an arrow head in the middle of each stretch: which way the foot travels
    for (let k = 1; k <= 4; k++) {
      const tm = (T[k - 1] + T[k]) / 2, j = D.pts.findIndex(p => p.t >= tm);
      if (j < 2 || j >= sp.length - 1) continue;
      const a = sp[j - 2], b = sp[j + 1], d = Math.hypot(b.x - a.x, b.y - a.y); if (d < 3) continue;   // the foot hardly moves here
      const ux = (b.x - a.x) / d, uy = (b.y - a.y) / d, c = sp[j], L = 9, W = 6;
      g.globalAlpha = live ? (tm <= now ? 1 : 0.35) : lit(k) ? 1 : 0.4;
      g.beginPath(); g.moveTo(c.x + ux * L, c.y + uy * L); g.lineTo(c.x - ux * L * 0.6 - uy * W, c.y - uy * L * 0.6 + ux * W); g.lineTo(c.x - ux * L * 0.6 + uy * W, c.y - uy * L * 0.6 - ux * W); g.closePath();
      g.fillStyle = cols[k]; g.strokeStyle = 'rgba(10,14,30,0.8)'; g.lineWidth = 2; g.stroke(); g.fill();
    }
    // the phase numbers, where the foot is in each phase (1 and 5 share the floor → nudged apart)
    const ms = D.marks.map(S), placed = [];
    g.font = '900 11px Cairo, Roboto, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    ms.forEach((m, i) => {
      let p = { ...m };
      for (const q of placed) if (Math.hypot(q.x - p.x, q.y - p.y) < 17) { p.x = q.x + (this.ar ? -18 : 18); p.y = q.y - 6; }
      placed.push(p);
      const cur = this.mode !== 'full' && this.mode !== 'scrub' ? i === this.phase : now !== null && Math.abs(now - Kick4D.phaseT(T, i)) < 0.05;
      const r = cur ? 10.5 : 8.5;
      g.globalAlpha = 1;
      if (cur) { g.fillStyle = 'rgba(255,255,255,0.35)'; g.beginPath(); g.arc(p.x, p.y, r + 4, 0, Math.PI * 2); g.fill(); }
      g.fillStyle = cols[i]; g.strokeStyle = cur ? '#fff' : 'rgba(10,14,30,0.85)'; g.lineWidth = 2;
      g.beginPath(); g.arc(p.x, p.y, r, 0, Math.PI * 2); g.fill(); g.stroke();
      g.fillStyle = '#10142a'; g.fillText(String(i + 1), p.x, p.y + 0.5);       // like the lesson's 1️⃣…5️⃣
    });
