// LEAGUE SCREEN
// =====================================================================
const LeagueScreen = {
  tab: 'league',
  init() { League.process(); this.render(); },
  render() {
    const root = TKD.$('league-root'); if (!root) return;
    const club = !!window.Club?.joined();
    const tabs = [['league', `🏅 ${TKD.t('League', 'الدوري')}`], ['today', `🏆 ${TKD.t('Today', 'النهارده')}`], ['awards', `🎖️ ${TKD.t('Awards', 'الجوايز')}`], ['versus', `⚔️ ${TKD.t('Duels', 'المواجهات')}`], ['gym', club ? `🏟️ ${TKD.t('Club heroes', 'أبطال النادي')}` : `🏟️ ${TKD.t('Gym', 'الصالة')}`]];
    root.innerHTML = `<div class="lg-tabs" role="tablist">${tabs.map(([k, l]) => `<button type="button" role="tab" aria-selected="${this.tab === k}" class="${this.tab === k ? 'on' : ''}" data-tab="${k}">${l}</button>`).join('')}</div>
      <div class="lg-body">${this[this.tab + 'HTML']()}</div>`;
    root.querySelectorAll('[data-tab]').forEach(b => b.addEventListener('click', () => { this.tab = b.dataset.tab; TKD.gs()?.playSound('click'); this.render(); }));
    root.querySelector('#lg-play')?.addEventListener('click', () => Challenge.start());
    root.querySelectorAll('[data-profile]').forEach(li => li.addEventListener('click', () => window.Profile?.open(li.dataset.profile)));
    root.querySelectorAll('[data-hero]').forEach(el => el.addEventListener('click', () => window.Club?.showHero(el.dataset.hero)));
    root.querySelectorAll('[data-cert]').forEach(b => b.addEventListener('click', () => {
      const p = PlayerSystem.getPlayers().find(x => x.id === b.dataset.pid); if (p) Certificates.award(p, b.dataset.cert, b.dataset.week);
    }));
    root.querySelector('#lg-duel')?.addEventListener('click', () => switchScreen('versus'));
    root.querySelector('#lg-scan')?.addEventListener('click', () => Coach.open('import'));
    root.querySelector('#lg-mycard')?.addEventListener('click', () => { const p = PlayerSystem.getCurrentPlayer(); if (p) PlayerCard.show(p); });
  },
  row(i, p, main, sub, cls = '') {
    const local = p?.id && PlayerSystem.getPlayers().some(x => x.id === p.id);
    // v56: a club player from another device opens their hero card
    const hero = !local && p?.id && window.Club?.joined() && Club.find(p.id);
    return `<li class="lg-row ${cls} ${p?.id === TKD.pid() ? 'me' : ''} ${hero ? 'remote' : ''}" ${local ? `data-profile="${p.id}" tabindex="0" role="button"` : hero ? `data-hero="${p.id}" tabindex="0" role="button"` : ''}><span class="lg-rank">${i < 3 ? ['🥇', '🥈', '🥉'][i] : TKD.num(i + 1)}</span>${hero ? Club.avatar(hero) : TKD.avatar(p)}
      <span class="lg-name">${TKD.esc(p?.name || '?')}${sub ? `<small>${sub}</small>` : ''}</span><span class="lg-pts">${main}</span></li>`;
  },
  leagueHTML() {
    const me = PlayerSystem.getCurrentPlayer();
    const myTier = League.tierOf(me);
    const set = League.settings();
    const all = League.table();
    const tierBlock = (ti) => {
      const rows = all.filter(r => r.tier === ti);
      if (!rows.length) return '';
      const t = League.TIERS[ti];
      return `<section class="lg-tier ${ti === myTier ? 'mine' : ''}" style="--tier:${t.color}">
        <h3>${t.icon} ${League.tierName(ti)} <small>${TKD.t(`${rows.length} players`, TKD.count(rows.length, 'hero', 'ar'))}</small></h3>
        <ol class="lg-list">${rows.map((r, i) => this.row(i, r.p, `${TKD.num(r.total)}`,
          TKD.t(`${r.challengeDays} challenges · ${r.warmDays} warm-ups · ${r.trainDays} days`, `${TKD.count(r.challengeDays, 'challenge', 'ar')} · ${TKD.num(r.warmDays)} إحماء · ${TKD.count(r.trainDays, 'trainDay', 'ar')}`),
          i < set.promote && ti < League.TIERS.length - 1 && r.total >= set.minPoints ? 'up' : '')).join('')}</ol></section>`;
    };
    return `${window.Club?.joined() ? Club.statusLine() : ''}<div class="lg-head"><div>${TKD.t('This week ends in', 'الأسبوع بيخلص بعد')} <b>${TKD.count(League.daysLeft(), 'day')}</b></div>
        <div class="lg-legend"><span class="lg-up">⬆️</span> ${TKD.t(`top ${set.promote} with ${set.minPoints}+ points go up a league`, `أول ${TKD.num(set.promote)} اللي عندهم ${TKD.num(set.minPoints)} نقطة أو أكتر بيطلعوا دوري أعلى`)}</div></div>
      ${[myTier, ...League.TIERS.map((_, i) => i).filter(i => i !== myTier).reverse()].map(tierBlock).join('')}
      <details class="lg-how"><summary>❓ ${TKD.t('How are points counted?', 'النقط بتتحسب إزاي؟')}</summary>
        <ul><li>🏆 ${TKD.t("Today's challenge: your best score each day (only the first 3 tries count)", 'تحدي النهارده: أحسن نتيجة ليك كل يوم (أول ٣ محاولات بس اللي بتتحسب)')}</li>
        <li>🔥 ${TKD.t('+20 for every day you warm up', '+٢٠ لكل يوم تعمل فيه إحماء')}</li>
        <li>📅 ${TKD.t('+10 for every day you train', '+١٠ لكل يوم تتمرن فيه')}</li>
        <li>⬆️ ${TKD.t('Nobody goes down a league — only up!', 'محدش بينزل دوري — بس بتطلع!')}</li></ul></details>`;
  },
  todayHTML() {
    const c = Challenge.today(), left = Challenge.triesLeft();
    const rk = Challenge.ranking();
    const players = PlayerSystem.getPlayers();
    return `${window.Club?.joined() ? Club.statusLine() : ''}<div class="lg-challenge">
        <div class="lg-ch-icon">${TKD.gameIcon(c.gameId)}</div>
        <div><h3>${TKD.gameName(c.gameId)} · ${TKD.skillName(c.skillId)}</h3>
          <p>${TKD.t('Same game and kick for everyone today, on Normal. Your best of the first 3 tries counts.', 'نفس اللعبة والركلة للكل النهارده، على مستوى عادي. أحسن نتيجة من أول ٣ محاولات هي اللي بتتحسب.')}</p></div>
        <button type="button" class="btn btn-success" id="lg-play">${left ? TKD.t(`Play (${left} left)`, `العب (فاضل ${TKD.num(left)})`) : TKD.t('Practice', 'اتمرن')}</button></div>
      ${rk.length ? `<ol class="lg-list">${rk.map((r, i) => this.row(i, players.find(p => p.id === r.pid) || { id: r.pid, name: r.name, character: r.character }, `${TKD.num(r.score)}%`, r.remote ? `🌍 ${TKD.t('another device', 'جهاز تاني')}` : new Date(r.ts).toLocaleTimeString(TKD.ar ? 'ar-EG' : 'en-GB', { hour: '2-digit', minute: '2-digit' }))).join('')}</ol>`
        : `<p class="lg-empty">${TKD.t('Nobody has played today yet — be the first! 🚀', 'لسه محدش لعب النهارده — خليك الأول! 🚀')}</p>`}`;
  },
  awardsHTML() {
    const st = League.load(); const players = PlayerSystem.getPlayers();
    const last = (st.history || [])[0];
    // v56: a club winner from another device still shows (name kept with the week's results)
    const nameOf = (id) => players.find(p => p.id === id) || (window.Club?.joined() && Club.find(id) ? { id, name: Club.find(id).name, character: Club.find(id).character, remote: true } : (st.names?.[id] ? { id, name: st.names[id], remote: true } : null));
    const me = PlayerSystem.getCurrentPlayer();
    const awards = last ? Object.entries(last.awards || {}).map(([id, pid]) => {
      const p = nameOf(pid); if (!p) return '';
      return `<li class="lg-award">${TKD.avatar(p)}<span><b>${League.awardName(id)}</b><small>${TKD.esc(p.name)}${p.remote ? ` · 🌍` : ''}</small></span>
        ${p.remote ? '' : `<button type="button" class="btn btn-small" data-cert="${id}" data-pid="${p.id}" data-week="${last.week}">📜</button>`}</li>`;
    }).join('') : '';
    const badges = (me?.badges || []).slice().reverse();
    return `<h3 class="lg-sub">${TKD.t('Last week', 'الأسبوع اللي فات')}${last ? ` <small>(${last.week})</small>` : ''}</h3>
      ${awards ? `<ul class="lg-awards">${awards}</ul>` : `<p class="lg-empty">${TKD.t('Awards are given when the week ends (Friday night).', 'الجوايز بتتوزع لما الأسبوع يخلص (يوم الجمعة بالليل).')}</p>`}
      <h3 class="lg-sub">${TKD.t('My badges', 'شاراتي')}</h3>
      ${badges.length ? `<div class="lg-badges">${badges.map(b => `<span class="lg-badge" title="${b.week || ''}">${League.awardName(b.id)}</span>`).join('')}</div>` : `<p class="lg-empty">${TKD.t('No badges yet — keep training! 💪', 'لسه مفيش شارات — كمّل تمرين! 💪')}</p>`}`;
  },
  versusHTML() {
    const rows = (window.Versus ? Versus.standings() : []);
    const champs = window.Versus ? Versus.champions() : [];
    return `<div class="lg-head"><div>${TKD.t('Wins in 1 × 1 duels on this device', 'المكسب في مواجهات ١×١ على الجهاز ده')}</div>
        <button type="button" class="btn btn-success btn-small" id="lg-duel">⚔️ ${TKD.t('New duel', 'مواجهة جديدة')}</button></div>
      ${rows.length ? `<ol class="lg-list">${rows.map((r, i) => this.row(i, r.p, `${TKD.num(r.w)} ${TKD.t('W', 'فوز')}`, TKD.t(`${r.l} losses · ${r.pts} points scored`, `${TKD.count(r.l, 'loss', 'ar')} · ${TKD.count(r.pts, 'point', 'ar')}`))).join('')}</ol>`
        : `<p class="lg-empty">${TKD.t('No duels yet.', 'لسه مفيش مواجهات.')}</p>`}
      ${champs.length ? `<h3 class="lg-sub">👑 ${TKD.t('Tournament champions', 'أبطال البطولات')}</h3><ul class="lg-awards">${champs.map(c => `<li class="lg-award">${TKD.avatar(c.p)}<span><b>${TKD.esc(c.p.name)}</b><small>${TKD.esc(c.name)} · ${c.date}</small></span></li>`).join('')}</ul>` : ''}`;
  },
  gymHTML() {
    if (window.Club?.joined()) return Club.wallHTML();          // v56: the whole club, live
    const rows = window.GymBoard ? GymBoard.rows() : [];
    return `<div class="lg-head"><div>${TKD.t('Players from every device your coach scanned (this week)', 'لاعبين من كل الأجهزة اللي المدرب مسح كروتهم (الأسبوع ده)')}</div>
        <div class="tkd-row"><button type="button" class="btn btn-small" id="lg-mycard">📇 ${TKD.t('My card', 'كارتي')}</button>
        <button type="button" class="btn btn-small" id="lg-scan">📷 ${TKD.t('Add cards (coach)', 'ضيف كروت (المدرب)')}</button></div></div>
      ${window.Club?.usable() ? `<p class="club-hint">☁️ ${TKD.t('Tip: the coach can join this device to the online club (Coach → Club) — then everybody of the gym shows here, live.', 'نصيحة: المدرب يقدر يوصّل الجهاز ده بالنادي أونلاين (المدرب ← النادي) — وساعتها كل الصالة تظهر هنا على طول.')}</p>` : ''}
      ${rows.length ? `<ol class="lg-list">${rows.map((r, i) => this.row(i, r.p, `${TKD.num(r.points)}`, `${League.TIERS[r.tier]?.icon || ''} ${r.local ? TKD.t('this device', 'الجهاز ده') : TKD.t(`card from ${r.updated}`, `كارت ${r.updated}`)}${r.stale ? ' · ⏳' : ''}`)).join('')}</ol>`
        : `<p class="lg-empty">${TKD.t('No players yet.', 'لسه مفيش لاعبين.')}</p>`}`;
  }
};
window.LeagueScreen = LeagueScreen;

// small in-app confirm (no browser dialogs)
function tkdConfirm(text, okLabel) {
  return new Promise(res => {
    const ov = document.createElement('div');
    ov.className = 'tkd-modal';
    ov.innerHTML = `<div class="tkd-modal-card"><p class="tkd-confirm-txt">${TKD.esc(text)}</p>
      <div class="tkd-row"><button type="button" class="btn" data-a="0">${TKD.t('Cancel', 'إلغاء')}</button><button type="button" class="btn btn-danger" data-a="1">${okLabel || TKD.t('Yes', 'أيوه')}</button></div></div>`;
    document.body.appendChild(ov);
    ov.querySelectorAll('[data-a]').forEach(b => b.addEventListener('click', () => { ov.remove(); res(b.dataset.a === '1'); }));
  });
}
window.tkdConfirm = tkdConfirm;

// =====================================================================
// PLAYER CARD (for the coach's gym leaderboard across devices)
// =====================================================================
const PlayerCard = {
  PREFIX: 'TKD1.',
  build(p) {
    const m = window.DashboardSystem ? DashboardSystem.masteryFor(p.id).map(x => x.overall) : [];
    const streak = TKD.read(GameState.storageKey(p.id), {})?.practiceStreak || 0;
    return { v: 1, id: p.id, n: p.name, c: p.character || 'boy', t: League.tierOf(p), wk: TKD.weekKey(), wp: League.pointsFor(p.id).total, s: streak, m, d: TKD.dayKey() };
  },
  encode(card) {
    const bytes = new TextEncoder().encode(JSON.stringify(card));
    let bin = ''; bytes.forEach(b => { bin += String.fromCharCode(b); });
    return this.PREFIX + btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  },
  decode(text) {
    const t = String(text || '').trim();
    const i = t.indexOf(this.PREFIX); if (i < 0) return null;
    try {
      const b64 = t.slice(i + this.PREFIX.length).split(/\s/)[0].replace(/-/g, '+').replace(/_/g, '/');
      const bin = atob(b64 + '==='.slice((b64.length + 3) % 4));
      const card = JSON.parse(new TextDecoder().decode(Uint8Array.from(bin, ch => ch.charCodeAt(0))));
      return card && card.v === 1 && card.id && card.n ? card : null;
    } catch (e) { return null; }
  },
  show(p) {
    const card = this.build(p), code = this.encode(card);
    const ov = document.createElement('div');
    ov.className = 'tkd-modal';
    ov.innerHTML = `<div class="tkd-modal-card tkd-card-view">
      <h2>📇 ${TKD.t('Player card', 'كارت اللاعب')}</h2>
      <div class="tkd-card-id">${TKD.avatar(p)}<div><b>${TKD.esc(p.name)}</b><small>${League.TIERS[card.t].icon} ${League.tierName(card.t)} · ${TKD.count(card.wp, 'point')} ${TKD.t('this week', 'الأسبوع ده')}</small></div></div>
      <div class="tkd-qr" id="tkd-qr"></div>
      <p class="tkd-muted">${TKD.t("Show this to your coach's camera, or send the code.", 'وري الكارت ده لكاميرا المدرب، أو ابعتله الكود.')}</p>
      <textarea readonly class="tkd-code" rows="2" aria-label="code">${code}</textarea>
      <div class="tkd-row wrap">
        <button type="button" class="btn btn-small" data-a="copy">📋 ${TKD.t('Copy code', 'انسخ الكود')}</button>
        ${navigator.share ? `<button type="button" class="btn btn-small" data-a="share">📤 ${TKD.t('Share', 'شارك')}</button>` : ''}
        <button type="button" class="btn btn-small" data-a="png">⬇️ ${TKD.t('Save picture', 'احفظ الصورة')}</button>
        <button type="button" class="btn btn-success btn-small" data-a="close">${TKD.t('Done', 'تمام')}</button></div></div>`;
    document.body.appendChild(ov);
    const box = ov.querySelector('#tkd-qr');
    let canvas = null;
    try { canvas = QRCode.toCanvas(code, 6); box.appendChild(canvas); }
    catch (e) { box.innerHTML = `<textarea readonly class="tkd-code">${code}</textarea>`; }
    ov.querySelectorAll('[data-a]').forEach(b => b.addEventListener('click', async () => {
      const a = b.dataset.a;
      if (a === 'close') ov.remove();
      if (a === 'copy') { try { await navigator.clipboard.writeText(code); TKD.toast(TKD.t('📋 Code copied', '📋 الكود اتنسخ'), 'success'); } catch (e) { const ta = ov.querySelector('.tkd-code'); ta.select(); TKD.toast(TKD.t('Select and copy the code below', 'حدّد الكود اللي تحت وانسخه'), 'info'); } }
      if (a === 'share') { try { await navigator.share({ title: 'Taekwondo Journey', text: code }); } catch (e) {} }
      if (a === 'png' && canvas) { const l = document.createElement('a'); l.href = canvas.toDataURL('image/png'); l.download = `card-${p.name}.png`; document.body.appendChild(l); l.click(); l.remove(); }
    }));
  }
};
window.PlayerCard = PlayerCard;

const GymBoard = {
  KEY: 'taekwondoJourneyGym',
  load() { return TKD.read(this.KEY, { cards: {} }); },
  add(card) {
    const st = this.load();
    const old = st.cards[card.id];
    if (old && old.d > card.d) return 'older';
    st.cards[card.id] = card; TKD.write(this.KEY, st);
    return old ? 'updated' : 'added';
  },
  remove(id) { const st = this.load(); delete st.cards[id]; TKD.write(this.KEY, st); },
  rows() {
    const wk = TKD.weekKey();
    const local = PlayerSystem.getPlayers().map(p => ({ p, points: League.pointsFor(p.id).total, tier: League.tierOf(p), local: true }));
    const ids = new Set(local.map(r => r.p.id));
    const remote = Object.values(this.load().cards).filter(c => !ids.has(c.id)).map(c => ({
      p: { id: c.id, name: c.n, character: c.c }, points: c.wk === wk ? c.wp : 0, tier: c.t || 0, local: false, updated: c.d, stale: c.wk !== wk
    }));
    return [...local, ...remote].sort((a, b) => b.points - a.points);
  }
};
window.GymBoard = GymBoard;

// =====================================================================
// COACH MODE
// =====================================================================
const Coach = {
  KEY: 'taekwondoJourneyCoach',
  unlocked: false,
  view: 'panel',
  pinHash(pin) { return 'h' + TKD.hash('tkd-coach-salt:' + pin).toString(36); },
  hasPin() { return !!TKD.read(this.KEY, {}).pin; },
  // ---------- reject easy-to-guess PINs when a coach is choosing one (all-same-digit,
  // simple runs like 1234/4321, or a well-known weak PIN such as 1212/0852)
  isWeakPin(pin) {
    if (!/^\d{4}$/.test(pin)) return true;
    const d = [...pin].map(Number);
    if (d.every(x => x === d[0])) return true; // 0000, 1111, ...
    if (d.every((x, i) => i === 0 || x === d[i - 1] + 1)) return true; // 1234, 2345, ...
    if (d.every((x, i) => i === 0 || x === d[i - 1] - 1)) return true; // 4321, 9876, ...
    const common = ['1212', '1122', '2001', '2580', '0852', '1004', '1313', '6969'];
    return common.includes(pin);
  },
  open(view = 'panel') { this.view = view; switchScreen('coach'); },
  init() { this.render(); },
  // v55 — the PIN is not left open behind the coach: leaving for a child's screen locks at once;
  // a quick look at a coach tool (dashboard, report, league, tournament) keeps it open for 3 minutes
  TOOLS: ['dashboard', 'report', 'league', 'versus'],
  lock() { this.unlocked = false; this._leftAt = 0; this._pending = null; this.stopCamera(); if (window.VoiceRecorder?.recording()) VoiceRecorder.cancel(); },
  away(id) {
    this._pending = null; this._why = '';                                  // a PIN request left unanswered is forgotten
    if (window.VoiceRecorder?.recording()) VoiceRecorder.cancel();       // never leave the microphone on
    if (!this.unlocked) return;
    if (this.TOOLS.includes(id)) { if (!this._leftAt) this._leftAt = Date.now(); }
    else this.lock();
  },
  back() { if (this.unlocked && this._leftAt && Date.now() - this._leftAt > 3 * 60e3) this.lock(); this._leftAt = 0; },
  // a grown-up action (restore a backup, erase everything…) asks for the coach PIN first
  guard(fn, why) {
    if (this.unlocked) return fn();
    this._pending = fn; this._why = why || '';
    this.open(this.view === 'panel' ? 'panel' : this.view);
  },
  runPending() { const f = this._pending; this._pending = null; this._why = ''; if (f) setTimeout(f, 250); },
  render() {
    const root = TKD.$('coach-root'); if (!root) return;
    if (window.VoiceRecorder?.recording()) VoiceRecorder.cancel();
    if (!this.unlocked) return this.renderPin(root);
    const views = { panel: () => this.panelHTML(), club: () => Club.coachHTML(), import: () => this.importHTML(), voice: () => this.voiceHTML(), settings: () => this.settingsHTML() };
    root.innerHTML = `<div class="co-top">
        <div class="co-nav">${[['panel', `👥 ${TKD.t('Players', 'اللاعبين')}`], ...(window.Club?.configured() ? [['club', `☁️ ${TKD.t('Club', 'النادي')}`]] : []), ['import', `📷 ${TKD.t('Scan cards', 'امسح كروت')}`], ['voice', `🎙️ ${TKD.t('Record voice', 'سجّل الصوت')}`], ['settings', `⚙️ ${TKD.t('Settings', 'الإعدادات')}`]]
          .map(([k, l]) => `<button type="button" class="${this.view === k ? 'on' : ''}" data-v="${k}">${l}</button>`).join('')}</div>
        <button type="button" class="btn btn-small" id="co-lock">🔒 ${TKD.t('Lock', 'اقفل')}</button></div>
      <div class="co-body">${views[this.view]()}</div>`;
    root.querySelectorAll('[data-v]').forEach(b => b.addEventListener('click', () => { this.stopCamera(); this.view = b.dataset.v; this.render(); }));
    TKD.$('co-lock').addEventListener('click', () => { this.lock(); this.render(); });
    this['bind_' + this.view]?.(root);
  },

  // ---------- forgotten PIN: a grown-up question (not something a young child can answer) resets it
  forgotPin(root) {
    const a = 6 + Math.floor(Math.random() * 7), b = 12 + Math.floor(Math.random() * 8);
    root.innerHTML = `<div class="co-pin">
      <div class="co-pin-ico">🔑</div>
      <h3>${TKD.t('Grown-ups only', 'للكبار بس')}</h3>
      <p class="co-pin-help">${TKD.t(`To choose a new PIN, type the answer: ${a} × ${b}`, `عشان تختار رقم سري جديد، اكتب ناتج: ${TKD.num(a)} × ${TKD.num(b)}`)}</p>
      <input id="co-gate" class="player-name-input" inputmode="numeric" autocomplete="off" dir="ltr" style="max-width:160px;text-align:center">
      <div class="tkd-row"><button type="button" class="btn btn-success btn-small" id="co-gate-ok">${TKD.t('Reset PIN', 'غيّر الرقم')}</button>
      <button type="button" class="btn btn-small" id="co-gate-back">${TKD.t('Back', 'رجوع')}</button></div>
      <p class="co-pin-help" id="co-gate-msg"></p></div>`;
    const inp = TKD.$('co-gate'); inp.focus();
    const ok = () => {
      const v = parseInt(String(inp.value).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)), 10);
      if (v === a * b) { const c = TKD.read(this.KEY, {}); delete c.pin; TKD.write(this.KEY, c); this.unlocked = false; this.render(); }
      else { TKD.$('co-gate-msg').textContent = TKD.t('Not right — try again.', 'مش مظبوط — جرّب تاني.'); inp.value = ''; }
    };
    TKD.$('co-gate-ok').addEventListener('click', ok);
    inp.addEventListener('keydown', e => { if (e.key === 'Enter') ok(); });
    TKD.$('co-gate-back').addEventListener('click', () => this.render());
  },

  // ---------- PIN
  renderPin(root) {
    const setting = !this.hasPin();
    this._pin = ''; this._first = null;
    const paint = (msg) => {
      root.innerHTML = `<div class="co-pin">
        <div class="co-pin-ico">👩‍🏫</div>
        <h3>${msg || (setting ? TKD.t('Choose a 4-digit coach PIN', 'اختار رقم سري للمدرب (٤ أرقام)') : TKD.t('Coach PIN', 'الرقم السري للمدرب'))}</h3>
        ${this._why ? `<p class="co-pin-why">🔐 ${TKD.esc(this._why)}</p>` : ''}
        <p class="co-pin-help">${setting
          ? (this._first ? TKD.t('Type the same 4 numbers again to confirm.', 'اكتب نفس الـ ٤ أرقام اللي لسه كاتبها عشان نتأكد.')
                         : TKD.t('There is no ready-made PIN: pick any 4 numbers you will remember. Kids should not know it.', 'مفيش رقم جاهز: اختار أي ٤ أرقام هتفتكرها، وماتقولهاش للأطفال.'))
          : ''}</p>
        ${setting && !this._first ? `<ul class="co-pin-what"><li>👥 ${TKD.t('Follow every player: who needs help, where kids get stuck', 'تابع كل لاعب: مين محتاج مساعدة، والأطفال بيتعثروا فين')}</li>
          <li>🎙️ ${TKD.t('Record the game in your own voice', 'سجّل كلام اللعبة بصوتك')}</li>
          <li>⚙️ ${TKD.t('League rules, game pace, backups', 'قواعد الدوري، سرعة الألعاب، والنسخ الاحتياطية')}</li></ul>` : ''}
        <div class="co-dots">${[0, 1, 2, 3].map(i => `<i class="${i < this._pin.length ? 'on' : ''}"></i>`).join('')}</div>
        <div class="co-pad" dir="ltr">${[1, 2, 3, 4, 5, 6, 7, 8, 9, '⌫', 0, '✓'].map(k => `<button type="button" data-k="${k}">${k}</button>`).join('')}</div>
        ${setting ? '' : `<button type="button" class="co-forgot" id="co-forgot">${TKD.t('Forgot the PIN?', 'نسيت الرقم السري؟')}</button>`}
        <button type="button" class="btn btn-small" id="co-back">${TKD.t('Back', 'رجوع')}</button></div>`;
      root.querySelectorAll('[data-k]').forEach(b => b.addEventListener('click', () => press(b.dataset.k)));
      TKD.$('co-forgot')?.addEventListener('click', () => this.forgotPin(root));
      TKD.$('co-back').addEventListener('click', () => { this._pending = null; this._why = ''; if (PlayerSystem.getCurrentPlayer()) switchScreen('home'); else StartScreen.show(); });
    };
    const press = (k) => {
      if (k === '⌫') { this._pin = this._pin.slice(0, -1); return paint(); }
      if (k === '✓') return submit();
      if (this._pin.length < 4) this._pin += k;
      paint();
      if (this._pin.length === 4) setTimeout(submit, 150);
    };
    const submit = () => {
      if (this._pin.length !== 4) return;
      if (setting) {
        if (!this._first) {
          if (this.isWeakPin(this._pin)) { this._pin = ''; return paint(TKD.t('That PIN is too easy to guess — pick different numbers.', 'الرقم ده سهل التخمين — اختار أرقام تانية.')); }
          this._first = this._pin; this._pin = ''; return paint(TKD.t('Type it again', 'اكتبه تاني'));
        }
        if (this._first !== this._pin) { this._first = null; this._pin = ''; return paint(TKD.t('Not the same — try again', 'مش زي بعض — جرّب تاني')); }
        TKD.write(this.KEY, { ...TKD.read(this.KEY, {}), pin: this.pinHash(this._pin) });
        this.unlocked = true; TKD.gs()?.playSound('success'); this.render(); return this.runPending();
      }
      if (this.pinHash(this._pin) === TKD.read(this.KEY, {}).pin) { this.unlocked = true; TKD.gs()?.playSound('success'); this.render(); return this.runPending(); }
      this._pin = ''; TKD.gs()?.playSound('error'); paint(TKD.t('Wrong PIN', 'الرقم غلط'));
    };
    this._keyHandler && document.removeEventListener('keydown', this._keyHandler);
    this._keyHandler = (e) => {
      if (this.unlocked || !TKD.$('coach-screen')?.classList.contains('active') || e.target?.closest?.('input, textarea') || !document.querySelector('.co-pad')) return;
      if (/^\d$/.test(e.key)) press(e.key); else if (e.key === 'Backspace') press('⌫'); else if (e.key === 'Enter') press('✓');
    };
    document.addEventListener('keydown', this._keyHandler);
    paint();
  },

  // ---------- players panel
  stats(p) {
    const att = PlayerSystem.getAttempts().filter(a => a.playerId === p.id);
    const played = att.filter(a => a.gameId !== 'warmup' && a.gameId !== 'learning');
    const last5 = played.slice(-5);
    const avg5 = last5.length ? Math.round(last5.reduce((s, a) => s + a.score, 0) / last5.length) : null;
    let failRun = 0; for (let i = played.length - 1; i >= 0 && !played[i].passed; i--) failRun++;
    const last = att.reduce((m, a) => Math.max(m, a.ts), 0);
    const save = TKD.read(GameState.storageKey(p.id), null) || PlayerSystem.rebuildState(p.id) || {};
    const unlocked = save.unlockedSkills || ['apchagi'];
    const help = [];
    if (avg5 !== null && avg5 < 60 && last5.length >= 3) help.push(TKD.t(`low scores (avg ${avg5}%)`, `نتايج واطية (متوسط ${avg5}%)`));
    if (failRun >= 3) help.push(TKD.t(`${failRun} misses in a row`, `${TKD.count(failRun, 'try', 'ar')} مش ناجحة ورا بعض`));
    if (last && Date.now() - last > 7 * 864e5) help.push(TKD.t('no training for a week', 'متمرنش من أسبوع'));
    return { avg5, failRun, last, help, save, unlocked, week: League.pointsFor(p.id).total, streak: save.practiceStreak || 0 };
  },
  // ---------- across every player: which station (kick × mini-game) trips kids up
  // most often, so a coach knows where to spend the next lesson's time — not just
  // which child is struggling (that's stats() above), but which STEP is the problem.
  stuckReport(minAttempts = 3, limit = 5) {
    const att = PlayerSystem.getAttempts().filter(a => a.gameId !== 'warmup' && a.gameId !== 'learning');
    const by = {};
    att.forEach(a => {
      const k = a.skillId + '|' + a.gameId;
      const row = by[k] || (by[k] = { skillId: a.skillId, gameId: a.gameId, n: 0, fails: 0, players: new Set() });
      row.n++; row.players.add(a.playerId); if (!a.passed) row.fails++;
    });
    return Object.values(by)
      .filter(r => r.n >= minAttempts)
      .map(r => ({ ...r, rate: r.fails / r.n, players: r.players.size }))
      .filter(r => r.rate > 0)
      .sort((a, b) => b.rate - a.rate || b.n - a.n)
      .slice(0, limit);
  },
  panelHTML() {
    const players = PlayerSystem.getPlayers();
    if (!players.length) return `<p class="lg-empty">${TKD.t('No players yet.', 'لسه مفيش لاعبين.')}</p>`;
    const rows = players.map(p => ({ p, s: this.stats(p) }));
    const needs = rows.filter(r => r.s.help.length);
    const stuck = this.stuckReport();
    const fmt = (ts) => ts ? new Date(ts).toLocaleDateString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short' }) : '—';
    return `${needs.length ? `<section class="co-help"><h3>🆘 ${TKD.t('Needs help', 'محتاجين مساعدة')}</h3>
        <ul>${needs.map(r => `<li>${TKD.avatar(r.p)}<b>${TKD.esc(r.p.name)}</b> ${r.s.help.map(h => `<span class="co-chip">${h}</span>`).join('')}</li>`).join('')}</ul></section>` : ''}
      ${stuck.length ? `<section class="co-stuck"><h3>🧩 ${TKD.t('Where kids get stuck', 'فين الأطفال بيتعثروا')}</h3>
        <ul>${stuck.map(r => `<li><b>${TKD.skillName(r.skillId)}</b> · ${TKD.gameIcon(r.gameId)} ${TKD.gameName(r.gameId)}
          <span class="co-chip co-chip-bad">${TKD.t(`${Math.round(r.rate * 100)}% of tries missed`, `${TKD.num(Math.round(r.rate * 100))}٪ من المحاولات ماعدّتش`)}</span>
          <span class="co-chip">${TKD.count(r.players, 'kid')}</span></li>`).join('')}</ul></section>` : ''}
      <div class="co-tools">
        <button type="button" class="btn btn-small" data-tool="tournament">👑 ${TKD.t('New tournament', 'بطولة جديدة')}</button>
        <button type="button" class="btn btn-small" data-tool="gym">🏟️ ${TKD.t('Gym leaderboard', 'ترتيب الصالة')}</button>
        <button type="button" class="btn btn-small" data-tool="dashboard">📊 ${TKD.t('Dashboard', 'لوحة اللاعبين')}</button>
        <button type="button" class="btn btn-small" data-tool="backup">⬇️ ${TKD.t('Backup (all players)', 'نسخة احتياطية (كل اللاعبين)')}</button>
      </div>
      <div class="db-table-wrap"><table class="co-table">
        <thead><tr><th>${TKD.t('Player', 'اللاعب')}</th><th>${TKD.t('League', 'الدوري')}</th><th>${TKD.t('Week pts', 'نقط الأسبوع')}</th><th>🔥</th><th>${TKD.t('Kicks open', 'الركلات المفتوحة')}</th><th>${TKD.t('Last 5 avg', 'متوسط آخر ٥')}</th><th>${TKD.t('Last played', 'آخر لعب')}</th><th></th></tr></thead>
        <tbody>${rows.map(({ p, s }) => `<tr data-pid="${p.id}">
          <td class="co-who">${TKD.avatar(p)} <b>${TKD.esc(p.name)}</b></td>
          <td data-l="${TKD.t('League', 'الدوري')}">${League.TIERS[League.tierOf(p)].icon}</td><td data-l="${TKD.t('Week pts', 'نقط الأسبوع')}">${TKD.num(s.week)}</td><td data-l="🔥">${TKD.num(s.streak)}</td>
          <td data-l="${TKD.t('Kicks', 'الركلات')}">${GameConfig.SKILL_ORDER.map(sk => `<span class="co-kick ${s.unlocked.includes(sk) ? 'on' : ''}" title="${TKD.skillName(sk)}">${TKD.num(GameConfig.SKILL_ORDER.indexOf(sk) + 1)}</span>`).join('')}</td>
          <td data-l="${TKD.t('Last 5', 'آخر ٥')}">${s.avg5 === null ? '—' : TKD.num(s.avg5) + (TKD.ar ? '٪' : '%')}</td><td data-l="${TKD.t('Last played', 'آخر لعب')}">${fmt(s.last)}</td>
          <td class="co-acts">
            <button type="button" title="${TKD.t('Play as', 'العب بيه')}" data-act="play">▶<span class="co-act-l">${TKD.t('Play as', 'العب بيه')}</span></button>
            <button type="button" title="${TKD.t('Move to a kick', 'انقله لركلة')}" data-act="stage">🎯<span class="co-act-l">${TKD.t('Move', 'انقله')}</span></button>
            <button type="button" title="${TKD.t("Give back today's tries", 'رجّع محاولات النهارده')}" data-act="tries">↺<span class="co-act-l">${TKD.t('Tries', 'المحاولات')}</span></button>
            <button type="button" title="${TKD.t('Player card (QR)', 'كارت اللاعب (QR)')}" data-act="card">📇<span class="co-act-l">${TKD.t('Card', 'الكارت')}</span></button>
            <button type="button" title="${TKD.t('Delete', 'امسح')}" data-act="del">🗑️<span class="co-act-l">${TKD.t('Delete', 'امسح')}</span></button></td></tr>`).join('')}</tbody></table></div>`;
  },
  bind_club(root) { Club.bindCoach(root); },
  bind_panel(root) {
    root.querySelectorAll('[data-tool]').forEach(b => b.addEventListener('click', () => {
      const t = b.dataset.tool;
      if (t === 'tournament') { window.Versus && (Versus.mode = 'tournament'); switchScreen('versus'); }
      if (t === 'gym') { LeagueScreen.tab = 'gym'; switchScreen('league'); }
      if (t === 'dashboard') switchScreen('dashboard');
      if (t === 'backup') exportProgress();
    }));
    root.querySelectorAll('tr[data-pid] [data-act]').forEach(b => b.addEventListener('click', async () => {
      const pid = b.closest('tr').dataset.pid; const p = PlayerSystem.getPlayers().find(x => x.id === pid); if (!p) return;
      const act = b.dataset.act;
      if (act === 'play') { PlayerSystem.selectPlayer(pid); switchScreen('home'); }
      if (act === 'card') PlayerCard.show(p);
      if (act === 'tries') {
        // v55: extra tries for today — the score the child already got (and its league points) stays
        const day = TKD.dayKey(), used = Challenge.attemptsFor(pid, day).length, n = League.settings().tries;
        if (Challenge.triesLeft(pid, day) >= n) { TKD.toast(TKD.t(`${p.name} still has all of today's tries (${n})`, `محاولات ${p.name} النهارده لسه كاملة (${TKD.count(n, 'try', 'ar')})`), 'info'); return; }
        const st = League.load(); st.bonus = st.bonus || {};
        st.bonus[pid] = { d: day, n: used };                            // triesLeft = tries + bonus − used = tries
        League.save(st);
        TKD.toast(TKD.t(`↺ ${p.name} has ${n} tries again today (the best score so far is kept)`, `↺ ${p.name}: رجعت ${TKD.count(n, 'try', 'ar')} للنهارده، وأحسن نتيجة اتجابت بتفضل محسوبة`), 'success');
        this.render();
      }
      if (act === 'del') {
        if (await tkdConfirm(TKD.t(`Delete ${p.name} and all their scores?`, `تمسح ${p.name} وكل نتايجه؟`), TKD.t('Delete', 'امسح'))) {
          const wasMe = PlayerSystem.getCurrentPlayerId() === pid;
          PlayerSystem.deletePlayer(pid);
          GymBoard.remove(pid);
          if (window.Club?.isCoach()) Club.be().then(be => be.removePlayer(Club.info().clubId, pid, p.name)).catch(() => {});
          if (wasMe) {
            const next = PlayerSystem.getPlayers()[0];
            if (next) PlayerSystem.selectPlayer(next.id);
            else { this.lock(); StartScreen.show(); return; }           // nobody left → make a new player
          }
          this.render();
        }
      }
      if (act === 'stage') this.stageDialog(p);
    }));
  },
  stageDialog(p) {
    const ov = document.createElement('div');
    ov.className = 'tkd-modal';
    ov.innerHTML = `<div class="tkd-modal-card"><h2>🎯 ${TKD.t(`Move ${TKD.esc(p.name)} to…`, `انقل ${TKD.esc(p.name)} لـ…`)}</h2>
      <p class="tkd-muted">${TKD.t('Opens this kick (and the ones before it). Useful when a child already knows a kick from class.', 'بيفتح الركلة دي (واللي قبلها). مفيد لو الطفل عارف الركلة من التمرين.')}</p>
      <div class="tkd-col">${GameConfig.SKILL_ORDER.map((sk, i) => `<button type="button" class="btn" data-sk="${sk}">${i + 1}. ${TKD.skillName(sk)}</button>`).join('')}</div>
      <label class="tkd-check"><input type="checkbox" id="co-skip" checked> ${TKD.t('Mark warm-up and lesson as done', 'اعتبر الإحماء والدرس خلصوا')}</label>
      <div class="tkd-row"><button type="button" class="btn" data-x>${TKD.t('Cancel', 'إلغاء')}</button></div></div>`;
    document.body.appendChild(ov);
    ov.querySelector('[data-x]').addEventListener('click', () => ov.remove());
    ov.querySelectorAll('[data-sk]').forEach(b => b.addEventListener('click', () => {
      const sk = b.dataset.sk, skip = ov.querySelector('#co-skip').checked;
      const key = GameState.storageKey(p.id);
      const gs = TKD.gs();
      if (PlayerSystem.getCurrentPlayerId() === p.id) gs.saveToStorage();
      const save = TKD.read(key, null) || PlayerSystem.rebuildState(p.id) || {};
      const order = GameConfig.SKILL_ORDER, idx = order.indexOf(sk);
      save.unlockedSkills = [...new Set([...(save.unlockedSkills || ['apchagi']), ...order.slice(0, idx + 1)])];
      save.currentSkill = sk;
      save.skillGameScores = save.skillGameScores || {};
      save.completedGames = save.completedGames || [];
      if (skip) {
        const s = (save.skillGameScores[sk] = save.skillGameScores[sk] || {});
        s.warmup = Math.max(s.warmup || 0, 100); s.learning = Math.max(s.learning || 0, 100);
        save.completedGames = [...new Set([...save.completedGames, `learning:${sk}`, 'learning'])];
      }
      TKD.write(key, save);
      if (PlayerSystem.getCurrentPlayerId() === p.id) gs.switchPlayer(p.id);
      ov.remove();
      TKD.toast(TKD.t(`🎯 ${p.name} → ${TKD.skillName(sk)}`, `🎯 ${p.name} ← ${TKD.skillName(sk)}`), 'success');
      this.render();
    }));
  },

  // ---------- import player cards (camera / paste / picture)
  importHTML() {
    const cam = 'BarcodeDetector' in window;
    const cards = Object.values(GymBoard.load().cards);
    return `<div class="co-import">
        ${cam ? `<div class="co-cam"><video id="co-video" playsinline muted></video><div class="co-cam-frame"></div>
          <button type="button" class="btn btn-success" id="co-cam-btn">📷 ${TKD.t('Start camera', 'شغّل الكاميرا')}</button></div>`
          : `<p class="tkd-muted">📷 ${TKD.t("This browser can't read QR codes with the camera — paste the code instead (players can copy it from their card).", 'المتصفح ده مبيقراش QR بالكاميرا — الصق الكود بدل كده (اللاعب يقدر ينسخه من الكارت بتاعه).')}</p>`}
        <label class="co-paste"><span>${TKD.t('…or paste a code', '…أو الصق الكود')}</span><textarea id="co-code" rows="2" placeholder="TKD1…"></textarea></label>
        <div class="tkd-row wrap"><button type="button" class="btn btn-success btn-small" id="co-add">➕ ${TKD.t('Add', 'ضيف')}</button>
          ${cam ? `<label class="btn btn-small co-file">🖼️ ${TKD.t('From a picture', 'من صورة')}<input type="file" accept="image/*" id="co-file" hidden></label>` : ''}</div>
        <h3 class="lg-sub">${TKD.t('Cards on this device', 'الكروت اللي على الجهاز ده')} (${TKD.num(cards.length)})</h3>
        <div id="co-cards-box">${this.cardsHTML(cards)}</div>
      </div>`;
  },
  cardsHTML(cards = Object.values(GymBoard.load().cards)) {
    const day = (d) => { try { return new Date(d + 'T12:00:00').toLocaleDateString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short' }); } catch (e) { return d; } };
    return cards.length ? `<ul class="co-cards">${cards.map(c => `<li>${TKD.avatar({ character: c.c })}<b>${TKD.esc(c.n)}</b><small>${League.TIERS[c.t || 0].icon} ${TKD.count(c.wp, 'pt')} · ${TKD.t('card from', 'كارت يوم')} ${day(c.d)}</small><button type="button" data-rm="${c.id}" aria-label="${TKD.t('Remove', 'شيله')}">✖</button></li>`).join('')}</ul>`
      : `<p class="lg-empty">${TKD.t('No cards yet — scan a player card from another phone.', 'لسه مفيش كروت — امسح كارت لاعب من موبايل تاني.')}</p>`;
  },
  bind_import(root) {
    const take = (text) => {
      const card = PlayerCard.decode(text);
      if (!card) { TKD.toast(TKD.t('❌ Not a player card', '❌ ده مش كارت لاعب'), 'error'); return false; }
      const r = GymBoard.add(card);
      TKD.gs()?.playSound('success');
      TKD.toast(r === 'older' ? TKD.t(`${card.n}: a newer card is already saved`, `${card.n}: فيه كارت أحدث متسجل`) : TKD.t(`✅ ${card.n} added to the gym leaderboard`, `✅ ${card.n} اتضاف لترتيب الصالة`), 'success');
      const box = TKD.$('co-cards-box'); if (box) box.innerHTML = this.cardsHTML();   // the list updates while the camera keeps scanning
      return true;
    };
    TKD.$('co-add')?.addEventListener('click', () => { if (take(TKD.$('co-code').value)) TKD.$('co-code').value = ''; });
    TKD.$('co-cards-box')?.addEventListener('click', (e) => { const b = e.target.closest('[data-rm]'); if (!b) return; GymBoard.remove(b.dataset.rm); TKD.$('co-cards-box').innerHTML = this.cardsHTML(); });
    TKD.$('co-file')?.addEventListener('change', async (e) => {
      const f = e.target.files?.[0]; if (!f) return;
      try {
        const det = new BarcodeDetector({ formats: ['qr_code'] });
        const res = await det.detect(await createImageBitmap(f));
        if (!res.length || !take(res[0].rawValue)) TKD.toast(TKD.t('No card found in the picture', 'ملقيناش كارت في الصورة'), 'warning');
      } catch (err) { TKD.toast(TKD.t('Could not read the picture', 'مقدرناش نقرا الصورة'), 'error'); }
    });
    TKD.$('co-cam-btn')?.addEventListener('click', () => this.startCamera(take));
  },
  async startCamera(take) {
    const v = TKD.$('co-video'); if (!v) return;
    try {
      this.stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      v.srcObject = this.stream; await v.play();
      TKD.$('co-cam-btn').hidden = true;
      const det = new BarcodeDetector({ formats: ['qr_code'] });
      const seen = new Set();
      this._scan = setInterval(async () => {
        try {
          const res = await det.detect(v);
          res.forEach(r => { if (!seen.has(r.rawValue)) { seen.add(r.rawValue); take(r.rawValue); } });
        } catch (e) {}
      }, 400);
    } catch (e) { TKD.toast(TKD.t('Camera not available', 'الكاميرا مش متاحة'), 'error'); }
  },
  stopCamera() { clearInterval(this._scan); this.stream?.getTracks().forEach(t => t.stop()); this.stream = null; },

  // ---------- voice recording (record the game's Egyptian lines on this phone)
  voiceHTML() {
    return `<div class="co-voice">
      <p class="tkd-muted">${TKD.t("Record the game's lines in your own voice — right here, no computer needed. Recordings stay on this device and play instead of the phone voice.", 'سجّل جمل اللعبة بصوتك من هنا على طول — مش محتاج كومبيوتر. التسجيلات بتفضل على الجهاز ده وبتتسمع بدل صوت الموبايل.')}</p>
      ${VoiceRecorder.supported() ? '' : `<p class="co-voice-warn">⚠️ ${TKD.t("This browser can't record audio.", 'المتصفح ده مايقدرش يسجّل صوت.')}</p>`}
      <div class="co-voice-progress" id="vr-prog"></div>
      <div class="co-voice-export"><button type="button" class="btn btn-small btn-success" id="vr-export">⬇️ ${TKD.t('Download all recordings (.zip)', 'نزّل كل التسجيلات (zip)')}</button>
        <small class="tkd-muted">${TKD.t('Unzip it into the game folder assets/audio/ — then every phone that gets the game hears your voice.', 'فك الملف جوه فولدر اللعبة assets/audio/ — وبكده كل موبايل ينزل اللعبة هيسمع صوتك.')}</small></div>
      <div class="co-voice-filters" id="vr-filters"></div>
      <ul class="co-voice-list" id="vr-list"><li class="tkd-muted">${TKD.t('Loading…', 'بيحمّل…')}</li></ul>
    </div>`;
  },
  async bind_voice(root) {
    if (!window.VoiceRecorder) return;
    const state = { group: 'all', onlyMissing: false, top: false };
    const lines = await VoiceRecorder.lines();
    // v55: the parts of the checklist in words a coach understands
    const VOICE_GROUPS = { cue: ['Short cheers & commands', 'تشجيع وأوامر قصيرة'], kick: ['Kick names', 'أسماء الركلات'], phase: ['Lesson steps', 'شرح المراحل'],
      hint: ['Game hints', 'تلميحات الألعاب'], warmup: ['Warm-up', 'الإحماء'], cooldown: ['Cool-down', 'التهدئة'], 'error-hunt': ["Mistake Hunter hints", 'تلميحات صيّاد الأخطاء'],
      screen: ['Screen instructions', 'تعليمات الشاشات'], quiz: ['Test questions', 'أسئلة الاختبار'], 'quiz-blast': ['Quiz Blast questions', 'أسئلة كويز الفضاء'] };
    if (!TKD.$('vr-list')) return; // the coach switched away before the script finished loading
    const groups = [...new Set(lines.map(l => l.group))];

    const paintProgress = async () => {
      const { recorded, total } = await VoiceRecorder.count();
      const pct = total ? Math.round(recorded / total * 100) : 0;
      TKD.$('vr-prog').innerHTML = `<div class="vr-bar"><div class="vr-bar-fill" style="width:${pct}%"></div></div>
        <span>${TKD.t(`${recorded} / ${total} recorded`, `${TKD.num(recorded)} / ${TKD.num(total)} متسجلين`)}</span>`;
    };
    const rowHTML = (l) => {
      const recorded = VoiceRecorder.has(l.key);
      return `<li class="vr-row ${recorded ? 'is-on' : ''}" data-key="${l.key}">
        <span class="vr-badge">${recorded ? '✅' : '⚪'}</span>
        <span class="vr-text"><b>${TKD.esc(l.ar)}</b><small>${TKD.esc(l.en)}</small></span>
        <span class="vr-actions">
          ${recorded ? `<button type="button" class="btn btn-small" data-act="play">▶️</button>` : ''}
          <button type="button" class="btn btn-small" data-act="rec">🎤</button>
          ${recorded ? `<button type="button" class="btn btn-small btn-danger" data-act="del">🗑️</button>` : ''}
        </span></li>`;
    };
    const paintList = () => {
      const filtered = lines.filter(l => (state.group === 'all' || l.group === state.group) && (!state.onlyMissing || !VoiceRecorder.has(l.key)) && (!state.top || l.priority === 1));
      TKD.$('vr-list').innerHTML = filtered.length ? filtered.map(rowHTML).join('') : `<li class="tkd-muted">${TKD.t('Nothing here.', 'مفيش حاجة هنا.')}</li>`;
    };
    TKD.$('vr-filters').innerHTML = `
      <select id="vr-group"><option value="all">${TKD.t('All parts', 'كل الأجزاء')}</option>${groups.map(g => `<option value="${g}">${TKD.esc(TKD.t(...(VOICE_GROUPS[g] || [g, g])))}</option>`).join('')}</select>
      <label class="tkd-row" style="gap:4px"><input type="checkbox" id="vr-missing"> ${TKD.t("Only what's missing", 'اللي لسه ناقص بس')}</label>
      <label class="tkd-row" style="gap:4px"><input type="checkbox" id="vr-top"> ⭐ ${TKD.t('Most important first', 'الأهم بس')} (${TKD.num(lines.filter(l => l.priority === 1).length)})</label>`;
    TKD.$('vr-group').addEventListener('change', e => { state.group = e.target.value; paintList(); });
    TKD.$('vr-export')?.addEventListener('click', async () => {
      const n = await VoiceRecorder.exportPack();
      TKD.toast(n ? TKD.t(`⬇️ ${n} recordings saved in one .zip`, `⬇️ اتحفظ ${TKD.count(n, 'thing', 'ar')} في ملف zip واحد`) : TKD.t('Nothing recorded yet.', 'لسه مفيش تسجيلات.'), n ? 'success' : 'info');
    });
    TKD.$('vr-missing').addEventListener('change', e => { state.onlyMissing = e.target.checked; paintList(); });
    TKD.$('vr-top').addEventListener('change', e => { state.top = e.target.checked; paintList(); });

    let activeAudio = null;
    TKD.$('vr-list').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-act]'); if (!btn) return;
      const li = btn.closest('.vr-row'); const key = li.dataset.key;
      const line = lines.find(l => l.key === key); if (!line) return;
      if (btn.dataset.act === 'rec') {
        if (VoiceRecorder.recording() === key) {
          clearTimeout(this._recCap);
          await VoiceRecorder.stop(true); li.outerHTML = rowHTML(line); await paintProgress();
        } else if (VoiceRecorder.recording()) {
          TKD.toast(TKD.t('Stop the line you are recording first (⏹️).', 'وقّف الجملة اللي بتسجلها الأول (⏹️).'), 'info');
        } else {
          if (!VoiceRecorder.supported()) { TKD.toast(TKD.t('Recording is not supported here', 'التسجيل مش متاح هنا'), 'error'); return; }
          try {
            await VoiceRecorder.start(key); li.classList.add('is-recording'); btn.textContent = '⏹️';
            // a forgotten recording stops (and is kept) by itself after 30 seconds
            clearTimeout(this._recCap);
            this._recCap = setTimeout(async () => { if (VoiceRecorder.recording() !== key) return; await VoiceRecorder.stop(true); const row = document.querySelector(`.vr-row[data-key="${key}"]`); if (row) row.outerHTML = rowHTML(line); await paintProgress(); }, 30000);
          } catch (err) { TKD.toast(TKD.t('Could not use the microphone', 'ماقدرناش نستخدم المايك'), 'error'); }
        }
      } else if (btn.dataset.act === 'play') {
        activeAudio?.pause(); const url = VoiceRecorder.urlFor(key); if (!url) return;
        activeAudio = new Audio(url); activeAudio.play().catch(() => {});
      } else if (btn.dataset.act === 'del') {
        if (!(await tkdConfirm(TKD.t('Delete this recording?', 'تمسح التسجيل ده؟')))) return;
        await VoiceRecorder.remove(key); li.outerHTML = rowHTML(line); await paintProgress();
      }
    });
    paintList(); await paintProgress();
  },

  // ---------- settings
  settingsHTML() {
    const s = League.settings();
    const sel = (id, vals, cur) => `<select id="${id}">${vals.map(v => `<option value="${v}" ${v === cur ? 'selected' : ''}>${TKD.num(v)}</option>`).join('')}</select>`;
    return `<div class="co-settings">
      <label>🏆 ${TKD.t('Counted challenge tries per day', 'عدد محاولات التحدي المحسوبة في اليوم')} ${sel('co-tries', [1, 2, 3, 4, 5], s.tries)}</label>
      <label>⬆️ ${TKD.t('Players promoted per league each week', 'عدد اللي بيطلعوا من كل دوري كل أسبوع')} ${sel('co-promote', [1, 2, 3, 4, 5], s.promote)}</label>
      <label>🎯 ${TKD.t('Minimum points to go up', 'أقل نقط عشان يطلع')} ${sel('co-min', [0, 50, 100, 150, 200, 300, 400], s.minPoints)}</label>
      <label>🏅 ${TKD.t('Medal difficulty', 'صعوبة الميداليات')} <select id="co-medals">${[['easy', TKD.t('Easier', 'أسهل')], ['normal', TKD.t('Normal', 'عادي')], ['hard', TKD.t('Harder', 'أصعب')]].map(([v, l]) => `<option value="${v}" ${s.medals === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label>
      <p class="tkd-muted">${TKD.t('Easier = ×0.7, harder = ×1.4 on the medals you earn by training (warm-ups, games, days…). Skill medals like strongest kick don\'t change.', 'أسهل = ×٠٫٧، أصعب = ×١٫٤ على ميداليات التمرين (إحماء، ألعاب، أيام…). ميداليات المهارة زي أقوى ركلة مابتتغيرش.')}</p>
      <label>🐢 ${TKD.t('Game pace', 'إيقاع الألعاب')} <select id="co-pace">${TKDPace.LIST.map(([v, en, ar]) => `<option value="${v}" ${s.pace === v ? 'selected' : ''}>${TKD.t(en, ar)}</option>`).join('')}</select></label>
      <p class="tkd-muted">${TKD.t('How fast notes, answers, targets and timers move in every game on this device. Calm gives children more time to see, read and react; each child can still pick Easy / Normal / Hard inside a game.', 'سرعة النوتات والإجابات والأهداف والعدادات في كل الألعاب على الجهاز ده. "هادي" بيدي الأطفال وقت أكتر يشوفوا ويقروا ويردوا، وكل طفل لسه يقدر يختار سهل / عادي / صعب جوه اللعبة.')}</p>
      <details class="co-pace-players" ${PlayerSystem.getPlayers().some(p => p.pace) ? 'open' : ''}>
        <summary>👧👦 ${TKD.t('Pace for each player', 'إيقاع لكل لاعب')}</summary>
        <p class="tkd-muted">${TKD.t('Overrides the pace above for one child. Saved straight away.', 'بيغلب الإيقاع اللي فوق لطفل واحد بس. بيتحفظ على طول.')}</p>
        <div class="co-pace-list">${PlayerSystem.getPlayers().map(p => this.paceRow(p)).join('') || `<p class="tkd-muted">${TKD.t('No players yet.', 'مفيش لاعبين لسه.')}</p>`}</div>
        <p class="tkd-muted">${TKD.t('⚡ = average reaction time in the quick games (Sparring, Target Paddles, Quiz Blast, Mistake Hunter). 🦵 = the leg the child kicks with — the 3D character mirrors for left-footers.', '⚡ = متوسط سرعة رد الفعل في الألعاب السريعة (النزال، مضارب الأهداف، كويز الفضاء، صيّاد الأخطاء). 🦵 = الرجل اللي الطفل بيركل بيها — الشخصية الـ3D بتتعكس للي بيركل بالشمال.')}</p>
      </details>
      <p class="co-autosave">✅ ${TKD.t('Every change is saved straight away.', 'أي تغيير بيتحفظ على طول.')}</p>
      <section class="co-data" id="co-data"><h3>💾 ${TKD.t('Data on this device', 'البيانات اللي على الجهاز')}</h3>
        <div class="tkd-row wrap">
          <button type="button" class="btn btn-small btn-success" id="co-backup">⬇️ ${TKD.t('Save a backup', 'احفظ نسخة احتياطية')}</button>
          <label class="btn btn-small co-file">📂 ${TKD.t('Restore a backup', 'رجّع نسخة احتياطية')}<input type="file" accept="application/json,.json" id="co-restore" hidden></label>
        </div>
        <p class="tkd-muted">${TKD.t('The backup holds every player, score and setting — keep it somewhere safe (WhatsApp to yourself, Drive…).', 'النسخة فيها كل اللاعبين والنتايج والإعدادات — احفظها في مكان أمان (ابعتها لنفسك واتساب، أو على درايف…).')}</p>
      </section>
      <div class="tkd-row wrap">
        <button type="button" class="btn btn-small" id="co-newpin">🔑 ${TKD.t('Change PIN', 'غيّر الرقم السري')}</button>
        <button type="button" class="btn btn-small btn-danger" id="co-reset-league">↺ ${TKD.t('Everyone back to Bronze', 'رجّع الكل للبرونز')}</button>
        <button type="button" class="btn btn-small btn-danger" id="co-erase">🗑️ ${TKD.t('Erase everything', 'امسح كل حاجة')}</button></div></div>`;
  },
  // v45: one child's row — pace, kicking leg, measured reaction time and a suggested pace
  paceRow(p) {
    const R = window.ReactionLog?.summary(p.id), name = v => { const L = TKDPace.LIST.find(x => x[0] === v); return L ? TKD.t(L[1], L[2]) : v; };
    let info = `<span class="co-rt muted">⚡ ${TKD.t('not enough play yet', 'لسه مالعبش كفاية')}</span>`;
    if (R) {
      const pct = Math.round((R.ratio - 1) * 100), feel = pct > 30 ? TKD.t('needs more time', 'محتاج وقت أكتر') : pct < -22 ? TKD.t('very quick', 'سريع جدًا') : TKD.t('on track', 'تمام');
      const cur = p.pace || League.settings().pace || 'normal';
      info = `<span class="co-rt">⚡ ${feel} <small>(${pct > 0 ? '+' : ''}${pct}% · ${R.n} ${TKD.t('tries', 'محاولة')})</small>${R.suggest !== cur ? ` <button type="button" class="co-rt-apply" data-rt-pid="${p.id}" data-rt-v="${R.suggest}">💡 ${TKD.t('Try', 'جرّب')} ${name(R.suggest)}</button>` : ''}</span>`;
    }
    return `<div class="co-pace-row">${TKD.avatar(p, 'sm')}<span>${TKD.esc(p.name)}</span>
          <select data-pace-pid="${p.id}" aria-label="${TKD.t('Pace', 'الإيقاع')}"><option value="">${TKD.t('Same as device', 'زي الجهاز')}</option>${TKDPace.LIST.map(([v, en, ar]) => `<option value="${v}" ${p.pace === v ? 'selected' : ''}>${TKD.t(en, ar)}</option>`).join('')}</select>
          <select data-leg-pid="${p.id}" aria-label="${TKD.t('Kicking leg', 'رجل الركل')}"><option value="right">🦵 ${TKD.t('Right', 'يمين')}</option><option value="left" ${p.kickLeg === 'left' ? 'selected' : ''}>🦵 ${TKD.t('Left', 'شمال')}</option></select>
          ${info}</div>`;
  },
  bind_settings() {
    const saveLeague = () => {
      const st = League.load();
      st.settings = { tries: +TKD.$('co-tries').value, promote: +TKD.$('co-promote').value, minPoints: +TKD.$('co-min').value, medals: TKD.$('co-medals').value, pace: TKD.$('co-pace')?.value || 'normal' };
      League.save(st); TKD.toast(TKD.t('✅ Saved', '✅ اتحفظ'), 'success');
    };
    ['co-tries', 'co-promote', 'co-min', 'co-medals', 'co-pace'].forEach(id => TKD.$(id)?.addEventListener('change', saveLeague));
    TKD.$('co-backup').addEventListener('click', () => exportProgress());
    TKD.$('co-restore').addEventListener('change', (e) => importProgress(e.target));
    TKD.$('co-erase').addEventListener('click', () => hardResetGame());
    if (this._focusData) { this._focusData = false; const d = TKD.$('co-data'); d?.scrollIntoView({ block: 'center' }); d?.classList.add('co-flash'); }
    document.querySelectorAll('[data-pace-pid]').forEach(sel => sel.addEventListener('change', () => {
      PlayerSystem.updatePlayer(sel.dataset.pacePid, { pace: sel.value || null });
      TKD.toast(TKD.t('✅ Saved', '✅ اتحفظ'), 'success');
    }));
    document.querySelectorAll('[data-leg-pid]').forEach(sel => sel.addEventListener('change', () => {
      PlayerSystem.updatePlayer(sel.dataset.legPid, { kickLeg: sel.value === 'left' ? 'left' : 'right' });
      TKD.toast(TKD.t('✅ Saved', '✅ اتحفظ'), 'success');
    }));
    document.querySelectorAll('[data-rt-pid]').forEach(b => b.addEventListener('click', () => {
      PlayerSystem.updatePlayer(b.dataset.rtPid, { pace: b.dataset.rtV });
      const sel = document.querySelector(`[data-pace-pid="${b.dataset.rtPid}"]`); if (sel) sel.value = b.dataset.rtV;
      b.remove(); TKD.toast(TKD.t('✅ Saved', '✅ اتحفظ'), 'success');
    }));
    TKD.$('co-newpin').addEventListener('click', () => { const c = TKD.read(this.KEY, {}); delete c.pin; TKD.write(this.KEY, c); this.unlocked = false; this.render(); });
    TKD.$('co-reset-league').addEventListener('click', async () => {
      if (!(await tkdConfirm(TKD.t('Put every player back in the Bronze league?', 'ترجّع كل اللاعبين لدوري البرونز؟')))) return;
      PlayerSystem.getPlayers().forEach(p => PlayerSystem.updatePlayer(p.id, { tier: 0 }));
      TKD.toast(TKD.t('Done', 'تمام'), 'success');
    });
  }
};
window.Coach = Coach;

// =====================================================================
// WIRING
// =====================================================================
window.TKDScreens = {
  league: () => LeagueScreen.init(),
  coach: () => Coach.init(),
  versus: (gs) => window.Versus?.init(gs)
};
GameConfig.BACKGROUNDS.LEAGUE = 'assets/images/backgrounds/arena_bg.webp';
GameConfig.BACKGROUNDS.COACH = 'assets/images/backgrounds/dojo_interior_bg.webp';
GameConfig.BACKGROUNDS.VERSUS = 'assets/images/backgrounds/sparring_training_bg.webp';

Challenge.wrapLogging();
document.addEventListener('tkd:screen', (e) => {
  const id = e.detail.screenId;
  if (Challenge.active && id !== Challenge.active.gameId && id !== 'winner') Challenge.end();
  if (id !== 'coach') { Coach.stopCamera(); Coach.away(id); } else Coach.back();
  TKDHints.hide();
  TKDHints.mountReadAloud();
  TKDHints.maybeShow(id);
});
document.addEventListener('tkd:player-changed', () => { if (document.querySelector('#home-screen.active')) HomeHub.render(); });
// v55: the phone put away for 2 minutes or more → the coach page locks itself
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') { Coach._hiddenAt = Date.now(); if (window.VoiceRecorder?.recording()) VoiceRecorder.cancel(); return; }
  if (Coach.unlocked && Coach._hiddenAt && Date.now() - Coach._hiddenAt > 2 * 60e3) { Coach.lock(); if (document.querySelector('#coach-screen.active')) Coach.render(); }
  Coach._hiddenAt = 0;
});
document.addEventListener('DOMContentLoaded', () => TKDHints.mountReadAloud());

// keep the hub + open screens in the current language
(function wrapLanguage() {
  const orig = GameState.prototype.applyLanguage;
  GameState.prototype.applyLanguage = function () {
    const r = orig.apply(this, arguments);
    try {
      if (document.querySelector('#home-screen.active')) HomeHub.render();
      if (document.querySelector('#league-screen.active')) LeagueScreen.render();
      if (document.querySelector('#coach-screen.active')) Coach.render();
      if (!TKD.$('start-screen')?.hidden) StartScreen.render();
      if (document.querySelector('#versus-screen.active')) window.Versus?.refresh?.();
    } catch (e) {}
    return r;
  };
})();

// #####################################################################
// ## social/versus.js
// #####################################################################
/* =====================================================================
   TAEKWONDO JOURNEY — 1 × 1 DUEL + KNOCKOUT TOURNAMENT (v23)
   Two players on ONE screen. A referee board announces an opening; the
   first player to kick a LEGAL target for the chosen kick scores
   (+2 body / +3 head). Kicking a trap (leg = below the belt, a covered
   target) or kicking before the signal gives the other player +1.
   First to 10, or the leader after 12 exchanges (tie → golden point).
   Tournament: 3–8 registered players, random bracket, byes, champion badge.
   Loaded after competition.js.
   ===================================================================== */

const Versus = {
  KEY: 'taekwondoJourneyVersus',
  TKEY: 'taekwondoJourneyTournament',
  mode: 'friendly',            // friendly | tournament
  sel: { p1: null, p2: null, skill: 'apchagi', picks: [] },
  WIN_POINTS: 10, MAX_EX: 12,
  VALID: { apchagi: ['body', 'head'], narochagi: ['head'], bakchagi3: ['body'] },
  LABEL: { head: { en: 'HEAD', ar: 'الراس', icon: '🎯' }, body: { en: 'BODY', ar: 'الجسم', icon: '🎯' }, leg: { en: 'LEG', ar: 'الرجل', icon: '🦵' }, covered: { en: 'COVERED', ar: 'متغطي', icon: '🛡️' } },

  load() { return TKD.read(this.KEY, { matches: [], champions: [] }); },
  save(d) { TKD.write(this.KEY, d); },
  tour() { return TKD.read(this.TKEY, null); },
  saveTour(t) { TKD.write(this.TKEY, t); },

  standings() {
    const players = PlayerSystem.getPlayers(); const by = {};
    this.load().matches.forEach(m => {
      [['p1', 's1'], ['p2', 's2']].forEach(([k, s]) => {
        const id = m[k]?.id; if (!id || !players.find(p => p.id === id)) return;
        const r = (by[id] ||= { p: players.find(p => p.id === id), w: 0, l: 0, pts: 0 });
        r.pts += m[s];
        if (m.winner === id) r.w++; else if (m.winner) r.l++;
      });
    });
    return Object.values(by).sort((a, b) => b.w - a.w || a.l - b.l || b.pts - a.pts);
  },
  champions() {
    const players = PlayerSystem.getPlayers();
    return this.load().champions.slice().reverse().map(c => ({ ...c, p: players.find(p => p.id === c.id) || { name: c.pname } }));
  },

  init() {
    this.teardown();
    const t = this.tour();
    if (t && !t.done) this.mode = 'tournament';
    this.renderSetup();
  },
  refresh() { if (this.view === 'match') this.renderPads(); else if (this.view === 'bracket') this.renderBracket(); else this.renderSetup(); },

  // ------------------------------------------------------------ setup
  renderSetup() {
    this.view = 'setup';
    const root = TKD.$('vs-root'); if (!root) return;
    const players = PlayerSystem.getPlayers();
    const t = this.tour();
    if (!this.sel.p1) this.sel.p1 = PlayerSystem.getCurrentPlayerId() || 'guest1';
    if (!this.sel.p2) this.sel.p2 = players.find(p => p.id !== this.sel.p1)?.id || 'guest2';
    const opt = (slot) => {
      const list = [...players.map(p => ({ id: p.id, p })), { id: slot === 'p1' ? 'guest1' : 'guest2', p: { name: slot === 'p1' ? TKD.t('Guest 1', 'ضيف ١') : TKD.t('Guest 2', 'ضيف ٢'), character: slot === 'p1' ? 'boy' : 'girl' } }];
      return `<div class="vs-pick ${slot}"><h4>${slot === 'p1' ? `🔵 ${TKD.t('Player 1', 'اللاعب ١')}` : `🔴 ${TKD.t('Player 2', 'اللاعب ٢')}`}</h4>
        <div class="vs-pick-list">${list.map(({ id, p }) => `<button type="button" class="vs-chip ${this.sel[slot] === id ? 'on' : ''}" data-slot="${slot}" data-id="${id}" ${(slot === 'p1' ? this.sel.p2 : this.sel.p1) === id ? 'disabled' : ''}>${TKD.avatar(p)}<span>${TKD.esc(p.name)}</span></button>`).join('')}</div></div>`;
    };
    const kicks = `<div class="vs-kicks">${GameConfig.SKILL_ORDER.map(sk => `<button type="button" class="vs-chip ${this.sel.skill === sk ? 'on' : ''}" data-skill="${sk}">🥋 ${TKD.skillName(sk)}</button>`).join('')}</div>`;
    const tabs = `<div class="lg-tabs"><button type="button" class="${this.mode === 'friendly' ? 'on' : ''}" data-mode="friendly">⚔️ ${TKD.t('Friendly match', 'مباراة ودية')}</button>
      <button type="button" class="${this.mode === 'tournament' ? 'on' : ''}" data-mode="tournament">👑 ${TKD.t('Tournament', 'بطولة')}</button></div>`;
    let body;
    if (this.mode === 'friendly') {
      body = `<div class="vs-setup">${opt('p1')}<div class="vs-vs">VS</div>${opt('p2')}</div>
        <h4 class="vs-h">${TKD.t('Kick for this match', 'الركلة في المباراة دي')}</h4>${kicks}
        <p class="tkd-muted">${TKD.t('Hold the tablet between you. Player 1 taps the blue side (or A), player 2 the red side (or L).', 'امسكوا التابلت بينكم. اللاعب ١ يدوس على الأزرق (أو حرف A)، واللاعب ٢ على الأحمر (أو حرف L).')}</p>
        <button type="button" class="btn btn-success vs-start" id="vs-go">⚔️ ${TKD.t('Start the duel', 'ابدأ المواجهة')}</button>`;
    } else if (t) {                                   // running, or finished and not cleared yet
      body = `<div id="vs-bracket-inline"></div>`;
    } else {
      if (!this.sel.picks.length) this.sel.picks = players.slice(0, 8).map(p => p.id);
      body = `<h4 class="vs-h">${TKD.t('Who is in? (3 to 8 players)', 'مين داخل البطولة؟ (من ٣ لـ ٨ لاعبين)')}</h4>
        <div class="vs-pick-list">${players.map(p => `<button type="button" class="vs-chip ${this.sel.picks.includes(p.id) ? 'on' : ''}" data-pick="${p.id}">${TKD.avatar(p)}<span>${TKD.esc(p.name)}</span></button>`).join('')}</div>
        ${players.length < 3 ? `<p class="tkd-muted">⚠️ ${TKD.t('Register at least 3 players first.', 'سجّل ٣ لاعبين على الأقل الأول.')}</p>` : ''}
        <h4 class="vs-h">${TKD.t('Kick for the tournament', 'الركلة في البطولة')}</h4>${kicks}
        <button type="button" class="btn btn-success vs-start" id="vs-tour-go" ${this.sel.picks.length < 3 ? 'disabled' : ''}>👑 ${TKD.t(`Start the tournament (${this.sel.picks.length})`, `ابدأ البطولة (${TKD.num(this.sel.picks.length)})`)}</button>`;
    }
    root.innerHTML = tabs + body;
    root.querySelectorAll('[data-mode]').forEach(b => b.addEventListener('click', () => { this.mode = b.dataset.mode; this.renderSetup(); }));
    root.querySelectorAll('[data-slot]').forEach(b => b.addEventListener('click', () => { this.sel[b.dataset.slot] = b.dataset.id; TKD.gs()?.playSound('click'); this.renderSetup(); }));
    root.querySelectorAll('[data-skill]').forEach(b => b.addEventListener('click', () => { this.sel.skill = b.dataset.skill; this.renderSetup(); }));
    root.querySelectorAll('[data-pick]').forEach(b => b.addEventListener('click', () => {
      const id = b.dataset.pick, l = this.sel.picks;
      this.sel.picks = l.includes(id) ? l.filter(x => x !== id) : (l.length < 8 ? [...l, id] : l);
      this.renderSetup();
    }));
    TKD.$('vs-go')?.addEventListener('click', () => this.startMatch(this.who(this.sel.p1, 'p1'), this.who(this.sel.p2, 'p2'), this.sel.skill));
    TKD.$('vs-tour-go')?.addEventListener('click', () => this.createTournament());
    if (TKD.$('vs-bracket-inline')) this.renderBracket(TKD.$('vs-bracket-inline'));
  },
  who(id, slot) {
    const p = PlayerSystem.getPlayers().find(x => x.id === id);
    if (p) return { id: p.id, name: p.name, character: p.character || 'boy' };
    return { id: null, name: slot === 'p1' ? TKD.t('Guest 1', 'ضيف ١') : TKD.t('Guest 2', 'ضيف ٢'), character: slot === 'p1' ? 'boy' : 'girl' };
  },

  // ------------------------------------------------------------ tournament
  createTournament() {
    const ids = AG.shuffle(this.sel.picks);
    const size = ids.length <= 4 ? 4 : 8;
    const slots = [...ids, ...new Array(size - ids.length).fill(null)];
    // spread byes: pair a player with a bye rather than two byes together
    const first = [];
    for (let i = 0; i < size / 2; i++) first.push({ a: slots[i], b: slots[size - 1 - i], winner: null });
    const rounds = [first];
    for (let n = size / 4; n >= 1; n /= 2) rounds.push(new Array(n).fill(0).map(() => ({ a: null, b: null, winner: null })));
    const d = new Date();
    const t = { id: 't' + Date.now(), name: TKD.t(`Cup ${d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}`, `كأس ${d.toLocaleDateString('ar-EG', { day: 'numeric', month: 'long' })}`), skill: this.sel.skill, rounds, done: false, champion: null };
    this.advanceByes(t);
    this.saveTour(t);
    TKD.gs()?.playSound('success');
    this.renderSetup();
  },
  advanceByes(t) {
    let changed = true;
    while (changed) {
      changed = false;
      t.rounds.forEach((round, ri) => round.forEach((m, mi) => {
        if (m.winner) return;
        const aDone = ri === 0 || t.rounds[ri - 1][mi * 2].winner !== null;
        const bDone = ri === 0 || t.rounds[ri - 1][mi * 2 + 1].winner !== null;
        if (!aDone || !bDone) return;
        if (m.a && !m.b) { m.winner = m.a; changed = true; }
        else if (!m.a && m.b) { m.winner = m.b; changed = true; }
        else if (!m.a && !m.b && ri > 0) { m.winner = 'bye'; changed = true; }
        if (m.winner) this.propagate(t, ri, mi);
      }));
    }
  },
  propagate(t, ri, mi) {
    const m = t.rounds[ri][mi];
    if (ri === t.rounds.length - 1) { if (m.winner && m.winner !== 'bye') { t.done = true; t.champion = m.winner; } return; }
    const next = t.rounds[ri + 1][Math.floor(mi / 2)];
    const w = m.winner === 'bye' ? null : m.winner;
    if (mi % 2 === 0) next.a = w; else next.b = w;
  },
  nextMatch(t) {
    for (let ri = 0; ri < t.rounds.length; ri++) for (let mi = 0; mi < t.rounds[ri].length; mi++) {
      const m = t.rounds[ri][mi];
      if (!m.winner && m.a && m.b) return { ri, mi, m };
    }
    return null;
  },
  renderBracket(host) {
    const t = this.tour(); if (!t) return this.renderSetup();
    this.view = host ? 'setup' : 'bracket';
    const root = host || TKD.$('vs-root');
    const players = PlayerSystem.getPlayers();
    const name = (id) => id ? TKD.esc(players.find(p => p.id === id)?.name || '?') : `<i>${TKD.t('bye', 'راحة')}</i>`;
    const rn = (ri) => { const left = t.rounds.length - ri; return left === 1 ? TKD.t('Final', 'النهائي') : left === 2 ? TKD.t('Semi-finals', 'قبل النهائي') : TKD.t('Quarter-finals', 'ربع النهائي'); };
    const nm = this.nextMatch(t);
    root.innerHTML = `<div class="vs-tour-head"><h3>👑 ${TKD.esc(t.name)} · ${TKD.skillName(t.skill)}</h3>
        <button type="button" class="btn btn-small btn-danger" id="vs-tour-cancel">✖ ${TKD.t('Cancel tournament', 'الغي البطولة')}</button></div>
      <div class="vs-bracket">${t.rounds.map((round, ri) => `<div class="vs-round"><h4>${rn(ri)}</h4>${round.map((m, mi) => `
        <div class="vs-match ${nm && nm.ri === ri && nm.mi === mi ? 'next' : ''}">
          <span class="${m.winner && m.winner === m.a ? 'win' : ''}">${m.a || ri === 0 ? name(m.a) : '…'}</span>
          <span class="${m.winner && m.winner === m.b ? 'win' : ''}">${m.b || ri === 0 ? name(m.b) : '…'}</span></div>`).join('')}</div>`).join('')}</div>
      ${t.done ? `<div class="vs-champ">🏆 ${TKD.t('Champion', 'البطل')}: <b>${name(t.champion)}</b>
          <button type="button" class="btn btn-small" id="vs-cert">📜 ${TKD.t('Certificate', 'الشهادة')}</button>
          <button type="button" class="btn btn-success btn-small" id="vs-tour-new">${TKD.t('New tournament', 'بطولة جديدة')}</button></div>`
        : nm ? `<button type="button" class="btn btn-success vs-start" id="vs-tour-play">⚔️ ${TKD.t('Next match', 'الماتش الجاي')}: ${name(nm.m.a)} × ${name(nm.m.b)}</button>` : ''}`;
    TKD.$('vs-tour-cancel')?.addEventListener('click', async () => { if (await tkdConfirm(TKD.t('Cancel this tournament?', 'تلغي البطولة دي؟'))) { localStorage.removeItem(this.TKEY); this.renderSetup(); } });
    TKD.$('vs-tour-new')?.addEventListener('click', () => { localStorage.removeItem(this.TKEY); this.renderSetup(); });
    TKD.$('vs-cert')?.addEventListener('click', () => { const p = players.find(x => x.id === t.champion); if (p) Certificates.draw({ icon: '👑', title: TKD.t('Tournament Champion', 'بطل البطولة'), name: p.name, line: t.name, date: TKD.dayKey() }); });
    TKD.$('vs-tour-play')?.addEventListener('click', () => {
      this.tourMatch = { ri: nm.ri, mi: nm.mi };
      this.startMatch(this.who(nm.m.a, 'p1'), this.who(nm.m.b, 'p2'), t.skill);
    });
  },
  finishTourMatch(winnerId) {
    const t = this.tour(); if (!t || !this.tourMatch) return;
    const { ri, mi } = this.tourMatch; this.tourMatch = null;
    t.rounds[ri][mi].winner = winnerId;
    this.propagate(t, ri, mi);
    this.advanceByes(t);
    if (t.done) {
      const d = this.load(); const p = PlayerSystem.getPlayers().find(x => x.id === t.champion);
      d.champions.push({ id: t.champion, pname: p?.name, name: t.name, date: TKD.dayKey() }); this.save(d);
      if (p) PlayerSystem.updatePlayer(p.id, { badges: [...(p.badges || []), { id: 'tournament-champion', week: TKD.dayKey() }], pending: [...(p.pending || []), { id: 'tournament-champion', week: TKD.dayKey() }] });
    }
    this.saveTour(t);
  },

  // ------------------------------------------------------------ match
  async startMatch(p1, p2, skill) {
    TKDHints.hide(); TKDHints.mark('versus');       // no pop-up over a running match
    if (!p1.id && !p2.id && this.tourMatch) return;
    this.teardown();
    this.view = 'match';
    this.P = [p1, p2]; this.skill = skill;
    this.score = [0, 0]; this.ex = 0; this.state = 'intro'; this.signal = null; this.golden = false; this.over = false;
    this.fouled = [false, false];
    const root = TKD.$('vs-root');
    root.innerHTML = `<div class="arena-wrap vs-wrap" id="vs-wrap"><canvas class="arena-canvas" id="vs-canvas" aria-label="Duel"></canvas><div class="arena-ui" id="vs-ui"></div></div>
      <div class="vs-pads" id="vs-pads" dir="ltr"></div>
      <div class="center-buttons"><button type="button" class="btn btn-small" id="vs-quit">✖ ${TKD.t('Stop', 'وقّف')}</button></div>`;
    this.renderPads();
    TKD.$('vs-quit').addEventListener('click', () => { this.teardown(); this.tourMatch = null; this.renderSetup(); });
    this.stage = new ArenaStage(TKD.$('vs-canvas'));
    const mk = (p, mirror) => (window.arenaMakeFighter ? arenaMakeFighter(this.stage, skill, p.character !== 'girl', { mirror, kickLeg: p.kickLeg === 'left' ? 'left' : 'right', cosmetics: !!p.id && p.id === PlayerSystem.getCurrentPlayerId() }) : new ArenaFighter(this.stage, arenaKickFrames(skill, p.character !== 'girl'), { shared: arenaSharedCanvas(skill), mirror }));
    this.F = [mk(p1, false), mk(p2, true)];
    this.stage.onResize = () => this.layout();
    this.stage.start((dt) => this.update(dt), (c, W, H) => this.draw(c, W, H));
    const tok = (this.tok = (this.tok || 0) + 1);
    await Promise.all(this.F.map(f => f.load()));
    if (tok !== this.tok) return;
    this.F.forEach(f => f.setIdle?.('bounce'));       // v45: footwork while they wait
    this.layout();
    this.keyH = (e) => {
      if (!TKD.$('versus-screen')?.classList.contains('active') || this.view !== 'match') return;
      if (e.repeat) return;
      // e.code = the physical key, so A / L work even when the keyboard is switched to Arabic (ش / م)
      const k = e.code;
      if (k === 'KeyA' || k === 'KeyS' || k === 'ShiftLeft') { e.preventDefault(); this.press(0); }
      if (k === 'KeyL' || k === 'KeyK' || k === 'Enter' || k === 'ShiftRight') { e.preventDefault(); this.press(1); }
    };
    document.addEventListener('keydown', this.keyH);
    const st = this.stage;
    st.text(st.W / 2, st.H * 0.4, TKD.t('Kyung-rye!', 'كيونغ ري!'), { size: 34, ttl: 1.1, rise: 8 });
    this.later(() => st.text(st.W / 2, st.H * 0.4, TKD.t('Shijak! 🔔', 'شيجاك! 🔔'), { color: '#ffd166', size: 40, ttl: 1, rise: 8 }), 1100);
    this.later(() => { if (!window.AudioKit?.sfx('gong', { gain: 0.6, vary: 0 })) ArenaSound.tone({ f0: 880, f1: 880, dur: 0.35, type: 'triangle', gain: 0.35 }); this.nextExchange(); }, 1900);
  },
  renderPads() {
    const pads = TKD.$('vs-pads'); if (!pads || !this.P) return;
    pads.innerHTML = this.P.map((p, i) => `<button type="button" class="vs-pad p${i + 1}" data-i="${i}">🦶 ${TKD.esc(p.name)}<small>${i === 0 ? TKD.t('key A', 'زرار A') : TKD.t('key L', 'زرار L')}</small><span class="vs-hint"></span></button>`).join('');
    pads.querySelectorAll('.vs-pad').forEach(b => b.addEventListener('pointerdown', (e) => { e.preventDefault(); b.classList.add('on'); setTimeout(() => b.classList.remove('on'), 120); this.press(+b.dataset.i); }));
  },
  later(fn, ms) { const tok = this.tok; const id = setTimeout(() => { if (tok === this.tok) fn(); }, ms); (this._t ||= []).push(id); },
  teardown() {
    this.tok = (this.tok || 0) + 1;
    (this._t || []).forEach(clearTimeout); this._t = [];
    this.stage?.destroy(); this.stage = null;
    if (this.keyH) document.removeEventListener('keydown', this.keyH); this.keyH = null;
  },
  layout() {
    const st = this.stage; if (!st || !this.F) return;
    const W = st.W, H = st.H, fy = st.floorY();
    const figH = Math.min(H * 0.6, W * 0.34);
    this.F[0].layout(W * 0.28, fy, figH);
    this.F[1].layout(W * 0.72, fy, figH);
    st.spotX = W / 2;
  },
  nextExchange() {
    if (this.over || !this.stage) return;
    const [a, b] = this.score;
    if (!this.golden && (a >= this.WIN_POINTS || b >= this.WIN_POINTS || this.ex >= this.MAX_EX)) {
      if (a === b) { this.golden = true; this.stage.text(this.stage.W / 2, this.stage.H * 0.35, TKD.t('⭐ Golden point!', '⭐ النقطة الدهبية!'), { color: '#ffd166', size: 34, ttl: 1.4 }); }
      else return this.endMatch();
    } else if (this.golden && a !== b) return this.endMatch();
    this.ex++;
    this.state = 'wait'; this.signal = null; this.fouled = [false, false];
    this.later(() => this.openSignal(), AG.rand(1000, 2400));
  },
  openSignal() {
    if (this.state !== 'wait') return;
    const valid = this.VALID[this.skill];
    const trap = Math.random() < 0.35 && this.ex > 1;
    const kind = trap ? AG.pick(['leg', 'covered']) : AG.pick(valid);
    this.signal = { kind, valid: !trap, born: this.stage.time, zone: kind === 'covered' ? AG.pick(valid) : kind };
    this.state = 'open';
    ArenaSound.tone({ f0: 620, f1: 820, dur: 0.08, type: 'sine', gain: 0.22 });
  },
  press(i) {
    if (this.over || this.view !== 'match' || !this.stage) return;
    const other = 1 - i, st = this.stage;
    if (this.state === 'wait') {                       // jumped the gun
      if (this.fouled[i]) return;
      this.fouled[i] = true;
      this.score[other] += 1; this.pop = { i: other, t: 1 };
      ArenaSound.buzz();
      const f = this.F[i]; f.wobble = 0.6;
      st.text(f.x, f.floor - f.height * 1.05, TKD.t('Too early! +1 ⟶', 'بدري! +١ للتاني'), { color: '#ffb3b9', size: 20 });
      return;
    }
    if (this.state !== 'open') return;
    this.state = 'resolving';
    const s = this.signal, rt = st.time - s.born;
    if (s.valid && this.P?.[i]?.id) window.ReactionLog?.add('versus', rt / Math.max(0.2, st.timeScale || 1), this.P[i].id);   // v45
    if (s.valid) {
      const pts = s.kind === 'head' ? 3 : 2;
      const v0 = this.F[other]; this.F[i].aimAt?.(v0.floor - v0.height * (s.kind === 'head' ? 0.86 : 0.6));   // v45: aim at the head / body
      this.kick(i, () => {
        this.score[i] += pts; this.pop = { i, t: 1 };
        const v = this.F[other], hx = v.footScreenX(), hy = v.floor - v.height * (s.kind === 'head' ? 0.86 : 0.6);
        ArenaSound.smack(); ArenaSound.tone({ f0: 1320, f1: 1320, dur: 0.12, type: 'square', gain: 0.12 });
        st.flash('#fff', 0.3); st.shake(s.kind === 'head' ? 11 : 7, 0.28);
        st.ring(hx, hy, i === 0 ? '#4dc9ff' : '#ff6b6b', 100, 0.45, 6); st.sparks(hx, hy, i === 0 ? '#8fd8ff' : '#ffb3b3', 26, 480);
        if (s.kind === 'head') st.slowmo(0.3, 0.28);
        v.wobble = 1; v.squash = 0.8; v.lungeTarget = -v.height * 0.08;
        this.later(() => { v.lungeTarget = 0; }, 350);
        st.text(hx, hy - 40, `+${pts}`, { color: i === 0 ? '#6ec8ff' : '#ff8a8a', size: 44 });
        st.text(st.W / 2, st.H * 0.3, `${rt.toFixed(2)}s`, { color: '#ffe68a', size: 16, rise: 18 });
      });
    } else {
      this.score[other] += 1; this.pop = { i: other, t: 1 };
      ArenaSound.buzz(); TKD.gs()?.playSound('error');
      this.F[i].wobble = 0.8;
      st.text(st.W / 2, st.H * 0.32, s.kind === 'leg' ? TKD.t('⚠️ Gam-jeom — below the belt! +1 ⟶', '⚠️ گام-جوم — تحت الحزام! +١ للتاني') : TKD.t('🛡️ It was covered! +1 ⟶', '🛡️ كان متغطي! +١ للتاني'), { color: '#ff9f9f', size: 22, ttl: 1.5, rise: 12 });
    }
    this.later(() => this.nextExchange(), 1300);
  },
  kick(i, onHit) {
    const f = this.F[i], o = this.F[1 - i], dir = i === 0 ? 1 : -1;
    const sp = f.strikePoint(2);
    const baseX = sp.x - f.lunge * dir;
    const target = o.footScreenX() - dir * o.height * 0.1;
    const reach = AG.clamp((target - baseX) * dir, 0, this.stage.W * 0.45);
    ArenaSound.whoosh();
    f.play([
      { pose: 0, hold: 0.04 },
      { pose: 1, hold: 0.12, fade: 0.06, lunge: reach * 0.85 },
      { pose: 2, hold: 0.08, fade: 0.05, lunge: reach },
      { pose: 2, hold: 0.2, fade: 0, ghost: false, hit: onHit },
      { pose: 3, hold: 0.12, fade: 0.07, lunge: reach * 0.4 },
      { pose: 4, hold: 0.14, fade: 0.1, lunge: 0 },
      { pose: 0, hold: 0.05, fade: 0.18 }
    ]);
  },
  update(dt) {
    this.F?.forEach(f => f.update(dt));
    // the two big buttons say what to do right now
    const pads = document.getElementById('vs-pads');
    if (pads && pads.dataset.state !== this.state) {
      pads.dataset.state = this.state;
      pads.querySelectorAll('.vs-pad').forEach((b, i) => {
        const hint = b.querySelector('.vs-hint');
        if (hint) hint.textContent = this.state === 'open' ? TKD.t('Legal target? KICK!', 'هدف صح؟ اركل!') : this.state === 'wait' ? TKD.t('wait for the board…', 'استنى اللوحة…') : '';
      });
    }
    if (this.state === 'open' && this.signal && this.stage.time - this.signal.born > 2.0) {
      this.state = 'resolving';
      const st = this.stage;
      st.text(st.W / 2, st.H * 0.32, this.signal.valid ? TKD.t('⏰ Nobody kicked!', '⏰ محدش ركل!') : TKD.t('👀 Both read it right!', '👀 الاتنين قروها صح!'), { color: '#ffe68a', size: 22, ttl: 1.3, rise: 10 });
      this.later(() => this.nextExchange(), 1100);
    }
    if (this.pop) { this.pop.t -= dt * 2; if (this.pop.t <= 0) this.pop = null; }
  },
  draw(c, W, H) {
    // v46: whoever is kicking is drawn in front
    (this.F || []).slice().sort((a, b) => (a.pose > 0) - (b.pose > 0)).forEach(f => f.draw(c));
    // scoreboard
    const w = Math.min(420, W * 0.7), h = 56, x = (W - w) / 2, y = 10, half = (w - 8) / 2;
    c.save();
    c.fillStyle = 'rgba(5,10,16,0.85)'; c.beginPath(); c.roundRect(x - 4, y - 4, w + 8, h + 8, 14); c.fill();
    (this.P || []).forEach((p, i) => {
      const bx = x + i * (half + 8), g = c.createLinearGradient(0, y, 0, y + h);
      g.addColorStop(0, i ? '#d12a37' : '#1f5fd1'); g.addColorStop(1, i ? '#7d1720' : '#123a80');
      c.fillStyle = g; c.beginPath(); c.roundRect(bx, y, half, h, 10); c.fill();
      c.fillStyle = 'rgba(255,255,255,0.9)'; c.font = '800 12px Cairo, Roboto, sans-serif'; c.textAlign = 'center'; c.textBaseline = 'top';
      c.fillText(p.name, bx + half / 2, y + 5);
      const s = this.pop?.i === i ? 1 + this.pop.t * 0.3 : 1;
      c.save(); c.translate(bx + half / 2, y + 36); c.scale(s, s);
      c.font = '900 26px "Roboto Mono", Roboto, monospace'; c.textBaseline = 'middle'; c.fillStyle = '#fff'; c.fillText(String(this.score[i]), 0, 0); c.restore();
    });
    c.fillStyle = 'rgba(255,255,255,0.7)'; c.font = '700 12px Cairo, Roboto, sans-serif'; c.textAlign = 'center'; c.textBaseline = 'top';
    c.fillText(this.golden ? TKD.t('⭐ golden point', '⭐ النقطة الدهبية') : TKD.t(`exchange ${Math.max(1, this.ex)} / ${this.MAX_EX} · first to ${this.WIN_POINTS}`, `جولة ${Math.max(1, this.ex)} / ${this.MAX_EX} · أول واحد يوصل ${this.WIN_POINTS}`), W / 2, y + h + 10);
    c.restore();
    // referee board
    const cx = W / 2, cy = H * 0.42;
    c.save();
    if (this.state === 'open' && this.signal) {
      const L = this.LABEL[this.signal.kind];
      const age = this.stage.time - this.signal.born, pop = AG.easeOutBack(AG.clamp(age / 0.18, 0, 1));
      const left = 1 - AG.clamp(age / 2, 0, 1);
      c.translate(cx, cy); c.scale(pop, pop);
      c.fillStyle = 'rgba(10,16,22,0.88)'; c.strokeStyle = '#ffd166'; c.lineWidth = 3;
      c.beginPath(); c.roundRect(-92, -46, 184, 92, 18); c.fill(); c.stroke();
      c.font = '34px system-ui'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText(L.icon, 0, -14);
      c.font = '900 22px Cairo, Roboto, sans-serif'; c.fillStyle = '#ffd166'; c.fillText(TKD.ar ? L.ar : L.en, 0, 22);
      c.fillStyle = left < 0.3 ? '#ff6b6b' : '#fff'; c.fillRect(-80, 38, 160 * left, 4);
    } else if (this.state === 'wait') {
      c.globalAlpha = 0.6 + 0.2 * Math.sin(this.stage.time * 6);
      c.font = '800 18px Cairo, Roboto, sans-serif'; c.fillStyle = '#fff'; c.textAlign = 'center';
      c.fillText(TKD.t('Ready…', 'استعدوا…'), cx, cy);
    }
    c.restore();
  },
  endMatch() {
    this.over = true; this.state = 'done';
    const [a, b] = this.score, wi = a > b ? 0 : 1, W = this.P[wi], L = this.P[1 - wi];
    const st = this.stage;
    st.confetti(wi === 0 ? st.W * 0.28 : st.W * 0.72, st.H * 0.3, 70);
    TKD.gs()?.playSound('win');
    this.F[wi].setPose(2, 0.1); this.F[1 - wi].wobble = 1;
    const d = this.load();
    d.matches.push({ ts: Date.now(), p1: { id: this.P[0].id, name: this.P[0].name }, p2: { id: this.P[1].id, name: this.P[1].name }, s1: a, s2: b, winner: W.id, kick: this.skill, tid: this.tourMatch ? this.tour()?.id : null });
    d.matches = d.matches.slice(-500);
    this.save(d);
    const inTour = !!this.tourMatch;
    if (inTour) this.finishTourMatch(W.id);
    const t = this.tour();
    const ui = TKD.$('vs-ui');
    this.later(() => {
      if (!ui) return;
      ui.innerHTML = `<div class="ag-card ag-center vs-result">
        <div class="vs-result-av">${TKD.avatar(W, 'lg')}</div>
        <div class="ag-big">🏆 ${TKD.esc(W.name)}</div>
        <p>${TKD.num(a)} – ${TKD.num(b)} · ${TKD.t(`well played, ${TKD.esc(L.name)}!`, `لعبت حلو يا ${TKD.esc(L.name)}!`)}</p>
        ${inTour && t?.done ? `<p class="vs-champ-line">👑 ${TKD.t('Tournament champion!', 'بطل البطولة!')}</p>` : ''}
        <div class="tkd-row wrap">
          ${inTour ? `<button type="button" class="btn btn-success" id="vs-r-bracket">👑 ${TKD.t('Back to the bracket', 'رجوع للبطولة')}</button>`
            : `<button type="button" class="btn btn-success" id="vs-r-again">🔁 ${TKD.t('Rematch', 'ماتش تاني')}</button><button type="button" class="btn" id="vs-r-setup">⚙️ ${TKD.t('Change players', 'غيّر اللاعبين')}</button>`}
        </div></div>`;
      TKD.$('vs-r-again')?.addEventListener('click', () => this.startMatch(this.P[0], this.P[1], this.skill));
      TKD.$('vs-r-setup')?.addEventListener('click', () => { this.teardown(); this.renderSetup(); });
      TKD.$('vs-r-bracket')?.addEventListener('click', () => { this.teardown(); this.renderSetup(); });
    }, 1400);
  }
};
window.Versus = Versus;
// the arena registry tears the duel down when leaving the screen
if (window.ArenaGames) ArenaGames.byScreen.versus = { initialize: () => {}, teardown: () => Versus.teardown(), refresh: () => Versus.refresh() };

// v27.1: leaving the duel screen (menu, home…) stops the match cleanly
document.addEventListener('tkd:screen', (e) => {
  if (e.detail?.previousScreen === 'versus' && e.detail.screenId !== 'versus' && Versus.view === 'match') { Versus.teardown(); Versus.view = 'setup'; }
});

// #####################################################################
// ## social/profile.js
// #####################################################################
/* =====================================================================
   TAEKWONDO JOURNEY — PLAYER PROFILE ("hero page") + ALL PLAYERS (v24)
   Profile: hero card, kick mastery, tiered achievements (bronze → silver →
   gold, with progress to the next tier) + the classic trophies, personal
   records, training calendar, journey timeline, this week vs last week,
   shareable PNG card. All players: gym records + sortable player grid.
   "New record!" / "New achievement!" pop up right after the attempt.
   Everything is computed from data the game already stores. Loaded after
   competition.js / versus.js.
   ===================================================================== */

const Profile = {
  pid: null,
  month: 0,          // 0 = this month, -1 = last month …
  showAllTimeline: false,
  PLAYED_EXCLUDE: new Set(['warmup', 'learning']),
  TIER_NAMES: [{ en: 'Bronze', ar: 'برونز', icon: '🥉', color: '#c08457' }, { en: 'Silver', ar: 'فضة', icon: '🥈', color: '#aab4be' }, { en: 'Gold', ar: 'دهب', icon: '🥇', color: '#e9c46a' }],

  // ------------------------------------------------------------ data
  ctx(pid) {
    const p = PlayerSystem.getPlayers().find(x => x.id === pid);
    if (!p) return null;
    if (pid === PlayerSystem.getCurrentPlayerId()) TKD.gs()?.saveToStorage();
    const save = TKD.read(GameState.storageKey(pid), null) || PlayerSystem.rebuildState(pid) || {};
    const att = PlayerSystem.getAttempts().filter(a => a.playerId === pid).sort((a, b) => a.ts - b.ts);
    const played = att.filter(a => !this.PLAYED_EXCLUDE.has(a.gameId));
    const days = [...new Set(att.map(a => TKD.dayKey(a.ts)))].sort();
    // longest run of consecutive training days (from the log) vs the saved streak
    let run = 0, best = 0, prev = null;
    days.forEach(d => { run = prev && TKD.addDays(prev, 1) === d ? run + 1 : 1; best = Math.max(best, run); prev = d; });
    // weekly streak: consecutive weeks (Sat–Fri) with at least 2 training days — fits a gym
    // schedule (classes are rarely on consecutive days, so a day streak would stay at 1)
    const perWeek = {};
    days.forEach(d => { const w = TKD.weekKey(new Date(d + 'T12:00:00')); perWeek[w] = (perWeek[w] || 0) + 1; });
    let wRun = 0, wBest = 0, wPrev = null;
    Object.keys(perWeek).sort().forEach(w => { if (perWeek[w] < 2) { wRun = 0; wPrev = w; return; } wRun = wPrev && TKD.addDays(wPrev, 7) === w && wRun ? wRun + 1 : 1; wBest = Math.max(wBest, wRun); wPrev = w; });
    let wNow = 0;
    for (let w = TKD.weekKey(), first = true; ; w = TKD.addDays(w, -7), first = false) {
      if ((perWeek[w] || 0) >= 2) wNow++;
      else if (!first) break;                  // this week isn't over yet — don't break the streak on it
      if (!perWeek[w] && !first) break;
      if (wNow > 200) break;
    }
    const vs = window.Versus ? Versus.load() : { matches: [], champions: [] };
    const duels = vs.matches.filter(m => m.p1?.id === pid || m.p2?.id === pid);
    const challengeDays = [...new Set(att.filter(a => a.meta?.challenge).map(a => a.meta.challenge))];
    const gs = {
      completedGames: new Set(save.completedGames || []), completedSkills: new Set(save.completedSkills || []),
      unlockedSkills: new Set(save.unlockedSkills || ['apchagi']), skillGameScores: save.skillGameScores || {},
      practiceStreak: save.practiceStreak || 0, bestStreak: save.bestStreak || 0
    };
    const belt = [...GameState.BELTS].reverse().find(b => gs.completedSkills.size >= b.threshold) || GameState.BELTS[0];
    return {
      p, save, att, played, days, gs, belt,
      warmups: att.filter(a => a.gameId === 'warmup').length,
      passes: played.filter(a => a.score >= GameConfig.SETTINGS.PASSING_SCORE).length,
      perfect: played.filter(a => a.score >= 100).length,
      tried: new Set(played.map(a => a.gameId)),
      bestStreak: Math.max(best, save.bestStreak || 0),
      weekStreak: wNow, bestWeekStreak: Math.max(wBest, wNow),
      streak: save.practiceStreak || 0,
      challengeDays,
      challengeWins: challengeDays.filter(d => Challenge.ranking(d)[0]?.pid === pid).length,
      duelWins: duels.filter(m => m.winner === pid).length, duelLosses: duels.filter(m => m.winner && m.winner !== pid).length,
      duelBest: duels.reduce((m, x) => Math.max(m, x.p1?.id === pid ? x.s1 : x.s2), 0),
      titles: vs.champions.filter(c => c.id === pid),
      awards: (p.badges || []).filter(b => b.id !== 'promoted'),
      tier: League.tierOf(p),
      mastered: gs.completedSkills.size
    };
  },
  metaBest(c, gameIds, key, lower = false) {
    let best = null;
    c.att.forEach(a => {
      if (!gameIds.includes(a.gameId)) return;
      const v = a.meta?.[key];
      if (typeof v !== 'number' || v <= 0) return;
      if (best === null || (lower ? v < best.v : v > best.v)) best = { v, ts: a.ts };
    });
    return best;
  },

  // ------------------------------------------------------------ achievements (tiered)
  // Thresholds are calibrated for a typical gym kid: ~3 training days a week,
  // ~1 warm-up + ~5 games + the daily challenge per day, ~45% of games passed,
  // ~5% perfect. Target time to each medal: bronze ≈ 1–2 weeks (a quick first
  // win), silver ≈ 6–8 weeks, gold ≈ one season (4–5 months). Skill medals
  // (power, reaction, kicks, league) are set by how hard the thing is, not by
  // time. scale: true → the coach's "medal difficulty" setting multiplies it.
  ACH: [
    { id: 'warmups',    icon: '🔥', en: 'Warm-up Hero',   ar: 'بطل الإحماء',     den: 'warm-ups',        dar: 'إحماء',          t: [5, 25, 60],   scale: true, v: c => c.warmups },
    { id: 'days',       icon: '📅', en: 'Regular',        ar: 'منتظم',           den: 'training days',   dar: 'يوم تمرين',      t: [4, 20, 50],   scale: true, v: c => c.days.length },
    { id: 'streak',     icon: '⚡', en: 'On Fire',        ar: 'مولّع',            den: 'weeks in a row (2+ days)', dar: 'أسبوع ورا بعض (يومين+)', t: [2, 6, 12], scale: true, v: c => c.bestWeekStreak },
    { id: 'games',      icon: '🎮', en: 'Gamer',          ar: 'لعّيب',            den: 'games played',    dar: 'لعبة',           t: [20, 100, 300], scale: true, v: c => c.played.length },
    { id: 'passes',     icon: '✅', en: 'Passer',         ar: 'بيعدّي',           den: 'passes (85%+)',   dar: 'نجاح (٨٥٪+)',    t: [5, 40, 120],  scale: true, v: c => c.passes },
    { id: 'perfect',    icon: '💯', en: 'Perfectionist',  ar: 'مية مية',          den: 'perfect 100%',    dar: 'مرة ١٠٠٪',      t: [1, 5, 15],    scale: true, v: c => c.perfect },
    { id: 'kicks',      icon: '🥋', en: 'Kick Master',    ar: 'أستاذ الركلات',    den: 'kicks mastered',  dar: 'ركلة متقنة',     t: [1, 2, 3],     v: c => c.mastered },
    { id: 'explorer',   icon: '🧭', en: 'Explorer',       ar: 'مستكشف',          den: 'different games', dar: 'لعبة مختلفة',    t: [4, 8, 13],    v: c => c.tried.size },
    { id: 'challenges', icon: '🏆', en: 'Challenger',     ar: 'بتاع التحديات',    den: 'daily challenges', dar: 'تحدي يومي',     t: [3, 15, 40],   scale: true, v: c => c.challengeDays.length },
    { id: 'daywins',    icon: '🥇', en: 'Top of the Day', ar: 'الأول في اليوم',   den: 'days ranked #1',  dar: 'يوم في المركز الأول', t: [1, 4, 10], scale: true, v: c => c.challengeWins },
    { id: 'duels',      icon: '⚔️', en: 'Duelist',        ar: 'مقاتل',           den: 'duels won',       dar: 'مواجهة كسبها',   t: [1, 8, 25],    scale: true, v: c => c.duelWins },
    { id: 'titles',     icon: '👑', en: 'Champion',       ar: 'البطل',            den: 'tournaments won', dar: 'بطولة',          t: [1, 2, 4],     v: c => c.titles.length },
    { id: 'awards',     icon: '🎖️', en: 'Decorated',      ar: 'متكرّم',           den: 'weekly awards',   dar: 'جايزة أسبوعية',  t: [1, 3, 6],     scale: true, v: c => c.awards.length },
    { id: 'league',     icon: '⬆️', en: 'Climber',        ar: 'طالع لفوق',        den: 'league reached',  dar: 'الدوري',         t: [1, 2, 4],     v: c => c.tier, fmt: v => League.tierName(v), noUnit: true },
    { id: 'power',      icon: '💥', en: 'Power Kicker',   ar: 'رجل حديد',         den: 'power points',    dar: 'نقطة قوة',          t: [450, 650, 850], v: c => Profile.metaBest(c, ['heavy-bag'], 'bestPower')?.v || 0 },
    { id: 'reflex',     icon: '⚡', en: 'Lightning',      ar: 'البرق',            den: 's reaction',      dar: 'ث رد فعل',       t: [1.1, 0.85, 0.65], lower: true, v: c => Profile.metaBest(c, ['paddle-reflex', 'sparring-duel'], 'avgReaction', true)?.v || 0, fmt: v => v ? v.toFixed(2) : '—' }
  ],
  // coach setting: easier ×0.7 · normal ×1 · harder ×1.4 (count medals only)
  MEDAL_SCALE: { easy: 0.7, normal: 1, hard: 1.4 },
  thresholds(a) {
    const k = this.MEDAL_SCALE[League.settings().medals] || 1;
    if (!a.scale || k === 1) return a.t;
    return a.t.map((x, i) => Math.max(i + 1, Math.round(x * k)));
  },
  achTier(a, v) {
    const t = this.thresholds(a);
    if (a.lower) { if (!v) return 0; return t.filter(x => v <= x).length; }
    return t.filter(x => v >= x).length;
  },
  achievements(c) {
    return this.ACH.map(a0 => {
      const a = { ...a0, t: this.thresholds(a0) };
      const v = a.v(c), tier = this.achTier(a0, v);
      const next = tier < 3 ? a.t[tier] : null;
      let prog = 1;
      if (next !== null) prog = a.lower ? (v ? Math.max(0, Math.min(1, (a.t[0] * 1.6 - v) / (a.t[0] * 1.6 - next))) : 0) : Math.min(1, v / next);
      return { ...a, value: v, tier, next, prog };
    });
  },
  trophies(c) {
    const list = (typeof TrophyRoomSystem !== 'undefined' && TrophyRoomSystem.TROPHIES) || [];
    return list.map(t => { let ok = false; try { ok = !!t.condition(c.gs); } catch (e) {} return { ...t, ok }; });
  },
  level(achs, trophies) {
    const pts = achs.reduce((s, a) => s + a.tier, 0) + trophies.filter(t => t.ok).length;
    return { pts, level: 1 + Math.floor(pts / 3), into: pts % 3 };
  },

  // ------------------------------------------------------------ personal records
  records(c) {
    const r = [];
    const add = (id, icon, en, ar, best, fmt) => r.push({ id, icon, label: TKD.t(en, ar), v: best?.v ?? null, ts: best?.ts, text: best ? fmt(best.v) : '—' });
    add('reaction', '⚡', 'Fastest reaction', 'أسرع رد فعل', this.metaBest(c, ['paddle-reflex', 'sparring-duel'], 'avgReaction', true), v => TKD.t(`${v.toFixed(2)} s`, `${TKD.num(v.toFixed(2))} ث`));
    add('power', '💥', 'Strongest kick', 'أقوى ركلة', this.metaBest(c, ['heavy-bag'], 'bestPower'), v => `💪 ${TKD.num(v)}`);
    const sp = this.metaBest(c, ['sparring-duel'], 'points');
    const duelBest = c.duelBest ? { v: c.duelBest } : null;
    add('points', '🥊', 'Most points in a fight', 'أكتر نقط في نزال', sp && (!duelBest || sp.v >= duelBest.v) ? sp : duelBest, v => TKD.t(TKD.count(v, 'pt', 'en'), TKD.count(v, 'point', 'ar')));
    add('rhythm', '🥁', 'Longest rhythm streak', 'أطول سلسلة إيقاع', this.metaBest(c, ['phase-rhythm'], 'bestStreak'), v => TKD.t(`${v} notes`, `${TKD.num(v)} نوتة`));
    add('combo', '🎯', 'Best paddle combo', 'أحسن كومبو مضارب', this.metaBest(c, ['paddle-reflex'], 'bestCombo'), v => `× ${TKD.num(v)}`);
    const bal = c.att.filter(a => a.gameId === 'balance-hold' && a.meta && a.meta.falls === 0).reduce((m, a) => (!m || a.score > m.v ? { v: a.score, ts: a.ts } : m), null);
    add('balance', '⚖️', 'Best balance (no falls)', 'أحسن توازن (من غير وقوع)', bal, v => `${TKD.num(v)}%`);
    const ch = c.att.filter(a => a.meta?.challenge).reduce((m, a) => (!m || a.score > m.v ? { v: a.score, ts: a.ts } : m), null);
    add('challenge', '🏆', 'Best challenge score', 'أحسن نتيجة في التحدي', ch, v => `${TKD.num(v)}%`);
    add('streak', '🔥', 'Longest weekly streak', 'أطول سلسلة أسابيع', c.bestWeekStreak ? { v: c.bestWeekStreak } : null, v => TKD.t(TKD.count(v, 'week', 'en'), TKD.count(v, 'week', 'ar')));
    const weeks = [...new Set(c.days.map(d => TKD.weekKey(new Date(d + 'T12:00:00'))))];
    const bw = weeks.map(w => ({ v: League.pointsFor(c.p.id, w).total, ts: new Date(w + 'T12:00:00').getTime() })).sort((a, b) => b.v - a.v)[0];
    add('week', '📈', 'Best week', 'أحسن أسبوع', bw && bw.v ? bw : null, v => TKD.t(TKD.count(v, 'pt', 'en'), TKD.count(v, 'point', 'ar')));
    return r;
  },

  // ------------------------------------------------------------ timeline
  timeline(c) {
    const ev = [];
    const push = (ts, icon, text) => { if (ts) ev.push({ ts, icon, text }); };
    push(c.p.createdAt, '🎉', TKD.t('Joined Taekwondo Journey', 'بدأ رحلة التايكوندو'));
    const w = c.att.find(a => a.gameId === 'warmup'); push(w?.ts, '🔥', TKD.t('First warm-up', 'أول إحماء'));
    GameConfig.SKILL_ORDER.forEach(sk => {
      const first = c.att.find(a => a.skillId === sk && a.gameId !== 'warmup');
      if (first && sk !== 'apchagi') push(first.ts, '🔓', TKD.t(`Started ${TKD.skillName(sk)}`, `بدأ ${TKD.skillName(sk)}`));
      const q = c.att.find(a => a.skillId === sk && a.gameId === 'quiz' && a.score >= GameConfig.SETTINGS.PASSING_SCORE);
      push(q?.ts, '🎓', TKD.t(`Passed the ${TKD.skillName(sk)} test`, `عدّى اختبار ${TKD.skillName(sk)}`));
    });
    const perf = c.played.find(a => a.score >= 100); push(perf?.ts, '💯', TKD.t(`First 100% — ${TKD.gameName(perf?.gameId)}`, `أول ١٠٠٪ — ${TKD.gameName(perf?.gameId)}`));
    (c.p.badges || []).forEach(b => push(new Date((b.week || TKD.dayKey()) + 'T20:00:00').getTime(), League.AWARDS[b.id]?.icon || '🏅', League.awardName(b.id).replace(/^\S+\s/, '')));
    const dw = c.att.find(a => a.meta?.challenge && Challenge.ranking(a.meta.challenge)[0]?.pid === c.p.id);
    push(dw?.ts, '🥇', TKD.t('First day ranked #1 in the challenge', 'أول يوم في المركز الأول في التحدي'));
    const duel = window.Versus ? Versus.load().matches.find(m => m.winner === c.p.id) : null;
    push(duel?.ts, '⚔️', TKD.t('First duel won', 'أول مواجهة كسبها'));
    return ev.sort((a, b) => b.ts - a.ts);
  },

  // ------------------------------------------------------------ open / render
  open(pid) { this.pid = pid || PlayerSystem.getCurrentPlayerId(); this.month = 0; this.showAllTimeline = false; this.tab = 'me'; switchScreen('profile'); },
  init() { if (!this.pid || !PlayerSystem.getPlayers().find(p => p.id === this.pid)) this.pid = PlayerSystem.getCurrentPlayerId() || PlayerSystem.getPlayers()[0]?.id; this.render(); },
  render() {
    const root = TKD.$('profile-root'); if (!root) return;
    const c = this.ctx(this.pid);
    if (!c) { root.innerHTML = `<p class="lg-empty">${TKD.t('No players yet.', 'لسه مفيش لاعبين.')}</p>`; return; }
    const achs = this.achievements(c), trophies = this.trophies(c), lv = this.level(achs, trophies);
    const me = c.p.id === PlayerSystem.getCurrentPlayerId();
    const tier = League.TIERS[c.tier];
    const medals = [0, 1, 2].map(i => achs.filter(a => a.tier > i).length);
    const recs = this.records(c);
    // v55: one long page became three short tabs — me · my achievements · my calendar
    const tab = ['me', 'ach', 'cal'].includes(this.tab) ? this.tab : 'me';
    const tabs = [['me', '🧑', TKD.t('Me', 'أنا')], ['ach', '🏅', TKD.t('Achievements', 'إنجازاتي')], ['cal', '🗓️', TKD.t('Calendar', 'تقويمي')]];
    const got = trophies.filter(t => t.ok).length;
    const body = {
      me: () => `${this.compareHTML(c)}
      ${(() => { const w = window.Review ? Review.weakest(c.p.id, 3) : []; return w.length ? `<section class="pf-sec pf-review"><h3>🧠 ${TKD.t('Worth reviewing', 'محتاج يراجع')}</h3><ul>${w.map(x => `<li>${TKD.esc(Review.label(x))}</li>`).join('')}</ul></section>` : ''; })()}
      <section class="pf-sec"><h3>🥋 ${TKD.t('Kicks', 'الركلات')}</h3>${window.DashboardSystem ? DashboardSystem.masteryHTML(c.p.id) : ''}</section>`,
      ach: () => `<section class="pf-sec pf-troph-sum"><h3>🏆 ${TKD.t('Trophies', 'الكاسات')} <small>${TKD.num(got)} / ${TKD.num(trophies.length)}</small></h3>
        <div class="pf-troph-row">${trophies.filter(t => t.ok).map(t => `<span title="${TKD.esc(TKD.ar ? t.name.ar : t.name.en)}">${t.icon}</span>`).join('') || `<small>${TKD.t('No trophies yet — they are waiting for you!', 'لسه مفيش كاسات — مستنياك!')}</small>`}</div>
        ${me ? `<button type="button" class="btn btn-small" id="pf-trophy-room">🏆 ${TKD.t('Open the trophy room', 'افتح فاترينة الكاسات')}</button>` : ''}</section>
      <section class="pf-sec"><h3>🏅 ${TKD.t('Achievements', 'الإنجازات')} <small>${TKD.t(`${medals[0]} bronze · ${medals[1]} silver · ${medals[2]} gold`, `${TKD.num(medals[0])} برونز · ${TKD.num(medals[1])} فضة · ${TKD.num(medals[2])} دهب`)}</small></h3>
        <div class="pf-ach">${achs.map(a => this.achHTML(a)).join('')}</div></section>
      <section class="pf-sec"><h3>📊 ${TKD.t('Personal records', 'أرقامي القياسية')}</h3>
        <div class="pf-recs">${recs.map(r => `<div class="pf-rec ${r.v === null ? 'empty' : ''}"><span class="pf-rec-i">${r.icon}</span><span class="pf-rec-l">${r.label}</span><b>${r.text}</b>${r.ts ? `<small>${new Date(r.ts).toLocaleDateString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short' })}</small>` : ''}</div>`).join('')}</div></section>`,
      cal: () => `<section class="pf-sec">${this.calendarHTML(c)}</section>
      <section class="pf-sec">${this.timelineHTML(c)}</section>`
    };
    root.innerHTML = `
      ${this.heroHTML(c, lv, tier, medals, trophies, me)}
      <div class="pf-tabs" role="tablist">${tabs.map(([id, ic, label]) => `<button type="button" role="tab" aria-selected="${id === tab}" class="${id === tab ? 'on' : ''}" data-pf-tab="${id}">${ic} ${label}</button>`).join('')}</div>
      <div class="pf-tabbody" role="tabpanel">${body[tab]()}</div>`;
    this.bind(root, c, achs, trophies, lv, medals);
    root.querySelectorAll('[data-pf-tab]').forEach(b => b.addEventListener('click', () => { this.tab = b.dataset.pfTab; TKD.gs()?.playSound('click'); this.render(); }));
    TKD.$('pf-trophy-room')?.addEventListener('click', () => switchScreen('trophy-room'));
  },
  heroHTML(c, lv, tier, medals, trophies, me) {
    const belt = c.belt;
    return `<section class="pf-hero" style="--tier:${tier.color}">
      <div class="pf-hero-av">${TKD.avatar(c.p, 'xl')}<span class="pf-lvl" title="${TKD.t('Level', 'المستوى')}">${TKD.num(lv.level)}</span></div>
      <div class="pf-hero-main">
        <h2>${TKD.esc(c.p.name)}${me ? ` <em>${TKD.t('(you)', '(إنت)')}</em>` : ''}</h2>
        <div class="pf-tags"><span>${tier.icon} ${League.tierName(c.tier)}</span>
          <span class="pf-belt"><i style="background:${belt.color};border-color:${belt.accent}">${'<b></b>'.repeat(belt.stripes)}</i>${TKD.esc(TKD.ar ? belt.name.ar : belt.name.en)}</span></div>
        <div class="pf-xp"><span>${TKD.t(`Level ${lv.level}`, `المستوى ${TKD.num(lv.level)}`)}</span><div class="pf-xp-bar"><i style="width:${(lv.into / 3) * 100}%"></i></div><small>${TKD.t(`${3 - lv.into} more medals to level ${lv.level + 1}`, `فاضل ${TKD.count(3 - lv.into, 'medal', 'ar')} للمستوى ${TKD.num(lv.level + 1)}`)}</small></div>
      </div>
      <div class="pf-tiles">
        <div><b>🔥 ${TKD.num(c.weekStreak)}</b><small>${TKD.t('weeks in a row', 'أسبوع ورا بعض')}</small></div>
        <div><b>${TKD.num(League.pointsFor(c.p.id).total)}</b><small>${TKD.t('pts this week', 'نقطة الأسبوع ده')}</small></div>
        <div><b>🥇 ${TKD.num(medals[2])}</b><small>${TKD.t('gold medals', 'ميدالية دهب')}</small></div>
        <div><b>🏆 ${TKD.num(trophies.filter(t => t.ok).length)}</b><small>${TKD.t('trophies', 'كاس')}</small></div>
      </div>
      <div class="pf-hero-btns">
        <button type="button" class="btn btn-success btn-small" id="pf-share">🖼️ ${TKD.t('Save my card', 'احفظ الكارت بتاعي')}</button>
        ${!me ? `<button type="button" class="btn btn-small" id="pf-duel">⚔️ ${TKD.t('Challenge', 'تحدّاه')}</button>` : ''}
        <button type="button" class="btn btn-small" id="pf-all">👥 ${TKD.t('All players', 'كل اللاعبين')}</button>
      </div></section>`;
  },
  compareHTML(c) {
    const wk = TKD.weekKey(), lw = TKD.addDays(wk, -7);
    const inWeek = (w) => c.att.filter(a => TKD.dayKey(a.ts) >= w && TKD.dayKey(a.ts) < TKD.addDays(w, 7));
    const stat = (w) => { const l = inWeek(w), pl = l.filter(a => !this.PLAYED_EXCLUDE.has(a.gameId)); return { pts: League.pointsFor(c.p.id, w).total, games: pl.length, avg: pl.length ? Math.round(pl.reduce((s, a) => s + a.score, 0) / pl.length) : 0, warm: new Set(l.filter(a => a.gameId === 'warmup').map(a => TKD.dayKey(a.ts))).size }; };
    const a = stat(wk), b = stat(lw);
    const cell = (label, x, y, unit = '') => {
      const d = x - y, cls = d > 0 ? 'up' : d < 0 ? 'down' : '';
      return `<div class="pf-cmp-c"><small>${label}</small><b>${TKD.num(x)}${unit}</b><span class="${cls}">${d > 0 ? '▲' : d < 0 ? '▼' : '＝'} ${TKD.num(Math.abs(d))}${unit}</span></div>`;
    };
    const msg = a.pts > b.pts ? TKD.t(`You're ahead of last week by ${a.pts - b.pts} points — keep it up! 💪`, `إنت متقدم عن الأسبوع اللي فات بـ${TKD.count(a.pts - b.pts, 'point', 'ar')} — كمّل كده! 💪`)
      : a.pts === b.pts ? TKD.t('Level with last week — one more warm-up puts you ahead!', 'زي الأسبوع اللي فات بالظبط — إحماء واحد كمان وتبقى متقدم!')
      : TKD.t(`${b.pts - a.pts} points to beat last week — you can do it!`, `فاضل ${TKD.count(b.pts - a.pts, 'point', 'ar')} وتكسب الأسبوع اللي فات — تقدر!`);
    return `<section class="pf-sec pf-cmp"><h3>📈 ${TKD.t('This week vs last week', 'الأسبوع ده قصاد اللي فات')}</h3>
      <div class="pf-cmp-row">${cell(TKD.t('Points', 'النقط'), a.pts, b.pts)}${cell(TKD.t('Games', 'الألعاب'), a.games, b.games)}${cell(TKD.t('Average', 'المتوسط'), a.avg, b.avg, '%')}${cell(TKD.t('Warm-up days', 'أيام الإحماء'), a.warm, b.warm)}</div>
      <p class="pf-cmp-msg">${msg}</p></section>`;
  },
  achHTML(a) {
    const T = this.TIER_NAMES;
    const cur = a.tier ? T[a.tier - 1] : null;
    const fmt = a.fmt || (v => TKD.num(Math.round(v * 100) / 100));
    const nextTxt = a.next === null ? TKD.t('Max level!', 'أعلى مستوى!')
      : a.lower ? TKD.t(`${T[a.tier].icon} at ${a.next.toFixed(1)} s`, `${T[a.tier].icon} عند ${TKD.num(a.next.toFixed(1))} ث`)
      : TKD.t(`${T[a.tier].icon} at ${a.fmt ? a.fmt(a.next) : a.next}`, `${T[a.tier].icon} عند ${a.fmt ? a.fmt(a.next) : TKD.num(a.next)}`);
    return `<div class="pf-a t${a.tier}" style="--c:${cur ? cur.color : 'rgba(255,255,255,0.15)'}">
      <div class="pf-a-medal">${a.icon}${cur ? `<i>${cur.icon}</i>` : ''}</div>
      <div class="pf-a-body"><b>${TKD.ar ? a.ar : a.en}</b>
        <small>${fmt(a.value)}${a.noUnit ? '' : ' ' + (TKD.ar ? a.dar : a.den)}</small>
        <div class="pf-a-bar"><i style="width:${Math.round(a.prog * 100)}%"></i></div>
        <small class="pf-a-next">${nextTxt}</small></div></div>`;
  },
  calendarHTML(c) {
    const base = new Date(); base.setDate(1); base.setMonth(base.getMonth() + this.month);
    const y = base.getFullYear(), m = base.getMonth();
    const first = new Date(y, m, 1), daysIn = new Date(y, m + 1, 0).getDate();
    const lead = (first.getDay() + 1) % 7;              // weeks start on Saturday
    const per = {}, warm = new Set();
    c.att.forEach(a => { const d = TKD.dayKey(a.ts); per[d] = (per[d] || 0) + 1; if (a.gameId === 'warmup') warm.add(d); });
    const lvl = (n) => (!n ? 0 : n < 3 ? 1 : n < 6 ? 2 : n < 10 ? 3 : 4);
    const names = TKD.ar ? ['س', 'ح', 'ن', 'ث', 'ر', 'خ', 'ج'] : ['Sa', 'Su', 'Mo', 'Tu', 'We', 'Th', 'Fr'];
    const today = TKD.dayKey();
    let cells = '';
    for (let i = 0; i < lead; i++) cells += '<span class="pf-day pad"></span>';
    let trained = 0;
    for (let d = 1; d <= daysIn; d++) {
      const key = TKD.dayKey(new Date(y, m, d)), n = per[key] || 0;
      if (n) trained++;
      cells += `<span class="pf-day l${lvl(n)} ${key === today ? 'today' : ''}" title="${key}: ${n}">${TKD.num(d)}${warm.has(key) ? '<i>🔥</i>' : ''}</span>`;
    }
    const title = first.toLocaleDateString(TKD.ar ? 'ar-EG' : 'en-GB', { month: 'long', year: 'numeric' });
    return `<div class="pf-cal-head"><h3>🗓️ ${TKD.t('Training calendar', 'تقويم التمرين')}</h3>
        <div class="pf-cal-nav"><button type="button" data-cal="-1" aria-label="${TKD.t('previous month', 'الشهر اللي فات')}">${TKD.ar ? '›' : '‹'}</button><b>${title}</b><button type="button" data-cal="1" ${this.month >= 0 ? 'disabled' : ''} aria-label="${TKD.t('next month', 'الشهر الجاي')}">${TKD.ar ? '‹' : '›'}</button></div></div>
      <div class="pf-cal">${names.map(n => `<span class="pf-dow">${n}</span>`).join('')}${cells}</div>
      <div class="pf-cal-foot"><span>${TKD.t(`Trained ${trained} days this month`, `اتمرن ${TKD.count(trained, 'day', 'ar')} في الشهر ده`)}</span>
        <span class="pf-cal-key">${TKD.t('less', 'أقل')} <i class="l1"></i><i class="l2"></i><i class="l3"></i><i class="l4"></i> ${TKD.t('more', 'أكتر')} · 🔥 ${TKD.t('warm-up', 'إحماء')}</span></div>`;
  },
  timelineHTML(c) {
    const ev = this.timeline(c);
    const list = this.showAllTimeline ? ev : ev.slice(0, 8);
    return `<h3>🧭 ${TKD.t('My journey', 'رحلتي')}</h3>
      ${ev.length ? `<ol class="pf-tl">${list.map(e => `<li><span class="pf-tl-i">${e.icon}</span><span>${TKD.esc(e.text)}</span><small>${new Date(e.ts).toLocaleDateString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</small></li>`).join('')}</ol>
        ${ev.length > 8 && !this.showAllTimeline ? `<button type="button" class="btn btn-small" id="pf-tl-more">${TKD.t(`Show all (${ev.length})`, `اعرض الكل (${TKD.num(ev.length)})`)}</button>` : ''}`
        : `<p class="lg-empty">${TKD.t('The journey starts with the first warm-up!', 'الرحلة بتبدأ بأول إحماء!')}</p>`}`;
  },
  bind(root, c, achs, trophies, lv, medals) {
    root.querySelectorAll('[data-cal]').forEach(b => b.addEventListener('click', () => { this.month = Math.min(0, this.month + (+b.dataset.cal)); this.render(); }));
    TKD.$('pf-tl-more')?.addEventListener('click', () => { this.showAllTimeline = true; this.render(); });
    TKD.$('pf-all')?.addEventListener('click', () => switchScreen('players'));
    TKD.$('pf-duel')?.addEventListener('click', () => { Versus.mode = 'friendly'; Versus.sel = { ...Versus.sel, p1: PlayerSystem.getCurrentPlayerId(), p2: c.p.id }; switchScreen('versus'); });
    TKD.$('pf-share')?.addEventListener('click', () => this.shareCard(c, achs, trophies, lv, medals));
  },

  // ------------------------------------------------------------ shareable PNG card
  async shareCard(c, achs, trophies, lv, medals) {
    const W = 1080, H = 1350, cv = document.createElement('canvas'); cv.width = W; cv.height = H;
    const g = cv.getContext('2d'); const tier = League.TIERS[c.tier];
    const bg = g.createLinearGradient(0, 0, W, H); bg.addColorStop(0, '#1d3557'); bg.addColorStop(0.55, '#15232c'); bg.addColorStop(1, '#3a1420');
    g.fillStyle = bg; g.fillRect(0, 0, W, H);
    g.strokeStyle = tier.color; g.lineWidth = 14; g.beginPath(); g.roundRect(30, 30, W - 60, H - 60, 40); g.stroke();
    const img = await new Promise(res => { const i = new Image(); i.onload = () => res(i); i.onerror = () => res(null); PoseShots.whenReady(PoseShots.url(c.p.character, 'hero', 0, { plain: true })).then(u => { i.src = u; }); });
    g.save(); g.beginPath(); g.arc(W / 2, 330, 190, 0, Math.PI * 2); g.fillStyle = 'rgba(255,255,255,0.08)'; g.fill(); g.clip();
    if (img) { const h = 520, w = img.width * h / img.height; g.drawImage(img, W / 2 - w / 2, 170, w, h); }
    g.restore();
    g.lineWidth = 8; g.strokeStyle = tier.color; g.beginPath(); g.arc(W / 2, 330, 190, 0, Math.PI * 2); g.stroke();
    g.fillStyle = '#ff6b35'; g.beginPath(); g.arc(W / 2 + 150, 190, 58, 0, Math.PI * 2); g.fill();
    g.textAlign = 'center'; g.textBaseline = 'middle'; g.direction = TKD.ar ? 'rtl' : 'ltr';
    g.fillStyle = '#fff'; g.font = '900 56px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(TKD.num(lv.level), W / 2 + 150, 194);
    g.font = '900 96px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(c.p.name, W / 2, 610);
    g.font = '700 44px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillStyle = tier.color; g.fillText(`${tier.icon} ${League.tierName(c.tier)}`, W / 2, 695);
    g.fillStyle = '#cfd8dc'; g.font = '600 38px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(TKD.ar ? c.belt.name.ar : c.belt.name.en, W / 2, 755);
    const tiles = [[`🔥 ${TKD.num(c.weekStreak)}`, TKD.t('weeks in a row', 'أسبوع ورا بعض')], [TKD.num(League.pointsFor(c.p.id).total), TKD.t('pts this week', 'نقطة الأسبوع')], [`🥇 ${TKD.num(medals[2])}`, TKD.t('gold medals', 'ميدالية دهب')], [`🏆 ${TKD.num(trophies.filter(t => t.ok).length)}`, TKD.t('trophies', 'كاس')]];
    tiles.forEach(([v, l], i) => {
      const x = 90 + (i % 2) * 460, y = 820 + Math.floor(i / 2) * 170;
      g.fillStyle = 'rgba(255,255,255,0.07)'; g.beginPath(); g.roundRect(x, y, 440, 150, 26); g.fill();
      g.fillStyle = '#fff'; g.font = '900 56px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(v, x + 220, y + 62);
      g.fillStyle = '#9fb3c0'; g.font = '600 30px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(l, x + 220, y + 116);
    });
    const top = achs.filter(a => a.tier).sort((a, b) => b.tier - a.tier).slice(0, 6);
    g.font = '64px system-ui, "Segoe UI Emoji", sans-serif';
    top.forEach((a, i) => g.fillText(a.icon, W / 2 + (i - (top.length - 1) / 2) * 120, 1200));
    g.fillStyle = '#ff6b35'; g.font = '800 34px Cairo, "Noto Sans Arabic", Roboto, system-ui, Tahoma, sans-serif'; g.fillText(`🥋 ${TKD.t('Taekwondo Journey', 'رحلة التايكوندو')}`, W / 2, 1280);
    cv.toBlob(b => {
      const url = URL.createObjectURL(b), l = document.createElement('a');
      l.href = url; l.download = `hero-${String(c.p.name).replace(/[^\w؀-ۿ-]+/g, '_')}.png`;
      document.body.appendChild(l); l.click(); l.remove(); setTimeout(() => URL.revokeObjectURL(url), 3000);
    });
    TKD.toast(TKD.t('🖼️ Card saved', '🖼️ الكارت اتحفظ'), 'success');
  },

  // ------------------------------------------------------------ live "new record / achievement" pop-ups
  snapshot(pid) {
    const c = this.ctx(pid); if (!c) return null;
    return { recs: Object.fromEntries(this.records(c).map(r => [r.id, r])), achs: Object.fromEntries(this.achievements(c).map(a => [a.id, a])) };
  },
  wrapLogging() {
    const orig = PlayerSystem.logAttempt.bind(PlayerSystem);
    const lowerIsBetter = new Set(['reaction']);
    PlayerSystem.logAttempt = (...args) => {
      const pid = PlayerSystem.getCurrentPlayerId();
      let before = null;
      try { before = pid ? this.snapshot(pid) : null; } catch (e) {}
      orig(...args);
      if (!before) return;
      setTimeout(() => {
        try {
          const after = this.snapshot(pid); if (!after) return;
          const news = [];
          Object.values(after.recs).forEach(r => {
            const b = before.recs[r.id];
            if (r.v === null || !b || b.v === null || r.id === 'streak' || r.id === 'week') return;
            if (lowerIsBetter.has(r.id) ? r.v < b.v : r.v > b.v) news.push(`📊 ${TKD.t('New record!', 'رقم قياسي جديد!')} ${r.icon} ${r.label}: ${r.text}`);
          });
          Object.values(after.achs).forEach(a => {
            const b = before.achs[a.id];
            if (b && a.tier > b.tier) news.push(`🏅 ${TKD.t('New achievement!', 'إنجاز جديد!')} ${a.icon} ${TKD.ar ? a.ar : a.en} — ${this.TIER_NAMES[a.tier - 1].icon} ${TKD.ar ? this.TIER_NAMES[a.tier - 1].ar : this.TIER_NAMES[a.tier - 1].en}`);
          });
          news.slice(0, 3).forEach((m, i) => setTimeout(() => { TKD.toast(m, 'success'); if (i === 0) { TKD.gs()?.playSound('success'); window.AudioKit?.sfx('star'); window.Voice?.cue(/📊/.test(m) ? 'record' : 'levelup'); } }, 2600 + i * 1400));
        } catch (e) {}
      }, 50);
    };
  }
};
window.Profile = Profile;

// =====================================================================
// ALL PLAYERS
// =====================================================================
const PlayersPage = {
  sort: 'week',
  init() { this.render(); },
  render() {
    const root = TKD.$('players-root'); if (!root) return;
    const rows = PlayerSystem.getPlayers().map(p => {
      const c = Profile.ctx(p.id), achs = Profile.achievements(c), tro = Profile.trophies(c), lv = Profile.level(achs, tro);
      const recs = Object.fromEntries(Profile.records(c).map(r => [r.id, r]));
      const last = c.att.length ? c.att[c.att.length - 1].ts : p.createdAt || 0;
      return { p, c, lv, recs, last, week: League.pointsFor(p.id).total, gold: achs.filter(a => a.tier === 3).length, medals: achs.reduce((s, a) => s + a.tier, 0), trophies: tro.filter(t => t.ok).length };
    });
    if (!rows.length) { root.innerHTML = `<p class="lg-empty">${TKD.t('No players yet.', 'لسه مفيش لاعبين.')}</p>`; return; }
    const sorts = {
      week: [TKD.t('Week points', 'نقط الأسبوع'), (a, b) => b.week - a.week],
      level: [TKD.t('Level', 'المستوى'), (a, b) => b.lv.pts - a.lv.pts],
      streak: [TKD.t('Streak', 'السلسلة'), (a, b) => b.c.weekStreak - a.c.weekStreak || b.c.bestWeekStreak - a.c.bestWeekStreak],
      warm: [TKD.t('Warm-ups', 'الإحماء'), (a, b) => b.c.warmups - a.c.warmups],
      recent: [TKD.t('Recent', 'الأحدث'), (a, b) => b.last - a.last]
    };
    rows.sort(sorts[this.sort][1]);
    // gym-wide records
    const holder = (id, lower) => rows.filter(r => r.recs[id]?.v != null).sort((a, b) => lower ? a.recs[id].v - b.recs[id].v : b.recs[id].v - a.recs[id].v)[0];
    const gymRecs = [['reaction', true], ['power', false], ['points', false], ['streak', false], ['challenge', false]].map(([id, lower]) => {
      const h = holder(id, lower); if (!h) return '';
      const r = h.recs[id];
      return `<button type="button" class="pl-rec" data-pid="${h.p.id}"><span class="pl-rec-i">${r.icon}</span><span class="pl-rec-t"><small>${r.label}</small><b>${r.text}</b></span>${TKD.avatar(h.p)}<span class="pl-rec-n">${TKD.esc(h.p.name)}</span></button>`;
    }).join('');
    const mostLvl = [...rows].sort(sorts.level[1])[0];
    root.innerHTML = `
      ${gymRecs || mostLvl ? `<section class="pf-sec"><h3>🏟️ ${TKD.t('Gym records', 'الأرقام القياسية في الصالة')}</h3><div class="pl-recs">
        ${mostLvl ? `<button type="button" class="pl-rec" data-pid="${mostLvl.p.id}"><span class="pl-rec-i">⭐</span><span class="pl-rec-t"><small>${TKD.t('Highest level', 'أعلى مستوى')}</small><b>${TKD.t(`Level ${mostLvl.lv.level}`, `المستوى ${TKD.num(mostLvl.lv.level)}`)}</b></span>${TKD.avatar(mostLvl.p)}<span class="pl-rec-n">${TKD.esc(mostLvl.p.name)}</span></button>` : ''}
        ${gymRecs}</div></section>` : ''}
      <div class="pl-sort" role="radiogroup">${Object.entries(sorts).map(([k, [l]]) => `<button type="button" role="radio" aria-checked="${this.sort === k}" class="${this.sort === k ? 'on' : ''}" data-sort="${k}">${l}</button>`).join('')}</div>
      <div class="pl-grid">${rows.map((r, i) => {
        const tier = League.TIERS[r.c.tier];
        return `<button type="button" class="pl-card ${r.p.id === PlayerSystem.getCurrentPlayerId() ? 'me' : ''}" data-pid="${r.p.id}" style="--tier:${tier.color}">
          <span class="pl-pos">${i < 3 ? ['🥇', '🥈', '🥉'][i] : TKD.num(i + 1)}</span>
          <span class="pl-av">${TKD.avatar(r.p, 'lg')}<span class="pf-lvl">${TKD.num(r.lv.level)}</span></span>
          <b class="pl-name">${TKD.esc(r.p.name)}</b>
          <small>${tier.icon} ${League.tierName(r.c.tier)}</small>
          <span class="pl-belt"><i style="background:${r.c.belt.color};border-color:${r.c.belt.accent}">${'<b></b>'.repeat(r.c.belt.stripes)}</i></span>
          <span class="pl-stats"><span>🔥 ${TKD.num(r.c.weekStreak)}</span><span>📈 ${TKD.num(r.week)}</span><span>🏅 ${TKD.num(r.medals)}</span><span>🏆 ${TKD.num(r.trophies)}</span></span>
        </button>`;
      }).join('')}</div>`;
    root.querySelectorAll('[data-sort]').forEach(b => b.addEventListener('click', () => { this.sort = b.dataset.sort; TKD.gs()?.playSound('click'); this.render(); }));
    root.querySelectorAll('[data-pid]').forEach(b => b.addEventListener('click', () => Profile.open(b.dataset.pid)));
  }
};
window.PlayersPage = PlayersPage;

// ------------------------------------------------------------ wiring
Object.assign(window.TKDScreens, { profile: () => Profile.init(), players: () => PlayersPage.init() });
GameConfig.BACKGROUNDS.PROFILE = 'assets/images/backgrounds/memory_dojo_bg.webp';
GameConfig.BACKGROUNDS.PLAYERS = 'assets/images/backgrounds/arena_bg.webp';
Profile.wrapLogging();
(function wrapLanguage() {
  const orig = GameState.prototype.applyLanguage;
  GameState.prototype.applyLanguage = function () {
    const r = orig.apply(this, arguments);
    try {
      if (document.querySelector('#profile-screen.active')) Profile.render();
      if (document.querySelector('#players-screen.active')) PlayersPage.render();
    } catch (e) {}
    return r;
  };
})();

// #####################################################################
// ## learn/curriculum-screen.js
// #####################################################################
// ============================================================================
// CURRICULUM SCREEN (v26) — the whole belt syllabus in one place.
// Every belt → its techniques grouped by kind. Playable kicks open their
// training path; everything else opens a card with names, key points and
// common mistakes, and shows a "pictures coming soon" slot until the media
// arrives. Each player can tick what they already practised at the dojo
// (saved per player) — that becomes a belt checklist.
// ============================================================================
const CurriculumScreen = {
  key() { return `taekwondoJourneyCurriculum:${TKD.pid() || 'guest'}`; },
  done() { return new Set(TKD.read(this.key(), [])); },
  toggle(id) { const d = this.done(); d.has(id) ? d.delete(id) : d.add(id); TKD.write(this.key(), [...d]); },
  L(p) { return TKD.ar ? p.ar : p.en; },
  openBelt: null,

  // an item counts as "done" when ticked, or (for playable kicks) when the skill is completed
  isDone(it, d = this.done()) {
    const gs = TKD.gs();
    return d.has(it.id) || (it.skillId && gs?.completedSkills?.has(it.skillId));
  },
  mastery(it) {
    const gs = TKD.gs();
    if (!it.skillId || !gs) return null;
    return gs.completedSkills.has(it.skillId) ? 100 : Math.round(gs.calculateSkillOverallProgress?.(it.skillId) || 0);
  },
  photo(it) {
    // v51 — a kick the 3D characters can do: its five phases in one stroboscope picture
    const strobe = this.strobeKey(it);
    if (strobe) return PoseShots.url(PoseShots.mine(), strobe, 0);
    if (it.skillId) {
      const sk = GameConfig.SKILLS[it.skillId];
      const ph = sk?.phases?.[2] || sk?.phases?.[0];
      const ch = TKD.gs()?.playerCharacter === 'girl' ? 'girl' : 'boy';
      return ph?.image?.[ch] || it.media.photo;
    }
    return it.media.photo;
  },

  strobeKey(it) { return it.kind === 'kick' ? [it.skillId, it.id].filter(Boolean).map(k => `strobe:${k}`).find(k => PoseShots.has(k)) || null : null; },
  video(it) { return (it.skillId && GameConfig.SKILLS[it.skillId]?.video) || it.media.video; },

  init() {
    const root = TKD.$('curriculum-root');
    if (!root) return;
    const d = this.done();
    const c = Curriculum.count();
    const withMedia = Curriculum.all().filter(i => i.status === 'playable').length;
    if (!this.openBelt) this.openBelt = (Curriculum.BELTS.find(b => b.items.some(i => !this.isDone(i, d))) || Curriculum.BELTS[0]).id;

    const belts = Curriculum.BELTS.map((b, bi) => {
      const doneN = b.items.filter(i => this.isDone(i, d)).length;
      const pct = Math.round(100 * doneN / b.items.length);
      const groups = Object.keys(Curriculum.KINDS).map(k => {
        const items = b.items.filter(i => i.kind === k);
        if (!items.length) return '';
        return `<div class="cu-group"><h4>${Curriculum.KINDS[k].icon} ${this.L(Curriculum.KINDS[k].name)}</h4><div class="cu-grid">${items.map(it => {
          const m = this.mastery(it); const ok = this.isDone(it, d);
          return `<button type="button" class="cu-item ${it.status === 'playable' ? 'playable' : ''} ${ok ? 'done' : ''}" data-id="${it.id}">
            <span class="cu-ko">${TKD.esc(it.ko)}</span>
            <span class="cu-name">${TKD.esc(this.L(it.name))}</span>
            <span class="cu-chip">${it.status === 'playable' ? (m !== null ? `▶ ${TKD.num(m)}%` : '▶') : ok ? '✓' : TKD.t('📷 soon', '📷 قريب')}</span>
          </button>`;
        }).join('')}</div></div>`;
      }).join('');
      const open = this.openBelt === b.id;
      return `<section class="cu-belt ${open ? 'open' : ''}" data-belt="${b.id}" style="--belt:${b.color};--belt-2:${b.accent}">
        <button type="button" class="cu-belt-head" aria-expanded="${open}">
          <span class="cu-belt-strip"></span>
          <span class="cu-belt-txt"><b>${TKD.num(bi + 1)}. ${TKD.esc(this.L(b.name))}</b><small>${TKD.esc(this.L(b.geup))} · ${TKD.num(b.items.length)} ${TKD.t('items', 'حاجة')}</small></span>
          <span class="cu-belt-pct"><span style="width:${pct}%"></span></span>
          <span class="cu-belt-n">${TKD.num(doneN)}/${TKD.num(b.items.length)}</span>
        </button>
        <div class="cu-belt-body"><p class="cu-goal">🎯 ${TKD.esc(this.L(b.goal))}</p>${groups}</div>
      </section>`;
    }).join('');

    root.innerHTML = `
      <div class="cu-summary">
        <span><b>${TKD.num(c.belts)}</b> ${TKD.t('belts', 'أحزمة')}</span>
        <span><b>${TKD.num(c.items)}</b> ${TKD.t('techniques', 'حركة')}</span>
        <span><b>${TKD.num(c.poomsae)}</b> ${TKD.t('poomsae', 'بومسي')}</span>
        <span><b>${TKD.num(withMedia)}</b> ${TKD.t('playable now', 'تتلعب دلوقتي')}</span>
      </div>
      <p class="cu-note">${TKD.t('📷 = pictures & videos are on the way. You can already read the tips and tick what you practised at the dojo.', '📷 = الصور والفيديوهات جايين في السكة. تقدر من دلوقتي تقرا النصايح وتعلّم على اللي اتمرنت عليه في النادي.')}</p>
      ${belts}`;

    root.querySelectorAll('.cu-belt-head').forEach(h => h.addEventListener('click', () => {
      const id = h.parentElement.dataset.belt;
      this.openBelt = this.openBelt === id ? '' : id;
      root.querySelectorAll('.cu-belt').forEach(s => { const o = s.dataset.belt === this.openBelt; s.classList.toggle('open', o); s.querySelector('.cu-belt-head').setAttribute('aria-expanded', o); });
    }));
    root.querySelectorAll('.cu-item').forEach(b => b.addEventListener('click', () => this.show(b.dataset.id)));
  },

  show(id) {
    const it = Curriculum.byId(id);
    if (!it) return;
    const belt = Curriculum.BELTS.find(b => b.id === it.belt);
    const ok = this.isDone(it);
    const list = (arr, cls) => arr.length ? `<ul class="${cls}">${arr.map(p => `<li>${TKD.esc(this.L(p))}</li>`).join('')}</ul>` : '';
    const ov = document.createElement('div');
    ov.className = 'tkd-modal cu-modal';
    ov.innerHTML = `<div class="tkd-modal-card cu-card" role="dialog" aria-label="${TKD.esc(it.ko)}" style="--belt:${belt.color};--belt-2:${belt.accent}">
      <div class="cu-media ${this.strobeKey(it) ? 'is-strobe' : ''}"><img src="${this.photo(it)}" alt="${this.strobeKey(it) ? TKD.esc(TKD.t('All five phases of the kick in one picture', 'الخمس مراحل بتوع الركلة في صورة واحدة')) : ''}" onerror="this.parentElement.classList.add('empty');this.remove()"><span class="cu-soon">📷 ${TKD.t('Picture coming soon', 'الصورة جاية قريب')}</span>${this.strobeKey(it) ? `<span class="cu-strobe-tag">🎞️ ${TKD.t('All 5 phases in one picture', 'الخمس مراحل في صورة واحدة')}</span>` : ''}</div>
      <video class="cu-video" controls playsinline preload="metadata" hidden src="${this.video(it)}"${/-tutorial\.mp4$/.test(this.video(it) || '') ? ` poster="${this.video(it).replace(/\.mp4$/, '.webp')}"` : ''} onloadedmetadata="this.hidden=false" onerror="this.remove()">${LearningSystem.captionTracks(this.video(it), TKD.gs()?.currentLanguage === 'ar')}</video>
      <p class="cu-kind">${Curriculum.KINDS[it.kind].icon} ${TKD.esc(this.L(Curriculum.KINDS[it.kind].name))} · ${TKD.esc(this.L(belt.name))}</p>
      <h2>${TKD.esc(it.ko)} <span class="cu-hangul" lang="ko">${TKD.esc(it.hangul)}</span></h2>
      <p class="cu-sub">${TKD.esc(this.L(it.name))}${it.trigram ? ` · ${TKD.esc(it.trigram)}` : ''}${it.aka ? ` · <i>${TKD.esc(this.L(it.aka))}</i>` : ''}</p>
      ${it.points.length ? `<h3>✅ ${TKD.t('Key points', 'أهم النقط')}</h3>${list(it.points, 'cu-points')}` : ''}
      ${it.mistakes.length ? `<h3>⚠️ ${TKD.t('Watch out', 'خلي بالك')}</h3>${list(it.mistakes, 'cu-mistakes')}` : ''}
      <div class="tkd-row cu-actions">
        <button type="button" class="btn" data-a="say">🔊 ${TKD.t('Say it', 'اسمعها')}</button>
        ${it.skillId ? `<button type="button" class="btn btn-primary" data-a="play">▶ ${TKD.t('Train it', 'اتمرن عليها')}</button>`
                     : `<button type="button" class="btn ${ok ? 'btn-primary' : ''}" data-a="tick">${ok ? '✓ ' + TKD.t('Practised', 'اتمرنت عليها') : TKD.t('I practised this', 'اتمرنت عليها في النادي')}</button>`}
        <button type="button" class="btn" data-a="close">${TKD.t('Close', 'اقفل')}</button>
      </div></div>`;
    document.body.appendChild(ov);
    LearningSystem.wireCaptions(ov.querySelector('.cu-video'), TKD.gs()?.currentLanguage === 'ar', null);
    const close = () => ov.remove();
    ov.addEventListener('click', e => { if (e.target === ov) close(); });
    ov.querySelector('[data-a="close"]').addEventListener('click', close);
    ov.querySelector('[data-a="say"]').addEventListener('click', () => {
      // the coach's recording (Korean) if there is one, else a Korean phone voice, else the romanized name
      if (window.Voice?.play(it.hangul, 'ko-KR')) return;
      const koVoice = (window.speechSynthesis?.getVoices() || []).some(v => /^ko/i.test(v.lang));
      SpeechHelper.speak(koVoice ? it.hangul : it.ko, koVoice ? 'ko-KR' : 'en-US');
    });
    ov.querySelector('[data-a="play"]')?.addEventListener('click', () => { close(); switchToSkill(it.skillId); });
    ov.querySelector('[data-a="tick"]')?.addEventListener('click', () => { this.toggle(it.id); close(); this.init(); });
  }
};
window.CurriculumScreen = CurriculumScreen;
Object.assign(window.TKDScreens || (window.TKDScreens = {}), { curriculum: () => CurriculumScreen.init() });

// #####################################################################
// ## learn/review.js
// #####################################################################
// ============================================================================
// SMART REVIEW (v28) — remembers what each child gets wrong, per kick, and
// turns it into ONE clear suggestion for today:
//   "النهارده راجع: رفع الركبة في آب تشاجي"  → opens exactly that lesson step.
// Games report small facts ("missed the chamber note", "picked the wrong part
// of the foot", "kicked a leg target"...) with Review.note(). Old mistakes fade
// (half-life 10 days) and good answers cancel them out, so the suggestion moves
// on as the child improves. Stored per player, on the device only.
// ============================================================================
const Review = {
  HALF_LIFE_DAYS: 10,
  key(pid = TKD.pid()) { return `taekwondoJourneyReview:${pid || 'guest'}`; },
  load(pid) { return TKD.read(this.key(pid), { topics: {}, done: {} }); },
  save(d, pid) { TKD.write(this.key(pid), d); },
  decay(v, dtMs) { return v * Math.pow(0.5, dtMs / (this.HALF_LIFE_DAYS * 864e5)); },

  // what each topic means for a child, and how to fix it
  TOPICS: {
    phase:   { icon: '🦵', en: (s, i) => `${Review.phaseName(s, i, 'en')} in ${TKD.skillName(s)}`, ar: (s, i) => `${Review.phaseName(s, i, 'ar')} في ${TKD.skillName(s)}` },
    surface: { icon: '🦶', en: s => `which part of the foot hits in ${TKD.skillName(s)}`, ar: s => `جزء الرجل اللي بيضرب في ${TKD.skillName(s)}` },
    target:  { icon: '🎯', en: s => `the right targets for ${TKD.skillName(s)}`, ar: s => `الأهداف الصح لـ ${TKD.skillName(s)}` },
    pivot:   { icon: '🔄', en: s => `turning the standing foot in ${TKD.skillName(s)}`, ar: s => `لفّة قدم الارتكاز في ${TKD.skillName(s)}` },
    name:    { icon: '🗣️', en: s => `the Korean name of ${TKD.skillName(s)}`, ar: s => `الاسم الكوري لـ ${TKD.skillName(s)}` },
    timing:  { icon: '⏱️', en: s => `the timing of ${TKD.skillName(s)}`, ar: s => `توقيت ${TKD.skillName(s)}` },
    head:    { icon: '👀', en: s => `eyes on the target in ${TKD.skillName(s)}`, ar: s => `عينك على الهدف في ${TKD.skillName(s)}` },
    knee:    { icon: '🦿', en: s => `a fully straight kicking knee in ${TKD.skillName(s)}`, ar: s => `فرد ركبة الركلة على الآخر في ${TKD.skillName(s)}` },
    lean:    { icon: '🧍', en: s => `keeping the back upright in ${TKD.skillName(s)}`, ar: s => `ضهرك مفرود في ${TKD.skillName(s)}` },
    heel:    { icon: '🦶', en: s => `a planted standing heel in ${TKD.skillName(s)}`, ar: s => `كعب قدم الارتكاز ثابت في ${TKD.skillName(s)}` },
    guard:   { icon: '🛡️', en: s => `keeping the guard up in ${TKD.skillName(s)}`, ar: s => `إيديك مرفوعة للحماية في ${TKD.skillName(s)}` }
  },
  phaseName(s, i, lang) {
    const ph = GameConfig.SKILLS[s]?.phases?.[i]; if (!ph) return '';
    return (lang === 'ar' ? ph.title.ar : ph.title.en).replace(/^[^\p{L}]+/u, '').replace(/\s*\(.*\)\s*$/, '');
  },
  // where to practise it
  fixFor(topic, s, i) {
    const lesson = (phase) => ({ kind: 'lesson', phase, go: () => this.openLesson(s, phase) });
    const game = (g) => ({ kind: 'game', game: g, go: () => { const gs = TKD.gs(); gs.currentSkill = s; gs.syncFlatProgressToCurrentSkill?.(); switchScreen(g); } });
    return ({
      phase: () => lesson(i), surface: () => game('board-break'), target: () => game('sparring-duel'), pivot: () => lesson(1),
      name: () => game('quiz-blast'), timing: () => game('heavy-bag'), head: () => lesson(2), knee: () => lesson(2), lean: () => lesson(2), heel: () => lesson(2), guard: () => lesson(0)
    }[topic] || (() => lesson(0)))();
  },
  openLesson(s, phase) {
    const gs = TKD.gs(); if (!gs) return;
    gs.currentSkill = s; gs.syncFlatProgressToCurrentSkill?.();
    switchScreen('learning');
    setTimeout(() => { LearningSystem.currentPhase = Math.max(0, Math.min(4, phase)); LearningSystem.render(); }, 60);
  },

  // ------------------------------------------------------------------ recording
  note(topic, ok, { skill, phase = null, weight = 1 } = {}) {
    const pid = TKD.pid(); if (!pid || !this.TOPICS[topic]) return;
    skill = skill || TKD.gs()?.currentSkill || 'apchagi';
    const id = `${skill}|${topic}${phase !== null && topic === 'phase' ? '|' + phase : ''}`;
    const d = this.load(pid), now = Date.now();
    const t = d.topics[id] || { m: 0, h: 0, t: now };
    t.m = this.decay(t.m, now - t.t); t.h = this.decay(t.h, now - t.t); t.t = now;
    if (ok) t.h += weight; else t.m += weight;
    d.topics[id] = t;
    // a good answer on today's review topic = review done
    const today = this.today(pid, d);
    if (ok && today && today.id === id && t.h >= 1) d.done[TKD.dayKey()] = id;
    this.save(d, pid);
  },
  // ------------------------------------------------------------------ reading
  list(pid = TKD.pid()) {
    const d = this.load(pid), now = Date.now();
    return Object.entries(d.topics).map(([id, t]) => {
      const [skill, topic, phase] = id.split('|');
      const m = this.decay(t.m, now - t.t), h = this.decay(t.h, now - t.t);
      return { id, skill, topic, phase: phase !== undefined ? +phase : null, misses: m, hits: h, weak: m - 0.7 * h };
    }).filter(x => GameConfig.SKILLS[x.skill] && this.TOPICS[x.topic]).sort((a, b) => b.weak - a.weak);
  },
  weakest(pid, n = 3) { return this.list(pid).filter(x => x.weak >= 1.2 && x.misses >= 2).slice(0, n); },
  today(pid = TKD.pid(), d = null) { return this.weakest(pid, 1)[0] || null; },
  doneToday(pid = TKD.pid()) { return !!this.load(pid).done[TKD.dayKey()]; },
  label(x) {
    const T = this.TOPICS[x.topic];
    return `${T.icon} ${TKD.ar ? T.ar(x.skill, x.phase) : T.en(x.skill, x.phase)}`;
  },
  // classify a quiz question by its (English) wording
  topicFromText(en) {
    const s = String(en || '').toLowerCase();
    if (/korean|called|name/.test(s)) return { topic: 'name' };
    if (/part of the foot|surface|strik|contact|delivered/.test(s)) return { topic: 'surface' };
    if (/target|score|scores|aim/.test(s)) return { topic: 'target' };
    if (/pivot|rotate|turn|angle|degree/.test(s)) return { topic: 'pivot' };
    const m = s.match(/(first|second|third|fourth|fifth|last|final|1st|2nd|3rd|4th|5th)\s+(phase|stage|step)|(phase|stage|step)\s+(\d)/);
    if (m) { const w = m[1] || m[4]; const i = { first: 0, '1st': 0, 1: 0, second: 1, '2nd': 1, 2: 1, third: 2, '3rd': 2, 3: 2, fourth: 3, '4th': 3, 4: 3, fifth: 4, '5th': 4, 5: 4, last: 4, final: 4 }[w]; return { topic: 'phase', phase: i ?? 0 }; }
    if (/chamber|knee lift|lift the knee|raise/.test(s)) return { topic: 'phase', phase: 1 };
    if (/extend|extension|snap/.test(s)) return { topic: 'phase', phase: 2 };
    if (/recoil|pull back|retract/.test(s)) return { topic: 'phase', phase: 3 };
    if (/ready|stance|guard/.test(s)) return { topic: 'phase', phase: 0 };
    return null;
  },
  noteText(en, ok, skill) { const t = this.topicFromText(en); if (t) this.note(t.topic, ok, { skill, phase: t.phase ?? null }); },

  // ------------------------------------------------------------------ home card
  card() {
    if (!TKD.pid()) return '';
    const x = this.today(); if (!x) return '';
    const done = this.doneToday();
    const fix = this.fixFor(x.topic, x.skill, x.phase);
    return `<button type="button" class="hub-review ${done ? 'done' : ''}" id="hub-review">
      <span class="hub-rv-k">${done ? '✅' : '🧠'} ${done ? TKD.t('Reviewed today — well done!', 'راجعت النهارده — برافو!') : TKD.t("Today's review", 'مراجعة النهارده')}</span>
      <span class="hub-rv-big">${TKD.esc(this.label(x))}</span>
      <span class="hub-rv-s">${fix.kind === 'lesson' ? TKD.t('Open the lesson step →', 'افتح خطوة الدرس ←') : TKD.t(`Practise in ${TKD.gameName(fix.game)} →`, `اتمرّن في ${TKD.gameName(fix.game)} ←`)}</span>
    </button>`;
  },
  bindCard() {
    const b = TKD.$('hub-review'); if (!b) return;
    b.addEventListener('click', () => {
      const x = this.today(); if (!x) return;
      TKD.gs()?.playSound('click');
      // opening the lesson step itself counts as a first look
      const fix = this.fixFor(x.topic, x.skill, x.phase);
      if (fix.kind === 'lesson') { const d = this.load(); d.done[TKD.dayKey()] = x.id; this.save(d); }
      fix.go();
    });
  }
};
window.Review = Review;

// #####################################################################
// ## ui/journey.js
// #####################################################################
// ============================================================================
// THE JOURNEY (v29 → v30 adventure map) — the child always sees ONE road and
// ONE next step.
//   🔥 warm-up → 🎓 learn → 🎭 🧩 👁️ ⚡ four games → 📝 test → 🎁 treasure
// The road snakes across the card like a board game. Finished stations keep
// their stars, the child's own fighter stands on the station that is next, the
// road fills up as they go, and the treasure chest at the end opens when the
// kick is mastered. Every screen that ends (a game, the warm-up, a lesson)
// offers the same next step, so nobody ever has to hunt through a menu.
// All looping motion is transform/opacity only (runs on the GPU compositor).
// ============================================================================
const Journey = {
  GAMES: ['form-control', 'puzzle', 'performance', 'action'],       // the 4 that a kick needs
  KEY: { 'form-control': 'formControl', puzzle: 'puzzle', performance: 'performance', action: 'action' },
  SHORT: {                                                          // station labels must fit under a 60 px button
    'form-control': { en: 'Pose', ar: 'الوضعية' },
    puzzle: { en: 'Phases', ar: 'المراحل' },
    performance: { en: "Judge's eye", ar: 'عين الحكم' },
    action: { en: 'Strike', ar: 'الضربة' }
  },
  skill() {
    const gs = TKD.gs(); if (!gs) return 'apchagi';
    const t = gs.getResumeTarget();
    return t.done ? gs.currentSkill : t.skillId;
  },
  scores(skillId) { return TKD.gs()?.skillGameScores?.[skillId] || {}; },
  gamesDone(skillId) { const s = this.scores(skillId); return this.GAMES.filter(g => (s[this.KEY[g]] || 0) > 0).length; },
  nextGame(skillId) { const s = this.scores(skillId); return this.GAMES.find(g => !(s[this.KEY[g]] > 0)) || null; },
  // ⭐ for a score: anything counts, 75+ is good, 90+ is perfect
  starsFor(score) { return score >= 90 ? 3 : score >= 75 ? 2 : score > 0 ? 1 : 0; },

  // the eight stations of the current kick
  steps(skillId = this.skill()) {
    const s = this.scores(skillId), gs = TKD.gs();
    const sc = k => s[k] || 0;
    const complete = !!gs?.completedSkills?.has(skillId);
    const allGames = this.gamesDone(skillId) >= this.GAMES.length;
    const st = [
      { id: 'warmup', stage: 'warmup', icon: '🔥', en: 'Warm-up', ar: 'الإحماء', done: sc('warmup') > 0, stars: sc('warmup') > 0 ? 3 : 0, go: () => switchScreen('warmup') },
      { id: 'learning', stage: 'learning', icon: '🎓', en: 'Learn it', ar: 'اتعلمها', done: sc('learning') > 0, stars: sc('learning') > 0 ? 3 : 0, go: () => switchScreen('learning') },
      ...this.GAMES.map(g => ({
        id: 'g:' + g, stage: 'games', game: g, icon: TKD.gameIcon(g), en: this.SHORT[g].en, ar: this.SHORT[g].ar,
        done: sc(this.KEY[g]) > 0, stars: this.starsFor(sc(this.KEY[g])), go: () => switchScreen(g)
      })),
      { id: 'quiz', stage: 'quiz', icon: '📝', en: 'The test', ar: 'الاختبار', done: sc('quiz') > 0, stars: this.starsFor(sc('quiz')), go: () => switchScreen(allGames ? 'quiz' : 'games') },
      { id: 'chest', stage: 'chest', icon: complete ? '🏅' : '🎁', en: 'Treasure', ar: 'الكنز', done: complete, stars: 0, go: () => switchScreen('trophy-room') }
    ];
    // the first unfinished station is "now"; everything after it is locked
    const i = st.findIndex(x => !x.done);
    st.forEach((x, k) => { x.state = x.done ? 'done' : k === i ? 'now' : 'locked'; });
    return st;
  },
  starTotal(st) { return st.reduce((a, x) => a + x.stars, 0); },
  starMax(st) { return st.filter(x => x.id !== 'chest').length * 3; },

  // the single next action (used by the home button and by every "what now?" moment)
  next() {
    const gs = TKD.gs();
    if (!gs) return null;
    const t = gs.getResumeTarget();
    if (t.done) return { icon: '🏆', label: TKD.t('See your trophies', 'شوف إنجازاتك'), step: 'done', stage: 'done', go: () => switchScreen('trophy-room') };
    const skillId = t.skillId, st = this.steps(skillId), now = st.find(x => x.state === 'now') || st[0];
    const name = TKD.skillName(skillId);
    const label = now.game ? TKD.t(`Play: ${TKD.gameName(now.game)}`, `العب: ${TKD.gameName(now.game)}`) : {
      warmup: TKD.t('Start the warm-up', 'ابدأ الإحماء'),
      learning: TKD.t(`Learn ${name}`, `اتعلم ${name}`),
      quiz: TKD.t(`Take the ${name} test`, `امتحن في ${name}`),
      chest: TKD.t('Open the treasure', 'افتح الكنز')
    }[now.id];
    return { icon: now.icon, label, step: now.id, stage: now.stage, skillId, go: () => { gs.currentSkill = skillId; gs.syncFlatProgressToCurrentSkill?.(); gs.saveToStorage?.(); now.go(); } };
  },

  // ------------------------------------------------------------------ the board geometry
  // 8 stations on a 300 × 330 board: three rows that snake like a board game
  // (right → left first in Arabic). Positions are in board units; the HTML uses %.
  BOARD: { w: 300, h: 342, rows: [54, 162, 270], cols: [250, 150, 50] },
  layout(n = 8) {
    const B = this.BOARD, rtl = TKD.ar, pts = [];
    for (let i = 0; i < n + 1; i++) {                                   // +1 = the sign to the next kick
      const row = Math.floor(i / 3), c = i % 3;
      let x = row % 2 === 0 ? B.cols[c] : B.cols[2 - c];
      if (!rtl) x = B.w - x;
      pts.push({ x, y: B.rows[row] });
    }
    return pts;
  },
  // one smooth road through the stations: straight runs + U-turns at the ends
  road(pts) {
    let d = `M${pts[0].x} ${pts[0].y}`;
    const segs = [];
    for (let i = 1; i < pts.length; i++) {
      const a = pts[i - 1], b = pts[i];
      if (a.y === b.y) { d += ` L${b.x} ${b.y}`; segs.push(Math.abs(b.x - a.x)); continue; }
      const out = a.x > this.BOARD.w / 2 ? 42 : -42;                   // bulge outwards
      const c1 = { x: a.x + out, y: a.y }, c2 = { x: b.x + out, y: b.y };
      d += ` C${c1.x} ${c1.y} ${c2.x} ${c2.y} ${b.x} ${b.y}`;
      segs.push(this.bezLen(a, c1, c2, b));
    }
    const total = segs.reduce((x, y) => x + y, 0);
    const at = [0]; segs.reduce((acc, l) => { acc += l; at.push(acc / total); return acc; }, 0);
    return { d, at };                                                  // at[i] = 0…1 position of station i on the road
  },
  // the fighter stands on the road next to its station (towards the middle of the board)
  stagePos(p) { return { x: p.x + (p.x > this.BOARD.w / 2 ? -44 : 44), y: p.y + 20 }; },
  bezLen(p0, p1, p2, p3) {
    let len = 0, px = p0.x, py = p0.y;
    for (let i = 1; i <= 24; i++) {
      const t = i / 24, u = 1 - t;
      const x = u * u * u * p0.x + 3 * u * u * t * p1.x + 3 * u * t * t * p2.x + t * t * t * p3.x;
      const y = u * u * u * p0.y + 3 * u * u * t * p1.y + 3 * u * t * t * p2.y + t * t * t * p3.y;
      len += Math.hypot(x - px, y - py); px = x; py = y;
    }
    return len;
  },

  // ------------------------------------------------------------------ home: the map
  html() {
    const skillId = this.skill(), st = this.steps(skillId), n = this.next(), gs = TKD.gs();
    const order = GameConfig.SKILL_ORDER, ki = Math.max(0, order.indexOf(skillId));
    const pts = this.layout(st.length), road = this.road(pts), B = this.BOARD;
    const nowI = st.findIndex(x => x.state === 'now');
    const reach = nowI < 0 ? 1 : road.at[nowI];
    const nextKick = order[ki + 1];
    const pct = (p) => `left:${(100 * p.x / B.w).toFixed(2)}%;top:${(100 * p.y / B.h).toFixed(2)}%`;
    const starRow = (x) => x.id === 'chest' ? '' : `<span class="jr-st-stars" aria-hidden="true">${[1, 2, 3].map(k => `<i class="${k <= x.stars ? 'on' : ''}" style="--k:${k}">★</i>`).join('')}</span>`;
    const kicks = order.map((id, i) => {
      const state = gs?.completedSkills?.has(id) ? 'done' : id === skillId ? 'now' : 'locked';
      return `<li class="jr-kick is-${state}"><span>${state === 'done' ? '✓' : state === 'locked' ? '🔒' : '🦶'}</span>${TKD.esc(TKD.skillName(id))}</li>`;
    }).join('');
    const stars = this.starTotal(st), max = this.starMax(st);
    return `<section class="jr jr-map" aria-label="${TKD.t('My journey', 'رحلتي')}" data-skill="${skillId}">
      <header class="jr-head">
        <div class="jr-title"><b>🗺️ ${TKD.t(`${TKD.skillName(skillId)} adventure`, `مغامرة ${TKD.skillName(skillId)}`)}</b>
          <small>${TKD.t(`Kick ${ki + 1} of ${order.length}`, `الركلة ${TKD.num(ki + 1)} من ${TKD.num(order.length)}`)}</small></div>
        <div class="jr-stars" title="${TKD.t('Stars on this map', 'نجوم الخريطة دي')}"><span class="jr-star-ico">⭐</span><b id="jr-star-n">${TKD.num(stars)}</b><small>/${TKD.num(max)}</small></div>
      </header>
      ${n ? `<button type="button" class="jr-go" id="jr-go"><span class="jr-go-ico">${n.icon}</span><span class="jr-go-txt"><b>${TKD.esc(n.label)}</b><small>${TKD.t('tap to start', 'دوس عشان تبدأ')}</small></span><span class="jr-go-arrow">${TKD.ar ? '←' : '→'}</span></button>` : ''}
      <div class="jr-board" id="jr-board" style="--reach:${reach.toFixed(4)}">
        <svg class="jr-road" viewBox="0 0 ${B.w} ${B.h}" aria-hidden="true" focusable="false">
          <defs><linearGradient id="jr-fill" x1="0" x2="1"><stop offset="0" stop-color="#ffd166"/><stop offset="1" stop-color="#ff6b35"/></linearGradient></defs>
          <path class="jr-road-edge" d="${road.d}"/>
          <path class="jr-road-bed" d="${road.d}"/>
          <path class="jr-road-dash" d="${road.d}"/>
          <path class="jr-road-fill" d="${road.d}" pathLength="1"/>
        </svg>
        ${st.map((x, i) => `
        <div class="jr-step is-${x.state} ${x.id === 'chest' ? 'is-chest' : ''}" data-step="${x.id}" style="${pct(pts[i])};--i:${i}">
          <button type="button" class="jr-dot" data-go="${x.id}" aria-label="${TKD.esc(TKD.ar ? x.ar : x.en)}${x.state === 'locked' ? ' — ' + TKD.t('locked', 'مقفول') : x.state === 'done' ? ' — ' + TKD.t('done', 'خلصت') : ''}">
            <span class="jr-ico">${x.state === 'locked' && x.id !== 'chest' ? '🔒' : x.icon}</span>
            ${x.state === 'done' && x.id !== 'chest' ? '<span class="jr-check" aria-hidden="true">✓</span>' : ''}
          </button>
          ${starRow(x)}
          <span class="jr-lbl">${TKD.esc(TKD.ar ? x.ar : x.en)}</span>
        </div>`).join('')}
        <div class="jr-sign" style="${pct(pts[st.length])}" aria-hidden="true">${nextKick
          ? `<span>🔒</span><small>${TKD.t('Next', 'الجاية')}: ${TKD.esc(TKD.skillName(nextKick))}</small>`
          : `<span>🥋</span><small>${TKD.t('Next belt!', 'الحزام الجاي!')}</small>`}</div>
        <div class="jr-stage" id="jr-stage" style="${pct(this.stagePos(pts[nowI < 0 ? st.length - 1 : nowI]))}"></div>
      </div>
      <ol class="jr-kicks" aria-label="${TKD.t('The kicks', 'الركلات')}">${kicks}</ol>
    </section>`;
  },
  bind(root = document) {
    // the child's own fighter stands on the station that is next
    const stage = root.querySelector('#jr-stage');
    const ch = TKD.gs()?.playerCharacter === 'girl' ? 'girl' : 'boy';
    const fallback = () => { if (stage) TKD.gs()?.createCharacterVisual('jr-stage', ch, 'IDLE'); };
    if (stage && window.RigSprite) {
      this.sprite = new RigSprite(stage, { ch, anim: 'idle', tap: 'win', height: 84 });
      this.sprite.start().then(ok => { if (!ok) fallback(); });
    } else fallback();
    root.querySelector('#jr-go')?.addEventListener('click', () => {
      TKD.gs()?.playSound('click'); window.AudioKit?.sfx('ui-pop', { gain: 0.5 });
      const step = this.next()?.step || '';
      this.sprite?.play(step.startsWith('g:') || step === 'quiz' ? 'win' : 'apchagi');
      setTimeout(() => this.next()?.go(), 200);
    });
    root.querySelectorAll('.jr-dot').forEach(b => b.addEventListener('click', () => {
      const id = b.dataset.go, st = this.steps().find(x => x.id === id);
      if (!st) return;
      const box = b.closest('.jr-step');
      if (st.state === 'locked') {
        box?.classList.remove('shake'); void box?.offsetWidth; box?.classList.add('shake');
        TKD.toast(st.id === 'chest'
          ? TKD.t('The treasure opens after the test 🎁', 'الكنز بيتفتح بعد الاختبار 🎁')
          : TKD.t('Finish the step before it first 😊', 'خلّص اللي قبلها الأول 😊'), 'warning');
        TKD.gs()?.playSound('error');
        return;
      }
      TKD.gs()?.playSound('click');
      box?.classList.add('tapped');
      const gs = TKD.gs(); if (gs) { gs.currentSkill = this.skill(); gs.syncFlatProgressToCurrentSkill?.(); }
      setTimeout(() => st.go(), 140);
    }));
    // the road fills to where the child is (animated once on first paint)
    const board = root.querySelector('#jr-board');
    if (board && !this._noIntro) { board.classList.add('intro'); requestAnimationFrame(() => requestAnimationFrame(() => board.classList.remove('intro'))); }
  },

  // ------------------------------------------------------------------ "what now?" button used after a game / lesson / warm-up
  nextButtonHTML(id = 'jr-next-btn') {
    const n = this.next(); if (!n) return '';
    return `<button type="button" class="btn btn-success jr-next" id="${id}">${n.icon} ${TKD.t('Next:', 'الخطوة الجاية:')} ${TKD.esc(n.label)} ${TKD.ar ? '←' : '→'}</button>`;
  },
  bindNextButton(id = 'jr-next-btn') {
    const b = document.getElementById(id); if (!b) return;
    b.addEventListener('click', () => { TKD.gs()?.playSound('click'); this.next()?.go(); });
  }
};
window.Journey = Journey;

// ---------------------------------------------------------------- first-time welcome
Object.assign(Journey, {
  welcomeKey() { return `taekwondoJourneyWelcome:${TKD.pid() || 'guest'}`; },
  welcome(root = document) {
    if (!TKD.pid() || TKD.read(this.welcomeKey(), false)) return;
    if (document.querySelector('.jr-coach')) return;
    const anchor = root.querySelector('.jr') || root.querySelector('#jr-go'); if (!anchor) return;
    const p = PlayerSystem.getCurrentPlayer();
    const box = document.createElement('div');
    box.className = 'jr-coach';
    box.innerHTML = `<div class="jr-coach-inner">
      <img class="jr-coach-img" src="${PoseShots.url('coach', 'coach')}" alt="">
      <div class="jr-coach-bubble">
        <b>${TKD.t('Hi! I am Coach Yang 👋', 'أهلًا! أنا الكوتش يانج 👋')}</b>
        <p>${TKD.t(`${p?.name || ''}, this is your map! Walk the road one station at a time, collect the stars ⭐ — and at the end there's a treasure 🎁.`, `يا ${p?.name || 'بطل'}، دي خريطتك! امشي على الطريق محطة محطة، واجمع النجوم ⭐، وفي الآخر فيه كنز مستنيك 🎁.`)}</p>
        <button type="button" class="btn btn-success" data-a="go">${TKD.t("Let's go! 🚀", 'يلا بينا! 🚀')}</button>
      </div></div>`;
    anchor.after(box);
    // v43: the 3D Coach Yang bows hello in place of his picture (the picture stays if 3D is off)
    if (window.RigSprite && window.RigBackend) RigBackend.lib().then(r => {
      const img = box.querySelector('.jr-coach-img'); if (!r || !img || !box.isConnected) return;
      const host = document.createElement('div'); host.className = 'jr-coach-3d'; img.replaceWith(host);
      new RigSprite(host, { ch: 'coach', anim: 'coach_idle', tap: 'bow', intro: 'bow', height: 130 }).start();
    });
    const close = () => { TKD.write(this.welcomeKey(), true); box.remove(); };
    box.querySelector('[data-a="go"]').addEventListener('click', () => { close(); this.next()?.go(); });
    box.addEventListener('click', (e) => { if (e.target === box) close(); });          // tap outside the bubble
    const bye = (e) => { if (e.detail?.screenId !== 'home') { document.removeEventListener('tkd:screen', bye); close(); } };
    document.addEventListener('tkd:screen', bye);                                      // never left hanging
    TKD.speak(TKD.t('This is your map. Walk the road and collect the stars!', 'دي خريطتك. امشي على الطريق واجمع النجوم!'));
    setTimeout(close, 14000);
  }
});

// ---------------------------------------------------------------- celebrations
// Coming back to the map after finishing something: the station pops, its stars
// fly in one by one, the road fills to the new station and the fighter hops
// there. Finishing a whole kick opens the treasure chest.
Object.assign(Journey, {
  snapKey() { return `taekwondoJourneySteps:${TKD.pid() || 'guest'}`; },
  reduced() { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; },
  celebrate(root = document) {
    // the hub also re-renders in the background (player switch, sync) — only replay what the child can SEE
    if (!document.getElementById('home-screen')?.classList.contains('active')) return;
    const gs = TKD.gs(), skill = this.skill(), st = this.steps(skill);
    const snap = { skill, done: st.filter(x => x.done).map(x => x.id), stars: Object.fromEntries(st.map(x => [x.id, x.stars])), completed: [...(gs?.completedSkills || [])] };
    const before = TKD.read(this.snapKey(), null);
    TKD.write(this.snapKey(), snap);
    if (!before || Array.isArray(before)) return;                     // first visit (or the v29 format) → nothing to replay
    const newKick = snap.completed.find(id => !(before.completed || []).includes(id));
    if (newKick) { this.treasure(newKick); return; }
    if (before.skill !== skill) return;
    const fresh = st.filter(x => x.done && !before.done.includes(x.id));
    const moreStars = st.filter(x => x.done && before.done.includes(x.id) && x.stars > (before.stars?.[x.id] || 0));
    if (!fresh.length && !moreStars.length) return;
    const board = root.querySelector('#jr-board');
    const reduced = this.reduced();
    // 1) the road and the fighter start where they were…
    if (board && !reduced) {
      const pts = this.layout(st.length), road = this.road(pts), B = this.BOARD;
      const prevNow = st.findIndex(x => !before.done.includes(x.id));
      if (prevNow >= 0 && fresh.length) {
        board.style.setProperty('--reach', road.at[prevNow].toFixed(4));
        const stg = board.querySelector('#jr-stage'), to = { left: stg?.style.left, top: stg?.style.top };
        const sp = this.stagePos(pts[prevNow]);
        if (stg) { stg.classList.add('no-tr'); stg.style.left = `${(100 * sp.x / B.w).toFixed(2)}%`; stg.style.top = `${(100 * sp.y / B.h).toFixed(2)}%`; void stg.offsetWidth; stg.classList.remove('no-tr'); }
        // 2) …then move on once the stars have landed
        setTimeout(() => {
          const nowI = st.findIndex(x => x.state === 'now');
          board.style.setProperty('--reach', (nowI < 0 ? 1 : road.at[nowI]).toFixed(4));
          if (stg) { stg.classList.add('hop'); stg.style.left = to.left; stg.style.top = to.top; setTimeout(() => stg.classList.remove('hop'), 900); }
          window.AudioKit?.sfx('whoosh-1', { gain: 0.35 });
        }, 700 + fresh.length * 450);
      }
    }
    [...fresh, ...moreStars].forEach((x, k) => setTimeout(() => {
      const box = root.querySelector(`.jr-step[data-step="${x.id}"]`); if (!box) return;
      box.classList.add('just-done');
      const dot = box.querySelector('.jr-dot');
      if (dot && !reduced) for (let i = 0; i < 12; i++) {
        const s = document.createElement('i');
        s.className = 'jr-spark';
        s.style.setProperty('--a', `${(360 / 12) * i}deg`);
        dot.appendChild(s);
        setTimeout(() => s.remove(), 900);
      }
      box.querySelectorAll('.jr-st-stars i.on').forEach((star, j) => {
        star.classList.add('fly');
        setTimeout(() => window.AudioKit?.sfx('star', { gain: 0.4, rate: 1 + j * 0.12 }), 180 + j * 160);
      });
      setTimeout(() => box.classList.remove('just-done'), 1400);
    }, 350 + k * 450));
    // the star counter counts up to the new total
    const n = root.querySelector('#jr-star-n');
    const from = Object.values(before.stars || {}).reduce((a, b) => a + b, 0);
    if (n && !reduced) { n.textContent = TKD.num(from); setTimeout(() => window.tkdCountUp(n, this.starTotal(st), { dur: 900, from }), 500); }
  },
  // a whole kick mastered → the treasure chest opens
  treasure(skillId) {
    if (document.querySelector('.jr-treasure')) return;
    const nextId = GameConfig.SKILL_ORDER[GameConfig.SKILL_ORDER.indexOf(skillId) + 1];
    // v55: the chest also holds a real present for the Star Shop, already put on
    const gift = window.Shop?.grant?.(({ apchagi: 'hb-red', narochagi: 'party-stars', bakchagi3: 'frame-gold' })[skillId]);
    const box = document.createElement('div');
    box.className = 'jr-treasure' + (this.reduced() ? ' still' : '');
    box.setAttribute('role', 'dialog');
    box.innerHTML = `<div class="jr-tr-card">
      <div class="jr-tr-rays" aria-hidden="true"></div>
      <div class="jr-tr-chest" aria-hidden="true"><span class="jr-tr-closed">🎁</span><span class="jr-tr-open">🏅</span></div>
      <h3>${TKD.t(`You mastered ${TKD.skillName(skillId)}!`, `إنت كده قفلت ${TKD.skillName(skillId)}!`)}</h3>
      <p>${TKD.t('The treasure is open — your medal is in the trophy room.', 'الكنز اتفتح — الميدالية بتاعتك في أوضة الإنجازات.')}</p>
      ${gift ? `<p class="jr-tr-gift">🎁 ${TKD.t(`And a present: the ${gift.en} — you already have it on!`, `وكمان هدية: ${gift.ar} — لابسها دلوقتي!`)}</p>` : ''}
      ${nextId ? `<p class="jr-tr-next">🦶 ${TKD.t('Next adventure', 'المغامرة الجاية')}: <b>${TKD.esc(TKD.skillName(nextId))}</b></p>` : ''}
      <button type="button" class="btn btn-success" data-a="ok">${nextId ? TKD.t("On to the next kick! 🚀", 'يلا على الركلة الجاية! 🚀') : TKD.t('See my trophies 🏆', 'شوف إنجازاتي 🏆')}</button>
    </div>`;
    document.body.appendChild(box);
    for (let i = 0; i < 18 && !this.reduced(); i++) {
      const c = document.createElement('i');
      c.className = 'jr-confetti';
      c.style.setProperty('--x', `${Math.round(Math.random() * 100)}%`);
      c.style.setProperty('--d', `${(Math.random() * 0.6).toFixed(2)}s`);
      c.style.setProperty('--h', `${Math.round(Math.random() * 360)}`);
      box.appendChild(c);
    }
    window.AudioKit?.sfx('taiko', { gain: 0.6 });
    setTimeout(() => { box.classList.add('open'); window.AudioKit?.sfx('win', { gain: 0.6 }); }, this.reduced() ? 0 : 900);
    const close = () => box.remove();
    box.querySelector('[data-a="ok"]').addEventListener('click', () => { close(); if (!nextId) switchScreen('trophy-room'); });
    box.addEventListener('click', (e) => { if (e.target === box) close(); });
    const bye = (e) => { if (e.detail?.screenId !== 'home') { document.removeEventListener('tkd:screen', bye); close(); } };
    document.addEventListener('tkd:screen', bye);
  }
});

// number that counts up — used for scores and points
window.tkdCountUp = function (el, to, { dur = 900, suffix = '', from = 0 } = {}) {
  if (!el) return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const num = n => (typeof TKD !== 'undefined' && TKD.ar ? TKD.num(n) : String(n));
  if (reduce) { el.textContent = num(to) + suffix; return; }
  const t0 = performance.now();
  const tick = (t) => {
    const k = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - k, 3);
    el.textContent = num(Math.round(from + (to - from) * e)) + suffix;
    if (k < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
};

// ---------------------------------------------------------------- lite mode for slow phones
// A phone with ≤4 cores or ≤3 GB of memory — or one on which a game already had
// to lower its render scale — gets html.lite: decorative loops off, fewer particles.
(function tkdLite() {
  let q = 1; try { q = +localStorage.getItem('tkdRenderQ') || 1; } catch (e) {}
  const weak = (navigator.hardwareConcurrency || 8) <= 4 || (navigator.deviceMemory || 8) <= 3 || q <= 0.75;
  document.documentElement.classList.toggle('lite', weak);
  window.TKDLite = () => document.documentElement.classList.contains('lite');
})();

// #####################################################################
// ## ui/tabbar.js
// #####################################################################
// ============================================================================
// BOTTOM TAB BAR (v28) — replaces the 20-button side menu.
// Four big tabs a child can hit with a thumb: اتمرّن · العب · إنجازاتي · المدرب.
// Each tab opens a sheet of large tiles; the tab of the current screen is lit.
// ============================================================================
const TabBar = {
  TABS: [
    { id: 'train', icon: '🥋', en: 'Train', ar: 'اتمرّن', screens: ['home', 'warmup', 'skill-menu', 'learning', 'curriculum', 'quiz', 'cooldown'],
      items: [
        { icon: '🏠', en: 'Home', ar: 'الرئيسية', go: () => switchScreen('home') },
        { icon: '▶️', en: "Let's train!", ar: 'يلا نتمرن!', go: () => (window.resumeTraining ? resumeTraining() : switchScreen('home')), hot: true },
        { icon: '🔥', en: 'Warm-up', ar: 'الإحماء', go: () => switchScreen('warmup') },
        { icon: '🎓', en: 'Learning', ar: 'التعلم', go: () => switchScreen('skill-menu') },
        { icon: '📚', en: 'Belt syllabus', ar: 'منهج الأحزمة', go: () => switchScreen('curriculum') },
        { icon: '📝', en: 'The test', ar: 'الاختبار', go: () => attemptStageNav('quiz') },
        { icon: '🧘', en: 'Cool-down', ar: 'التهدئة', go: () => switchScreen('cooldown') }
      ] },
    { id: 'play', icon: '🎮', en: 'Play', ar: 'العب', screens: ['games', 'form-control', 'puzzle', 'performance', 'action', 'error-hunt', 'quiz-blast', 'board-break', 'paddle-reflex', 'phase-rhythm', 'sparring-duel', 'balance-hold', 'heavy-bag', 'league', 'versus'],
      items: [
        { icon: '🎮', en: 'All games', ar: 'كل الألعاب', go: () => attemptStageNav('games'), hot: true },
        { icon: '🏆', en: "Today's challenge", ar: 'تحدي النهارده', go: () => (window.Challenge ? Challenge.start() : switchScreen('league')) },
        { icon: '🏅', en: 'Weekly league', ar: 'الدوري', go: () => { LeagueScreen.tab = 'league'; switchScreen('league'); } },
        { icon: '🏟️', en: 'Club heroes', ar: 'أبطال النادي', go: () => { LeagueScreen.tab = 'gym'; switchScreen('league'); } },
        { icon: '⚔️', en: 'Challenge a friend', ar: 'تحدّى صاحبك', go: () => switchScreen('versus') }
      ] },
    { id: 'mine', icon: '⭐', en: 'My stars', ar: 'إنجازاتي', screens: ['profile', 'trophy-room', 'players', 'character-change', 'winner'],
      items: [
        { icon: '🦸', en: 'My hero page', ar: 'صفحتي', go: () => Profile.open(), hot: true },
        { icon: '🏆', en: 'Trophy room', ar: 'فاترينة الإنجازات', go: () => switchScreen('trophy-room') },
        { icon: '👥', en: 'All players', ar: 'كل اللاعبين', go: () => switchScreen('players') },
        { icon: '🧒', en: 'Change character', ar: 'غيّر الشخصية', go: () => switchScreen('character-change') },
        { icon: '🔁', en: 'Switch player', ar: 'غيّر اللاعب', go: () => StartScreen.show() }
      ] },
    { id: 'coach', icon: '👩‍🏫', en: 'Coach', ar: 'المدرب', screens: ['coach', 'dashboard', 'report'],
      items: [
        { icon: '👩‍🏫', en: 'Coach mode', ar: 'وضع المدرب', go: () => Coach.open(), hot: true },
        { icon: '📊', en: 'Player dashboard', ar: 'لوحة اللاعبين', go: () => switchScreen('dashboard') },
        { icon: '📈', en: 'Progress report', ar: 'تقرير التقدم', go: () => switchScreen('report') },
        { icon: '💾', en: 'Save backup', ar: 'احفظ نسخة', go: () => exportProgress() },
        // v55: replacing or erasing every child's progress is for the coach / parent → PIN first
        { icon: '📂', en: 'Restore backup', ar: 'رجّع نسخة', go: () => Coach.guard(() => { Coach._focusData = true; Coach.view = 'settings'; Coach.render(); }, TKD.t('To restore a backup, type the coach PIN.', 'عشان ترجّع نسخة احتياطية، اكتب الرقم السري للمدرب.')) },
        { icon: '🔒', en: 'Privacy', ar: 'الخصوصية', go: () => { location.href = 'privacy.html'; } },
        { icon: '🗑️', en: 'Erase everything', ar: 'امسح كل حاجة', go: () => Coach.guard(() => hardResetGame(), TKD.t('To erase everything, type the coach PIN.', 'عشان تمسح كل حاجة، اكتب الرقم السري للمدرب.')), danger: true }
      ] }
  ],
  t(o) { return (typeof TKD !== 'undefined' && TKD.ar) ? o.ar : o.en; },
  mount() {
    if (document.getElementById('tabbar')) return;
    const bar = document.createElement('nav');
    bar.id = 'tabbar'; bar.className = 'tabbar';
    bar.setAttribute('aria-label', 'Main');
    document.body.appendChild(bar);
    const sheet = document.createElement('div');
    sheet.id = 'tab-sheet'; sheet.className = 'tab-sheet'; sheet.hidden = true;
    sheet.innerHTML = '<div class="tab-sheet-back" data-close></div><div class="tab-sheet-card" role="dialog" aria-modal="true"><div class="tab-sheet-grip" data-close></div><h3 id="tab-sheet-title"></h3><div class="tab-sheet-grid" id="tab-sheet-grid"></div></div>';
    document.body.appendChild(sheet);
    sheet.addEventListener('click', e => { if (e.target.closest('[data-close]')) this.close(); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !sheet.hidden) this.close(); });
    document.addEventListener('tkd:screen', () => { this.close(); this.render(); });
    // language switch → re-label
    new MutationObserver(() => this.render()).observe(document.documentElement, { attributes: true, attributeFilter: ['lang', 'dir'] });
    document.body.classList.add('has-tabbar');
    this.render();
  },
  current() {
    const id = (document.querySelector('.screen.active')?.id || '').replace(/-screen$/, '');
    return this.TABS.find(t => t.screens.includes(id))?.id || null;
  },
  render() {
    const bar = document.getElementById('tabbar'); if (!bar) return;
    const cur = this.current(), open = this.openId;
    // full-screen sessions keep the bar out of the way: the warm-up (own ✕) and the
    // arena games, whose KICK! button sits at the bottom of the canvas (v29).
    const act = document.querySelector('.screen.active');
    const immersive = !!act && (act.id === 'warmup-screen' || act.id === 'action-screen' || act.classList.contains('arena-screen'));
    document.body.classList.toggle('tab-hidden', immersive);
    bar.innerHTML = this.TABS.map(t => `<button type="button" class="tab ${t.id === cur ? 'on' : ''} ${t.id === open ? 'open' : ''}" data-tab="${t.id}" aria-haspopup="dialog" aria-expanded="${t.id === open}">
        <span class="tab-ico" aria-hidden="true">${t.icon}</span><span class="tab-lbl">${this.t(t)}</span></button>`).join('');
    bar.querySelectorAll('.tab').forEach(b => b.addEventListener('click', (e) => { this._kbd = e.detail === 0; this.toggle(b.dataset.tab); }));
  },
  toggle(id) { this.openId === id ? this.close() : this.open(id); },
  open(id) {
    const tab = this.TABS.find(t => t.id === id); if (!tab) return;
    this.openId = id;
    const sheet = document.getElementById('tab-sheet');
    document.getElementById('tab-sheet-title').textContent = `${tab.icon} ${this.t(tab)}`;
    const grid = document.getElementById('tab-sheet-grid');
    grid.innerHTML = tab.items.map((it, i) => `<button type="button" class="tab-tile ${it.hot ? 'hot' : ''} ${it.danger ? 'danger' : ''}" data-i="${i}">
      <span class="tab-tile-ico" aria-hidden="true">${it.icon}</span><span>${this.t(it)}</span></button>`).join('');
    grid.querySelectorAll('.tab-tile').forEach(b => b.addEventListener('click', () => {
      const it = tab.items[+b.dataset.i]; this.close();
      try { TKD.gs()?.playSound('click'); } catch (e) {}
      it.go();
    }));
    sheet.hidden = false;
    requestAnimationFrame(() => sheet.classList.add('show'));
    if (this._kbd) grid.querySelector('.tab-tile')?.focus({ preventScroll: true });   // focus ring only for keyboard users
    this.render();
  },
  close() {
    const sheet = document.getElementById('tab-sheet'); if (!sheet || sheet.hidden) { this.openId = null; return; }
    this.openId = null;
    sheet.classList.remove('show');
    setTimeout(() => { if (!this.openId) sheet.hidden = true; }, 180);
    this.render();
  }
};
window.TabBar = TabBar;
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => TabBar.mount()); else TabBar.mount();

// v28: on phones, long instructions fold to 2 lines with a "more" button
const DescFold = {
  // v55: the label is worked out every time it is shown, so it follows a language switch
  label(p) { return p.classList.contains('desc-fold') ? (TKD.ar ? 'اقرا الشرح كله ▾' : 'Read all ▾') : (TKD.ar ? 'أقل ▴' : 'Less ▴'); },
  relabel() {
    document.querySelectorAll('.desc-more').forEach(b => { const p = b.previousElementSibling; if (p) b.textContent = this.label(p); });
  },
  apply() {
    const small = window.matchMedia('(max-width: 600px)').matches;
    document.querySelectorAll('.screen.active .description').forEach(p => {
      const next = p.nextElementSibling?.classList?.contains('desc-more') ? p.nextElementSibling : null;
      if (getComputedStyle(p).display === 'none') { next?.remove(); return; }   // v55: a hidden text gets no "read all" button
      if (!small || p.dataset.open === '1') { p.classList.remove('desc-fold'); if (next && !small) next.remove(); return; }
      if ((p.textContent || '').trim().length < 90) { p.classList.remove('desc-fold'); next?.remove(); return; }
      p.classList.add('desc-fold');
      if (next) { next.textContent = this.label(p); return; }
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'desc-more';
      b.textContent = this.label(p);
      b.addEventListener('click', () => { p.classList.toggle('desc-fold'); p.dataset.open = p.classList.contains('desc-fold') ? '0' : '1'; b.textContent = this.label(p); });
      p.after(b);
    });
  }
};
document.addEventListener('tkd:screen', () => setTimeout(() => DescFold.apply(), 60));
document.addEventListener('tkd:lang', () => setTimeout(() => { DescFold.apply(); DescFold.relabel(); }, 60));

// =====================================================================
// v55 — ONE way of writing numbers per language. The Arabic screens mixed
// ١٢٣ and 123 ("سؤال 1/10" next to "السؤال ١ من ٣"); now every number a
// child sees in Arabic is written ٠١٢٣٤٥٦٧٨٩ (and 85% → ٨٥٪), and in English
// 0123456789 — whatever piece of code wrote it. Inputs, code and anything
// marked data-keep-digits are left alone.
// =====================================================================
const DigitLocalizer = {
  EAST: '٠١٢٣٤٥٦٧٨٩',
  SKIP: new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'INPUT', 'CODE', 'PRE', 'NOSCRIPT']),
  ar() { return document.documentElement.lang === 'ar'; },
  convert(t, ar = this.ar()) {
    // a keycap emoji (1️⃣ = 1 + U+FE0F + U+20E3) keeps its digit, or it breaks into empty boxes
    if (ar) return /\d|[٠-٩]\s?%/.test(t) ? t.replace(/\d(?![\uFE0F\u20E3])/g, d => this.EAST[d]).replace(/([٠-٩])\s?%/g, '$1٪') : t;
    return /[٠-٩٪]/.test(t) ? t.replace(/[٠-٩]/g, d => String(this.EAST.indexOf(d))).replace(/(\d)\s?٪/g, '$1%') : t;
  },
  skip(node) {
    const el = node.nodeType === 1 ? node : node.parentElement;
    if (!el) return true;
    if (this.SKIP.has(el.tagName)) return true;
    return !!el.closest('[data-keep-digits], [contenteditable="true"]');
  },
  fixText(node) {
    if (this.skip(node)) return;
    const t = node.nodeValue, n = this.convert(t);
    if (n !== t) node.nodeValue = n;
  },
  walk(root) {
    if (!root) return;
    if (root.nodeType === 3) { this.fixText(root); return; }
    if (root.nodeType !== 1 || this.skip(root)) return;
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let n; while ((n = w.nextNode())) this.fixText(n);
  },
  start() {
    if (this._mo || typeof MutationObserver === 'undefined') return;
    this.walk(document.body);
    this._mo = new MutationObserver(list => {
      for (const m of list) {
        if (m.type === 'characterData') this.fixText(m.target);
        else m.addedNodes.forEach(n => this.walk(n));
      }
    });
    this._mo.observe(document.body, { subtree: true, childList: true, characterData: true });
  }
};
document.addEventListener('tkd:lang', () => DigitLocalizer.walk(document.body));
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => DigitLocalizer.start()); else DigitLocalizer.start();
window.DigitLocalizer = DigitLocalizer;
window.addEventListener('resize', () => DescFold.apply());
window.DescFold = DescFold;

// #####################################################################
// ## audio/audio.js
// #####################################################################
// ============================================================================
// AUDIO (v28) — real sound effects, background music and recorded voice.
//   • SFX    rendered hit / whoosh / crack / chime samples (assets/audio/sfx),
//            with small random pitch changes so repeated hits never sound robotic.
//            Falls back to the old synthesized sounds if a file can't load.
//   • Music  two seamless loops: "dojo" (menus, lessons) and "arena" (games,
//            warm-up). Crossfades between screens, ducks under speech, has its
//            own 🎵 switch, and only starts after the first tap (browser rule).
//   • Voice  every time the game reads something aloud it first looks for a
//            recorded Egyptian voice line (assets/audio/voice/<lang>/…mp3, listed
//            in manifest.json); only if none exists it uses the phone's voice.
// ============================================================================
// v51 — opened straight from the folder (file://) the browser won't fetch() any file, so the
// samples and the music play through <audio> elements instead of Web Audio buffers
const FILE_MODE = typeof location !== 'undefined' && location.protocol === 'file:';
const AudioKit = {
  gs: () => (typeof GameStateInstance !== 'undefined' ? GameStateInstance : null),
  ctx() { const g = this.gs(); return g && g.audioContext; },
  buffers: {}, loading: {},
  async buffer(url) {
    const ctx = this.ctx(); if (!ctx) return null;
    if (this.buffers[url]) return this.buffers[url];
    if (!this.loading[url]) this.loading[url] = fetch(url).then(r => (r.ok ? r.arrayBuffer() : null))
      .then(b => (b ? new Promise((res) => ctx.decodeAudioData(b, res, () => res(null))) : null))
      .then(buf => (this.buffers[url] = buf)).catch(() => null);
    return this.loading[url];
  },
  SFX: ['whoosh-1', 'whoosh-2', 'whoosh-3', 'hit-1', 'hit-2', 'hit-3', 'hit-heavy', 'board-crack', 'bag-thud', 'ui-click', 'ui-pop', 'success', 'error', 'win', 'star', 'gong', 'tick', 'taiko', 'rim', 'clap'],
  preload() { if (this._pre || FILE_MODE) return; this._pre = true; this.SFX.forEach(n => this.buffer(`assets/audio/sfx/${n}.mp3`)); },
  // play a sample now; returns false if it isn't ready (caller then uses the old synth)
  sfx(name, { gain = 1, rate = 1, vary = 0.05 } = {}) {
    const g = this.gs(), ctx = this.ctx();
    if (!g || !g.soundEnabled || !ctx || !g.audioGain) return true;          // muted → "handled"
    if (FILE_MODE) return this.sfxEl(name, gain, rate * (1 + (Math.random() * 2 - 1) * vary), g);
    const pick = /-\d$/.test(name) || this.buffers[`assets/audio/sfx/${name}.mp3`] ? name
      : (['1', '2', '3'].map(k => `${name}-${k}`).filter(n => this.buffers[`assets/audio/sfx/${n}.mp3`])[Math.floor(Math.random() * 3)] || name);
    const buf = this.buffers[`assets/audio/sfx/${pick}.mp3`];
    if (!buf) { this.preload(); return false; }
    const src = ctx.createBufferSource(); src.buffer = buf;
    src.playbackRate.value = rate * (1 + (Math.random() * 2 - 1) * vary);
    const gn = ctx.createGain(); gn.gain.value = gain;
    src.connect(gn); gn.connect(g.audioGain); src.start();
    return true;
  },
  sfxEl(name, gain, rate, g) {
    const n = this.SFX.includes(name) ? name : ['1', '2', '3'].map(k => `${name}-${k}`).filter(x => this.SFX.includes(x))[Math.floor(Math.random() * 3)];
    if (!n) return false;
    try {
      const a = new Audio(`assets/audio/sfx/${n}.mp3`);
      a.volume = Math.max(0, Math.min(1, gain * (g.audioGain?.gain?.value ?? 0.3)));
      a.playbackRate = Math.max(0.5, Math.min(2, rate));
      a.play().catch(() => {});
      return true;
    } catch (e) { return false; }
  }
};

// ---------------------------------------------------------------- music
const Music = {
  KEY: 'taekwondoJourneyMusic',
  VOLUME: 0.32,
  ARENA: ['warmup', 'board-break', 'paddle-reflex', 'phase-rhythm', 'sparring-duel', 'balance-hold', 'heavy-bag', 'quiz-blast', 'action', 'versus'],
  enabled() { try { return localStorage.getItem(this.KEY) !== 'off'; } catch (e) { return true; } },
  setEnabled(on) { try { localStorage.setItem(this.KEY, on ? 'on' : 'off'); } catch (e) {} this.sync(); this.paintBtn(); },
  trackFor(screenId) { return this.ARENA.includes(screenId) ? 'arena' : 'dojo'; },
  master() {
    const ctx = AudioKit.ctx(); if (!ctx) return null;
    if (!this.out) { this.out = ctx.createGain(); this.out.gain.value = 0; this.out.connect(ctx.destination); }
    return this.out;
  },
  target() {
    const g = AudioKit.gs();
    if (!g || !g.soundEnabled || !this.enabled() || document.hidden || !this.unlocked) return 0;
    const video = document.querySelector('video:not([muted])');
    const playingVideo = video && !video.paused && !video.muted;
    return this.VOLUME * (this.ducked ? 0.3 : 1) * (playingVideo ? 0 : 1);
  },
  // file:// — one looping <audio> element instead of the Web Audio crossfade
  syncEl() {
    const want = this.trackFor((document.querySelector('.screen.active')?.id || 'home-screen').replace(/-screen$/, ''));
    const vol = this.target(), a = this.el2 || (this.el2 = Object.assign(new Audio(), { loop: true, preload: 'auto' }));
    if (!vol) { a.pause(); return; }
    if (this.current !== want) { a.src = `assets/audio/music/${want}.mp3`; this.current = want; }
    a.volume = Math.min(1, vol); a.play().catch(() => {});
  },
  async sync() {
    if (FILE_MODE) return this.syncEl();
    const ctx = AudioKit.ctx(), out = this.master(); if (!ctx || !out) return;
    const id = (document.querySelector('.screen.active')?.id || 'home-screen').replace(/-screen$/, '');
    const want = this.trackFor(id);
    out.gain.setTargetAtTime(this.target(), ctx.currentTime, 0.25);
    if (!this.target() || want === this.current) return;
    const buf = await AudioKit.buffer(`assets/audio/music/${want}.mp3`);
    if (!buf || want !== this.trackFor((document.querySelector('.screen.active')?.id || '').replace(/-screen$/, ''))) return;
    if (want === this.current) return;
    // crossfade: old voice fades out, new one fades in
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    const g = ctx.createGain(); g.gain.value = 0; src.connect(g); g.connect(out);
    src.start(); g.gain.setTargetAtTime(1, ctx.currentTime, 0.6);
    if (this.voice) { const old = this.voice; old.g.gain.setTargetAtTime(0, ctx.currentTime, 0.4); setTimeout(() => { try { old.src.stop(); } catch (e) {} }, 2500); }
    this.voice = { src, g }; this.current = want;
  },
  duck(on) { this.ducked = on; if (FILE_MODE) { if (this.el2) this.el2.volume = Math.min(1, this.target()); return; } const ctx = AudioKit.ctx(); if (ctx && this.out) this.out.gain.setTargetAtTime(this.target(), ctx.currentTime, 0.15); },
  paintBtn() {
    const b = document.getElementById('musicToggleBtn'); if (!b) return;
    const on = this.enabled();
    b.classList.toggle('muted', !on);
    b.setAttribute('aria-pressed', String(on));
    b.setAttribute('aria-label', on ? (TKD.ar ? 'اقفل المزيكا' : 'Music off') : (TKD.ar ? 'شغّل المزيكا' : 'Music on'));
    b.innerHTML = on ? '🎵' : '<span style="opacity:.55">🎵</span>';
  },
  mount() {
    const ctrls = document.querySelector('.header-controls');
    if (ctrls && !document.getElementById('musicToggleBtn')) {
      const b = document.createElement('button');
      b.type = 'button'; b.id = 'musicToggleBtn'; b.className = 'sound-toggle-btn music-toggle-btn';
      b.addEventListener('click', () => this.setEnabled(!this.enabled()));
      ctrls.insertBefore(b, ctrls.firstChild);
      this.paintBtn();
    }
    const unlock = () => { this.unlocked = true; AudioKit.preload(); this.sync(); };
    document.addEventListener('pointerdown', unlock, { once: true, capture: true });
    document.addEventListener('keydown', unlock, { once: true, capture: true });
    document.addEventListener('tkd:screen', () => this.sync());
    document.addEventListener('visibilitychange', () => this.sync());
    document.addEventListener('play', () => this.sync(), true);     // a lesson video started → music steps aside
    document.addEventListener('pause', () => this.sync(), true);
    document.addEventListener('click', (e) => { if (e.target.closest('#soundToggleBtn')) setTimeout(() => this.sync(), 50); }, true);
  }
};

// ---------------------------------------------------------------- voice
const Voice = {
  manifest: null,
  // same key for the same sentence, whatever emojis / punctuation / diacritics it carries
  norm(s) { return String(s || '').normalize('NFC').replace(/\p{M}/gu, '').replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x660)).replace(/[^\p{L}\p{N}]+/gu, ' ').trim().toLowerCase(); },   // v55: ٢٠ and 20 are the same line
  key(s) { const t = this.norm(s); let h = 2166136261; for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(36); },
  async load() {
    if (this.manifest) return this.manifest;
    // v55: opened from the folder, fetch() is refused → the same list ships as a script (manifest.js)
    if (FILE_MODE) return (this.manifest = await new Promise(res => {
      if (window.TKD_VOICE_MANIFEST) return res(window.TKD_VOICE_MANIFEST);
      const sc = document.createElement('script'); sc.src = 'assets/audio/voice/manifest.js';
      sc.onload = () => res(window.TKD_VOICE_MANIFEST || {}); sc.onerror = () => res({}); document.head.appendChild(sc);
    }));
    try { const r = await fetch('assets/audio/voice/manifest.json'); this.manifest = r.ok ? await r.json() : {}; } catch (e) { this.manifest = {}; }
    return this.manifest;
  },
  fileFor(text, lang) {
    const L = lang && lang.startsWith('ar') ? 'ar' : lang && lang.startsWith('ko') ? 'ko' : 'en';
    const f = this.manifest?.[L]?.[this.key(text)];
    return f ? `assets/audio/voice/${L}/${f}` : null;
  },
  stop() { this._run = (this._run || 0) + 1; if (this.el) { try { this.el.pause(); } catch (e) {} this.el = null; } Music.duck(false); },
  // v55 — a long text read in pieces: a screen = its title + each sentence of its instructions,
  // a quiz = the question + each answer. The recording checklist (lines.json) lists the SAME
  // pieces, built with this same function, so a coach records short lines once and every
  // screen that uses them speaks in the coach's voice
  parts(text) {
    return String(text || '').split(/(?<=[.!?؟…])\s+/u).map(s => s.trim()).filter(s => this.norm(s));
  },
  // plays the recording if there is one; returns true when it did
  play(text, lang, btn) {
    const url = this.fileFor(text, lang);
    if (!url) {
      // the whole text was never recorded as one line → are some of its pieces recorded?
      const parts = this.parts(text); if (parts.length < 2) return false;
      const urls = parts.map(p => this.fileFor(p, lang)); if (!urls.some(Boolean)) return false;
      this.chain(parts, urls, lang, btn); return true;
    }
    this.stop(); try { window.speechSynthesis?.cancel(); } catch (e) {}
    const a = new Audio(url); this.el = a;
    Music.duck(true); btn?.classList.add('speaking');
    const done = () => { btn?.classList.remove('speaking'); if (this.el === a) { this.el = null; Music.duck(false); } };
    a.addEventListener('ended', done); a.addEventListener('error', done);
    a.play().catch(done);
    return true;
  },
  // recorded pieces in the coach's voice, the pieces nobody recorded yet in the phone's voice, in order
  chain(parts, urls, lang, btn) {
    this.stop(); try { window.speechSynthesis?.cancel(); } catch (e) {}
    const run = this._run;
    Music.duck(true); btn?.classList.add('speaking');
    let i = 0;
    const finish = () => { if (this._run !== run) return; btn?.classList.remove('speaking'); this.el = null; Music.duck(false); };
    const next = () => {
      if (this._run !== run) return;
      if (i >= parts.length) return finish();
      const p = parts[i], u = urls[i]; i++;
      if (u) {
        const a = new Audio(u); this.el = a; let went = false;
        const go = () => { if (went) return; went = true; next(); };
        a.addEventListener('ended', go); a.addEventListener('error', go); a.play().catch(go);
      } else this.tts(p, lang, next);
    };
    next();
  },
  tts(text, lang, done) {
    let went = false; const go = () => { if (went) return; went = true; clearTimeout(t); done(); };
    const t = setTimeout(go, 1200 + String(text).length * 95);    // some phones never fire onend
    try {
      if (!('speechSynthesis' in window)) return go();
      const u = new SpeechSynthesisUtterance(text); u.lang = lang; u.rate = 0.9;
      if (lang.startsWith('ar')) {
        const vs = window.speechSynthesis.getVoices() || [];
        const v = vs.find(x => /^ar[-_]EG/i.test(x.lang)) || vs.find(x => /^ar\b/i.test(x.lang));
        if (v) { u.voice = v; u.lang = v.lang; }
      }
      u.onend = go; u.onerror = go;
      window.speechSynthesis.speak(u);
    } catch (e) { go(); }
  },
  // short praise / cue lines that exist ONLY as recordings (never robotic TTS)
  CUES: {
    bravo: { ar: 'برافو عليك!', en: 'Well done!' }, great: { ar: 'جامد جدًا!', en: 'Awesome!' }, again: { ar: 'قربت! جرّب تاني', en: 'So close — try again!' },
    record: { ar: 'رقم قياسي جديد!', en: 'New personal record!' }, levelup: { ar: 'طلعت مستوى جديد!', en: 'You levelled up!' },
    ready: { ar: 'استعد…', en: 'Get ready…' }, go: { ar: 'يلا!', en: 'Go!' }, kihap: { ar: 'كياي!', en: 'Kihap!' },
    welcome: { ar: 'أهلًا بيك يا بطل!', en: 'Welcome, champion!' }, warmupDone: { ar: 'برافو، خلّصت الإحماء!', en: 'Warm-up done — great job!' },
    // v43: the dojang commands (record them in Coach → Record voice)
    charyeot: { ar: 'تشاريوت!', en: 'Charyeot!' }, gyeongnye: { ar: 'كيونجنيه!', en: 'Gyeongnye!' },
    junbi: { ar: 'جونبي!', en: 'Junbi!' }, sijak: { ar: 'شيجاك!', en: 'Shijak!' }
  },
  cue(id) {
    const c = this.CUES[id]; if (!c || AudioKit.gs()?.soundEnabled === false) return;
    const ar = TKD.ar, t = ar ? c.ar : c.en, lang = ar ? 'ar-EG' : 'en-US';
    if (this.fileFor(t, lang)) this.play(t, lang);          // whole recordings only — a cue is never read by the phone voice
  },
  hook() {
    const orig = SpeechHelper.speak.bind(SpeechHelper);
    SpeechHelper.speak = (text, lang = 'en-US', btn = null) => {
      if (this.play(text, lang, btn)) return;
      // phone voice: duck the music while it talks
      try {
        Music.duck(true);
        clearTimeout(this._undo);
        this._undo = setTimeout(() => Music.duck(false), Math.min(9000, 700 + String(text).length * 75));
      } catch (e) {}
      orig(text, lang, btn);
    };
  }
};

// ---------------------------------------------------------------- wire into the existing sound calls
(function wire() {
  const GP = (typeof GameState !== 'undefined') && GameState.prototype;
  if (GP && GP.playSound) {
    const orig = GP.playSound;
    const MAP = { kick: ['whoosh', { gain: 0.9 }], strike: ['hit', { gain: 1 }], success: ['success', { gain: 0.8, vary: 0 }], error: ['error', { gain: 0.8, vary: 0 }],
                  win: ['win', { gain: 0.7, vary: 0 }], click: ['ui-click', { gain: 0.6, vary: 0.08 }] };
    GP.playSound = function (type, frequency) {
      const m = MAP[type];
      if (m && AudioKit.sfx(m[0], m[1])) return;
      return orig.call(this, type, frequency);
    };
  }
  if (typeof ArenaSound !== 'undefined') {
    const wrap = (name, sample, opts) => { const o = ArenaSound[name].bind(ArenaSound); ArenaSound[name] = (...a) => { if (!AudioKit.sfx(sample, opts)) o(...a); }; };
    wrap('smack', 'hit', { gain: 1 });
    wrap('thud', 'bag-thud', { gain: 1 });
    wrap('crack', 'board-crack', { gain: 1, vary: 0.03 });
    wrap('whoosh', 'whoosh', { gain: 0.8 });
    wrap('buzz', 'error', { gain: 0.6, vary: 0 });
    const drum = ArenaSound.drum.bind(ArenaSound);
    ArenaSound.drum = (kind) => {
      const s = { kick: 'taiko', snare: 'clap' }[kind];
      if (s && AudioKit.sfx(s, { gain: 0.7, vary: 0.02 })) return;
      drum(kind);
    };
  }
  Voice.hook(); Voice.load();
  const start = () => Music.mount();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
window.AudioKit = AudioKit; window.Music = Music; window.Voice = Voice;

// #####################################################################
// ## audio/voice-record.js
// #####################################################################
// ============================================================================
// VOICE RECORDER — lets the coach record the Egyptian voice-over lines right
// on the phone, no computer needed. Recordings are saved on THIS device only
// (IndexedDB — the app is fully offline, there is no server to upload to) and
// take priority over any shipped assets/audio/voice file with the same line,
// so a coach who records a sentence hears it immediately, everywhere the game
// would have played it.
// ============================================================================
const VoiceRecorder = {
  DB: 'tkdVoiceDB', STORE: 'clips', VERSION: 1,
  _db: null, _urls: new Map(), _lines: null,
  _rec: null, _stream: null, _chunks: [], _activeKey: null,

  db() {
    if (this._db) return Promise.resolve(this._db);
    if (typeof indexedDB === 'undefined') return Promise.reject(new Error('no indexedDB'));
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(this.DB, this.VERSION);
      req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains(this.STORE)) req.result.createObjectStore(this.STORE, { keyPath: 'key' }); };
      req.onsuccess = () => { this._db = req.result; resolve(this._db); };
      req.onerror = () => reject(req.error);
    });
  },
  // every line the game can read aloud, from the same data the recording
  // checklist (VOICE_SCRIPT.md) is generated from — always in sync with the game
  async lines() {
    if (this._lines) return this._lines;
    try { const r = await fetch('assets/audio/voice/lines.json'); this._lines = r.ok ? (await r.json()).lines || [] : []; }
    catch (e) { this._lines = []; }
    // v51: opened from the folder (file://) fetch() is refused — the same list ships as a script too
    if (!this._lines.length && FILE_MODE) this._lines = await new Promise(res => {
      if (window.TKD_VOICE_LINES) return res(window.TKD_VOICE_LINES);
      const sc = document.createElement('script'); sc.src = 'assets/audio/voice/lines.js';
      sc.onload = () => res(window.TKD_VOICE_LINES || []); sc.onerror = () => res([]); document.head.appendChild(sc);
    });
    return this._lines;
  },
  async put(key, blob) {
    const db = await this.db();
    await new Promise((res, rej) => {
      const tx = db.transaction(this.STORE, 'readwrite');
      tx.objectStore(this.STORE).put({ key, blob, ts: Date.now() });
      tx.oncomplete = res; tx.onerror = () => rej(tx.error);
    });
    const old = this._urls.get(key); if (old) URL.revokeObjectURL(old);
    this._urls.set(key, URL.createObjectURL(blob));
  },
  async remove(key) {
    const db = await this.db();
    await new Promise((res, rej) => {
      const tx = db.transaction(this.STORE, 'readwrite');
      tx.objectStore(this.STORE).delete(key);
      tx.oncomplete = res; tx.onerror = () => rej(tx.error);
    });
    const old = this._urls.get(key); if (old) { URL.revokeObjectURL(old); this._urls.delete(key); }
  },
  has(key) { return this._urls.has(key); },
  urlFor(key) { return this._urls.get(key) || null; },
  async loadAll() {
    try {
      const db = await this.db();
      const rows = await new Promise((res, rej) => {
        const tx = db.transaction(this.STORE, 'readonly');
        const req = tx.objectStore(this.STORE).getAll();
        req.onsuccess = () => res(req.result || []); req.onerror = () => rej(req.error);
      });
      rows.forEach(r => { if (r?.key && r.blob) this._urls.set(r.key, URL.createObjectURL(r.blob)); });
    } catch (e) { /* IndexedDB unavailable (private mode, old browser) — recording tool just won't offer playback of saved clips */ }
  },
  async count() { const all = await this.lines(); const total = all.length; let recorded = 0; all.forEach(l => { if (this.has(l.key)) recorded++; }); return { recorded, total }; },

  // ---------- recording (MediaRecorder over getUserMedia)
  supported() { return !!(navigator.mediaDevices?.getUserMedia && window.MediaRecorder); },
  async start(key) {
    if (this._rec) await this.stop(false);
    this._stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    this._chunks = []; this._activeKey = key;
    const mime = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4'].find(m => window.MediaRecorder.isTypeSupported?.(m));
    this._rec = new MediaRecorder(this._stream, mime ? { mimeType: mime } : undefined);
    this._rec.addEventListener('dataavailable', e => { if (e.data && e.data.size) this._chunks.push(e.data); });
    this._rec.start();
  },
  // stop(save=true) stops the mic and, by default, saves the clip under the key recording started with
  async stop(save = true) {
    if (!this._rec) return null;
    const rec = this._rec, key = this._activeKey;
    const blob = await new Promise(resolve => {
      rec.addEventListener('stop', () => resolve(new Blob(this._chunks, { type: rec.mimeType || 'audio/webm' })), { once: true });
      try { rec.stop(); } catch (e) { resolve(new Blob(this._chunks)); }
    });
    this._stream?.getTracks().forEach(t => { try { t.stop(); } catch (e) {} });
    this._stream = null; this._rec = null; this._activeKey = null; this._chunks = [];
    if (save && key && blob.size) await this.put(key, blob);
    return { key, blob };
  },
  cancel() { return this.stop(false); },
  recording() { return this._activeKey; },

  // v55 — every clip recorded on this device, packed as voice/manifest.json + voice/ar/<file>,
  // in a plain (stored) .zip, ready to unzip into assets/audio/ so they ship with the game
  async exportPack() {
    const lines = await this.lines(); const rows = [];
    try {
      const db = await this.db();
      rows.push(...await new Promise((res, rej) => { const tx = db.transaction(this.STORE, 'readonly'); const rq = tx.objectStore(this.STORE).getAll(); rq.onsuccess = () => res(rq.result || []); rq.onerror = () => rej(rq.error); }));
    } catch (e) { return 0; }
    if (!rows.length) return 0;
    const byKey = new Map(lines.map(l => [l.key, l]));
    const manifest = { ar: {}, en: {}, ko: {} }, files = [];
    for (const r of rows) {
      const l = byKey.get(r.key); if (!l || !r.blob) continue;
      const ext = /mp4|m4a|aac/.test(r.blob.type) ? 'm4a' : /ogg/.test(r.blob.type) ? 'ogg' : 'webm';
      const name = String(l.file || `${r.key}.mp3`).replace(/\.mp3$/, `.${ext}`);
      manifest.ar[r.key] = name;
      files.push({ path: `voice/ar/${name}`, data: new Uint8Array(await r.blob.arrayBuffer()) });
    }
    files.unshift({ path: 'voice/manifest.json', data: new TextEncoder().encode(JSON.stringify(manifest, null, 1)) },
                  // the same list for a game opened straight from the folder (file://)
                  { path: 'voice/manifest.js', data: new TextEncoder().encode(`// recorded voice lines (copy of manifest.json for file://)\nwindow.TKD_VOICE_MANIFEST = ${JSON.stringify(manifest)};\n`) });
    const blob = this.zip(files);
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `taekwondo-journey-voice-${TKD.dayKey()}.zip`;
    document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
    return files.length - 2;
  },
  // a tiny "store" (no compression) zip writer — audio is already compressed
  zip(files) {
    const T = this._crcT || (this._crcT = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })());
    const crc = (d) => { let c = 0xFFFFFFFF; for (let i = 0; i < d.length; i++) c = T[(c ^ d[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
    const enc = new TextEncoder(), parts = [], central = []; let off = 0;
    const u16 = (v) => [v & 255, (v >>> 8) & 255], u32 = (v) => [v & 255, (v >>> 8) & 255, (v >>> 16) & 255, (v >>> 24) & 255];
    for (const f of files) {
      const name = enc.encode(f.path), c = crc(f.data), n = f.data.length;
      const head = new Uint8Array([...u32(0x04034b50), ...u16(20), ...u16(0x0800), ...u16(0), ...u16(0), ...u16(0x21), ...u32(c), ...u32(n), ...u32(n), ...u16(name.length), ...u16(0)]);
      parts.push(head, name, f.data);
      central.push(new Uint8Array([...u32(0x02014b50), ...u16(20), ...u16(20), ...u16(0x0800), ...u16(0), ...u16(0), ...u16(0x21), ...u32(c), ...u32(n), ...u32(n), ...u16(name.length), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(0), ...u32(off)]), name);
      off += head.length + name.length + n;
    }
    const cdSize = central.reduce((a, b) => a + b.length, 0);
    const end = new Uint8Array([...u32(0x06054b50), ...u16(0), ...u16(0), ...u16(files.length), ...u16(files.length), ...u32(cdSize), ...u32(off), ...u16(0)]);
    return new Blob([...parts, ...central, end], { type: 'application/zip' });
  }
};

// give every recorded clip priority over the shipped manifest file for that
// exact sentence — Voice.play()/fileFor() ask VoiceRecorder first
(function hookVoice() {
  const wire = () => {
    if (typeof Voice === 'undefined') return;
    const origFileFor = Voice.fileFor.bind(Voice);
    Voice.fileFor = function (text, lang) {
      const k = this.key(text);
      const rec = window.VoiceRecorder?.urlFor?.(k);
      return rec || origFileFor(text, lang);
    };
  };
  if (typeof Voice !== 'undefined') wire(); else document.addEventListener('DOMContentLoaded', wire);
  VoiceRecorder.loadAll();
})();

window.VoiceRecorder = VoiceRecorder;

// #####################################################################
// ## ui/read-aloud.js
// #####################################################################
// ============================================================================
// READ-ALOUD (v31) — for the 6-year-olds who can't read well yet.
//   • a big 🔊 on every screen reads its title + instructions
//   • a 🔊 on every game card reads the game's name + what to do
//   • the quiz 🔊 reads the question AND the four answers
//   • 🗣️ in the header = "read to me by myself": each screen, each quiz
//     question and the map's next step are read out as soon as they appear
// Speech goes through TKD.speak → the recorded Egyptian voice when there is one,
// otherwise the phone's voice. Muted sound = silent (with a hint).
// ============================================================================
const ReadAloud = {
  key() { return `taekwondoJourneyReadAloud:${TKD.pid() || 'guest'}`; },
  auto() { return !!TKD.read(this.key(), false); },
  setAuto(on) { TKD.write(this.key(), !!on); this.paintBtn(); if (on) this.say(TKD.t('I will read everything to you!', 'هقرالك كل حاجة!')); },
  clean(s) { return String(s || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '').replace(/[\u{FE0F}\u{200D}\u{200B}\u{20E3}]/gu, '').replace(/\(\s*\)/g, '').replace(/\s+/g, ' ').trim(); },
  say(text, btn = null) {
    const t = this.clean(text); if (!t) return;
    if (TKD.gs()?.soundEnabled === false) { TKD.toast(TKD.t('Sound is off — turn it on with 🔊 at the top', 'الصوت مقفول — شغّله من 🔊 اللي فوق'), 'info'); return; }
    btn?.classList.add('speaking');
    SpeechHelper.speak(t, TKD.ar ? 'ar-EG' : 'en-US', btn);
    if (btn) setTimeout(() => btn.classList.remove('speaking'), Math.min(9000, 900 + t.length * 70));
  },
  // title + the screen's instructions
  screenText(screen) {
    const h = screen.querySelector('h2');
    const d = screen.querySelector('.description, .desc-fold .desc-full, .desc-fold');
    return [h?.textContent, d?.textContent].filter(Boolean).map(x => this.clean(x).replace(/اقرا الشرح كله|Read all/g, '')).join('. ');
  },
  mountScreen(screen) {
    if (!screen || screen.id === 'home-screen' || screen.id === 'warmup-screen') return;
    const box = screen.querySelector('.game-container') || screen;
    if (box.querySelector(':scope > .say-fab')) return;
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'say-fab';
    b.setAttribute('aria-label', TKD.t('Read it to me', 'اقرالي'));
    b.innerHTML = '<span aria-hidden="true">🔊</span>';
    b.addEventListener('click', (e) => { e.stopPropagation(); this.say(this.screenText(screen), b); });
    box.prepend(b);
  },
  mountCards() {
    document.querySelectorAll('.game-card').forEach(card => {
      if (card.querySelector('.say-mini')) return;
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'say-mini';
      b.setAttribute('aria-label', TKD.t('What is this game?', 'اللعبة دي إيه؟'));
      b.innerHTML = '<span aria-hidden="true">🔊</span>';
      b.addEventListener('click', (e) => { e.stopPropagation(); e.preventDefault(); this.say(`${card.querySelector('h3')?.textContent || ''}. ${card.querySelector('p')?.textContent || ''}`, b); });
      card.appendChild(b);
    });
  },
  quizText() {
    const q = document.getElementById('question-text')?.textContent || '';
    const nums = TKD.ar ? ['واحد', 'اتنين', 'تلاتة', 'أربعة'] : ['one', 'two', 'three', 'four'];
    // v55: "question. one. answer. two. answer…" — each piece on its own, so recorded pieces can be played (Voice.parts)
    const opts = [...document.querySelectorAll('.quiz-option')].map((o, i) => `${nums[i] || ''}. ${(o.querySelector('.option-text')?.textContent || '').trim().replace(/[.!؟?]*$/, '')}`);
    return `${q.trim().replace(/[.:]*$/, '')}. ${opts.join('. ')}.`;
  },
  // the header switch
  mountBtn() {
    const ctrls = document.querySelector('.header-controls');
    if (!ctrls || document.getElementById('readAloudBtn')) return;
    const b = document.createElement('button');
    b.type = 'button'; b.id = 'readAloudBtn'; b.className = 'sound-toggle-btn read-toggle-btn';
    b.addEventListener('click', () => this.setAuto(!this.auto()));
    ctrls.insertBefore(b, ctrls.firstChild);
    this.paintBtn();
  },
  paintBtn() {
    const b = document.getElementById('readAloudBtn'); if (!b) return;
    const on = this.auto();
    b.classList.toggle('muted', !on);
    b.setAttribute('aria-pressed', String(on));
    b.setAttribute('aria-label', on ? TKD.t('Stop reading to me', 'بطّل تقرالي') : TKD.t('Read everything to me', 'اقرالي كل حاجة'));
    b.innerHTML = on ? '🗣️' : '<span style="opacity:.5">🗣️</span>';
  },
  init() {
    this.mountBtn();
    document.addEventListener('tkd:screen', (e) => {
      const id = e.detail?.screenId, scr = document.getElementById(`${id}-screen`);
      this.mountScreen(scr);
      if (id === 'games') this.mountCards();
      if (!this.auto() || !scr) return;
      clearTimeout(this._t);
      this._t = setTimeout(() => {
        if (!scr.classList.contains('active')) return;
        // quiz is handled entirely by the #question-text MutationObserver below
        // (it fires on the first question too) — reading it here as well would
        // speak the same question twice.
        if (id === 'home') { const n = window.Journey?.next?.(); if (n) this.say(TKD.t(`Next: ${n.label}`, `الخطوة الجاية: ${n.label}`)); }
        else if (id !== 'quiz' && id !== 'warmup') this.say(this.screenText(scr));
      }, 700);
    });
    document.addEventListener('tkd:player-changed', () => this.paintBtn());
    // the quiz: its 🔊 reads the answers too, and each new question is read in auto mode
    const qBtn = document.querySelector('.quiz-question .speak-btn');
    if (qBtn) { qBtn.removeAttribute('onclick'); qBtn.addEventListener('click', (e) => { e.stopPropagation(); this.say(this.quizText(), qBtn); }); }
    const qt = document.getElementById('question-text');
    if (qt) new MutationObserver(() => {
      if (this.auto() && document.getElementById('quiz-screen')?.classList.contains('active')) { clearTimeout(this._q); this._q = setTimeout(() => this.say(this.quizText()), 400); }
    }).observe(qt, { childList: true, characterData: true, subtree: true });
  }
};
window.ReadAloud = ReadAloud;
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => ReadAloud.init()); else ReadAloud.init();

// #####################################################################
// ## ui/shop.js
// #####################################################################
// ============================================================================
// STAR SHOP (v31) — stars earned across every kick buy cosmetics for the
// fighter: coloured belts (matching real taekwondo ranks) and headbands.
// Purely cosmetic — never touches real skill/belt progress. Shows up on the
// map, the winner screen, in the arena games and in lessons, wherever the
// skeletal rig is drawn (RigFighter/RigOpponent/RigSprite/RigView).
// ============================================================================
const Shop = {
  BELTS: [
    { id: 'belt-white', slot: 'belt', color: '#f4f1e8', cost: 0, en: 'White', ar: 'أبيض' },
    { id: 'belt-yellow', slot: 'belt', color: '#ffd93d', cost: 15, en: 'Yellow', ar: 'أصفر' },
    { id: 'belt-green', slot: 'belt', color: '#2a9d8f', cost: 25, en: 'Green', ar: 'أخضر' },
    { id: 'belt-blue', slot: 'belt', color: '#3d7dff', cost: 35, en: 'Blue', ar: 'أزرق' },
    { id: 'belt-red', slot: 'belt', color: '#e63946', cost: 45, en: 'Red', ar: 'أحمر' },
    { id: 'belt-black', slot: 'belt', color: '#1d2b36', cost: 60, en: 'Black', ar: 'أسود' }
  ],
  // v55: belts are NOT sold any more — in Taekwondo a belt is earned. The BELTS list
  // above stays only so stars spent on one in an older version can be given back.
  HEADBANDS: [
    { id: 'hb-none', slot: 'headband', color: null, cost: 0, en: 'None', ar: 'بدون' },
    { id: 'hb-red', slot: 'headband', color: '#e63946', cost: 8, en: 'Red headband', ar: 'عصابة حمرا' },
    { id: 'hb-blue', slot: 'headband', color: '#3d7dff', cost: 8, en: 'Blue headband', ar: 'عصابة زرقا' },
    { id: 'hb-green', slot: 'headband', color: '#2a9d8f', cost: 10, en: 'Green headband', ar: 'عصابة خضرا' },
    { id: 'hb-purple', slot: 'headband', color: '#8e5cd9', cost: 12, en: 'Purple headband', ar: 'عصابة بنفسجي' },
    { id: 'hb-pink', slot: 'headband', color: '#ff7fa6', cost: 12, en: 'Pink headband', ar: 'عصابة بمبي' },
    { id: 'hb-black', slot: 'headband', color: '#1d2b36', cost: 15, en: 'Black headband', ar: 'عصابة سودا' },
    { id: 'hb-gold', slot: 'headband', color: '#ffd166', cost: 20, en: 'Gold headband', ar: 'عصابة دهبي' }
  ],
  // the little things that fly around your fighter when you win
  PARTIES: [
    { id: 'party-classic', slot: 'party', icons: ['🎉', '✨', '⭐'], cost: 0, en: 'Classic', ar: 'العادي' },
    { id: 'party-stars', slot: 'party', icons: ['🌟', '💫', '⭐'], cost: 10, en: 'Shooting stars', ar: 'نجوم لامعة' },
    { id: 'party-fire', slot: 'party', icons: ['🔥', '💥', '⚡'], cost: 15, en: 'Fire power', ar: 'نار وطاقة' },
    { id: 'party-flowers', slot: 'party', icons: ['🌸', '🌼', '🌷'], cost: 15, en: 'Flowers', ar: 'ورد' },
    { id: 'party-champion', slot: 'party', icons: ['🐉', '🏆', '🥇'], cost: 25, en: 'Champion', ar: 'البطل' }
  ],
  // the ring around your picture on the map, the league and the player cards
  FRAMES: [
    { id: 'frame-none', slot: 'frame', color: null, cost: 0, en: 'None', ar: 'بدون' },
    { id: 'frame-gold', slot: 'frame', color: '#ffd166', cost: 10, en: 'Gold frame', ar: 'إطار دهبي' },
    { id: 'frame-teal', slot: 'frame', color: '#2a9d8f', cost: 10, en: 'Teal frame', ar: 'إطار فيروزي' },
    { id: 'frame-red', slot: 'frame', color: '#e63946', cost: 10, en: 'Red frame', ar: 'إطار أحمر' },
    { id: 'frame-rainbow', slot: 'frame', color: 'rainbow', cost: 25, en: 'Rainbow frame', ar: 'إطار قوس قزح' }
  ],
  items() { return [...this.BELTS, ...this.HEADBANDS, ...this.PARTIES, ...this.FRAMES]; },
  forSale() { return [...this.HEADBANDS, ...this.PARTIES, ...this.FRAMES]; },
  find(id) { return this.items().find(x => x.id === id); },

  key() { return `taekwondoJourneyShop:${TKD.pid() || 'guest'}`; },
  data(pid) {
    const key = pid ? `taekwondoJourneyShop:${pid}` : this.key();
    const d = TKD.read(key, null);
    if (!(d && d.owned && d.equipped)) return { owned: ['belt-white', 'hb-none', 'party-classic', 'frame-none'], equipped: { belt: 'belt-white', headband: 'hb-none', party: 'party-classic', frame: 'frame-none' }, spent: 0 };
    // v55: give back the stars of any belt bought in an older version (once)
    const bought = d.owned.filter(id => id.startsWith('belt-') && id !== 'belt-white');
    if (bought.length && !pid) {
      const back = bought.reduce((n, id) => n + (this.BELTS.find(b => b.id === id)?.cost || 0), 0);
      d.owned = d.owned.filter(id => !bought.includes(id));
      d.spent = Math.max(0, (d.spent || 0) - back);
      d.equipped.belt = 'belt-white';
      TKD.write(key, d);
      setTimeout(() => TKD.toast(TKD.t(`⭐ ${back} stars are back in your pocket — in Taekwondo a belt is earned by training, not bought!`, `⭐ رجّعنالك ${back} نجمة — في التايكوندو الحزام بيتكسب بالتمرين، مش بيتشترى!`), 'info'), 900);
    }
    d.equipped.party = d.equipped.party || 'party-classic';
    d.equipped.frame = d.equipped.frame || 'frame-none';
    ['party-classic', 'frame-none'].forEach(id => { if (!d.owned.includes(id)) d.owned.push(id); });
    return d;
  },
  // the celebration icons and the avatar frame of any player (for the league, the player cards…)
  party(pid) { const d = this.data(pid); return (this.find(d.equipped.party) || this.PARTIES[0]).icons; },
  frame(pid) { const d = this.data(pid); return (this.find(d.equipped.frame) || this.FRAMES[0]).color; },
  save(d) { TKD.write(this.key(), d); },

  // stars earned across every kick, whether that kick is unlocked yet or
  // not, plus any daily-mission gifts the child has claimed
  earned() {
    let n = 0;
    (GameConfig.SKILL_ORDER || []).forEach(id => {
      try { n += window.Journey.starTotal(window.Journey.steps(id)); } catch (e) { /* not ready yet */ }
    });
    try { n += window.Mission?.bonusStars() || 0; } catch (e) { /* not ready yet */ }
    return n;
  },
  balance() { return Math.max(0, this.earned() - this.data().spent); },
  owns(id) { return this.data().owned.includes(id); },
  equipped(slot) { return this.data().equipped[slot]; },

  buy(id) {
    const item = this.find(id); if (!item) return false;
    const d = this.data();
    if (!d.owned.includes(id)) {
      if (this.balance() < item.cost) return false;
      d.owned.push(id); d.spent += item.cost;
    }
    d.equipped[item.slot] = id;
    this.save(d);
    return true;
  },
  // a free item (the treasure chest): owned and put on at once; returns the item, or null if already owned
  grant(id) {
    const item = this.find(id); if (!item || item.slot === 'belt') return null;
    const d = this.data(); if (d.owned.includes(id)) return null;
    d.owned.push(id); d.equipped[item.slot] = id; this.save(d); this._cos = null;
    return item;
  },
  equip(id) {
    const item = this.find(id); if (!item || !this.owns(id)) return false;
    const d = this.data(); d.equipped[item.slot] = id; this.save(d); this._cos = null;
    return true;
  },
  cosmetics() {
    const now = Date.now();                        // called on every 3D frame → cached briefly
    if (this._cos && now - this._cosT < 1500 && this._cosP === TKD.pid()) return this._cos;
    const d = this.data();
    const hb = this.find(d.equipped.headband) || this.HEADBANDS[0];
    // the character always wears the belt the child has EARNED in the syllabus
    const earned = this.earnedBelt();
    this._cos = { belt: earned?.color || this.BELTS[0].color, headband: hb.color, earned: earned?.id || null };
    this._cosT = now; this._cosP = TKD.pid();
    // first time a new belt shows up on the character → tell the child
    const k = `taekwondoJourneyBelt3D:${TKD.pid() || 'guest'}`, seen = TKD.read(k, null);
    if (earned && seen !== earned.id) {
      TKD.write(k, earned.id);
      if (seen !== null) setTimeout(() => TKD.toast(TKD.t(`🥋 Your character now wears the ${earned.name.en}!`, `🥋 شخصيتك لابسة دلوقتي ${earned.name.ar}!`), 'success'), 600);
    } else if (!earned && seen === null) TKD.write(k, '');
    return this._cos;
  },
  earnedBelt() {
    try {
      if (!window.Curriculum || !window.CurriculumScreen) return null;
      const d = CurriculumScreen.done(); let got = null;
      for (const b of Curriculum.BELTS) { if (b.items.every(i => CurriculumScreen.isDone(i, d))) got = b; else break; }
      return got;
    } catch (e) { return null; }
  },

  // ---------------------------------------------------------------- drawing
  // Anchors a coloured band to a point in a bone's own local space (found by
  // eye against every kick + the idle map sprite) — the same point→screen
  // mapping the rig engine uses for real atlas pieces, so it moves, rotates
  // and scales with the fighter through every kick.
  _frame(sk, ctx, x, y, scale, flip, boneName, lx, ly) {
    const i = sk.data.boneIndex[boneName]; if (i === undefined) return null;
    const w = i * 6, W = sk.world;
    const fx = flip ? -scale : scale;
    const p = sk.point(boneName, lx, ly);
    const ang = Math.atan2(-W[w + 2], (flip ? -1 : 1) * W[w]);
    return { x: x + fx * p.x, y: y - scale * p.y, ang };
  },
  drawCosmetics(sk, ctx, x, y, scale, flip = false, alpha = 1) {
    if (!sk || !sk.data || alpha <= 0 || sk.is3D) return;   // 3D characters colour their own belt / headband
    const cos = this.cosmetics();
    if (!cos.belt && !cos.headband) return;
    const H = sk.data.extra?.height || 1000, s = Math.abs(scale);
    ctx.save(); ctx.globalAlpha *= alpha;
    const round = (c, rx, ry, rw, rh, r) => { c.beginPath(); c.roundRect ? c.roundRect(rx, ry, rw, rh, r) : c.rect(rx, ry, rw, rh); c.fill(); };
    if (cos.belt) {
      // 'body' bone's own origin sits near the collar; the waist is a fixed
      // stretch further down its local x-axis. In the band's own frame +x runs
      // up the torso and +y across it, so the wrap is thin in x, wide in y,
      // and the knot's tails hang back down -x.
      const fr = this._frame(sk, ctx, x, y, scale, flip, 'body', H * 0.036, 0);
      if (fr) {
        const t = H * 0.038 * s, w = H * 0.155 * s, front = (flip ? -1 : 1) * w * 0.32;
        ctx.save(); ctx.translate(fr.x, fr.y); ctx.rotate(fr.ang);
        ctx.fillStyle = cos.belt;
        round(ctx, -t / 2, -w * 0.56, t, w, t * 0.34);                     // the wrap around the waist
        // two thin tails hanging down (-x) from the knot at the front
        const tw = t * 0.5, tl = H * 0.085 * s;
        [-0.8, 0.8].forEach((off, i) => {
          ctx.save();
          ctx.translate(-t * 0.2, front + off * tw);
          ctx.rotate((i ? -1 : 1) * 0.13);
          round(ctx, -tl, -tw / 2, tl, tw, tw * 0.45);
          ctx.restore();
        });
        round(ctx, -t * 0.62, front - t * 0.62, t * 1.24, t * 1.24, t * 0.3); // the knot itself
        ctx.fillStyle = 'rgba(0,0,0,.18)';                                 // a crease so it reads as cloth
        ctx.fillRect(-t / 2, -w / 2, t * 0.26, w);
        ctx.restore();
      }
    }
    if (cos.headband) {
      // 'head' bone's origin is at the neck; a short way along it lands on
      // the forehead, just above the eyes.
      const fr = this._frame(sk, ctx, x, y, scale, flip, 'head', 120, 0);
      if (fr) {
        const hL = sk.data.bones[sk.data.boneIndex.head]?.length || 160;
        const t = hL * 0.17 * s, w = hL * 0.72 * s, back = (flip ? 1 : -1) * w * 0.5;
        ctx.save(); ctx.translate(fr.x, fr.y); ctx.rotate(fr.ang);
        ctx.fillStyle = cos.headband;
        round(ctx, -t / 2, -w / 2, t, w, t * 0.45);                        // the band across the brow
        // its knot streams backwards off the back of the head (-y), angled down
        const tw = t * 0.36, tl = hL * 0.2 * s, dir = flip ? 1 : -1;
        [-0.7, 0.7].forEach((off, i) => {
          ctx.save();
          ctx.translate(-t * 0.12 + off * tw, back);
          ctx.rotate((i ? -1 : 1) * 0.22 * dir);
          round(ctx, -tw / 2, dir < 0 ? -tl : 0, tw, tl, tw * 0.5);
          ctx.restore();
        });
        ctx.fillStyle = 'rgba(0,0,0,.14)';
        ctx.fillRect(-t / 2, -w / 2, t * 0.25, w);
        ctx.restore();
      }
    }
    ctx.restore();
  },

  // v47: the phase pictures are rendered from the 3D character WEARING the
  // equipped belt / headband (PoseShots bakes them in), so nothing is painted
  // over the picture any more — this only clears a layer an older build left.
  async drawOnPhoto(host) {
    host?.querySelector('.cos-photo')?.remove();
    return false;
  },

  // ---------------------------------------------------------------- UI
  cardHTML(item) {
    const owned = this.owns(item.id), on = this.equipped(item.slot) === item.id;
    const label = TKD.t(item.en, item.ar);
    const swatch = item.icons ? `<span class="shop-swatch shop-swatch-party">${item.icons.join('')}</span>`
      : item.slot === 'frame' && item.color ? `<span class="shop-swatch shop-swatch-frame ${item.color === 'rainbow' ? 'rainbow' : ''}" style="--c:${item.color}"></span>`
      : item.color ? `<span class="shop-swatch" style="--c:${item.color}"></span>` : `<span class="shop-swatch shop-swatch-none">✕</span>`;
    return `<button type="button" class="shop-card ${on ? 'is-on' : ''}" data-buy="${item.id}">
      ${swatch}
      <b>${TKD.esc(label)}</b>
      ${on ? `<small class="shop-tag shop-tag-on">${TKD.t('Wearing', 'شغّال دلوقتي')}</small>`
        : owned ? `<small class="shop-tag">${TKD.t('Owned — tap to wear', 'عندك — دوس تلبسه')}</small>`
        : `<small class="shop-tag shop-tag-cost">⭐ ${TKD.num(item.cost)}</small>`}
    </button>`;
  },
  html() {
    const bal = this.balance();
    return `<div class="shop-modal" id="shop-modal">
      <div class="shop-card-sheet">
        <button type="button" class="shop-close" aria-label="${TKD.t('Close', 'قفل')}">✕</button>
        <h2>🛍️ ${TKD.t('Star Shop', 'متجر النجوم')}</h2>
        <p class="shop-balance">⭐ <b>${TKD.num(bal)}</b> ${TKD.t('stars to spend', 'نجمة معاك')}</p>
        <p class="shop-belt-note">🥋 ${TKD.t('Belts are not sold: your fighter wears the belt you EARN by mastering its techniques in the Belt Syllabus.', 'الحزام مش بيتشترى: شخصيتك بتلبس الحزام اللي بتكسبه لما تتقن حركاته في منهج الأحزمة.')}</p>
        <h3>${TKD.t('Headband', 'عصابة الراس')}</h3>
        <div class="shop-grid">${this.HEADBANDS.map(i => this.cardHTML(i)).join('')}</div>
        <h3>${TKD.t('Win celebration', 'احتفال الفوز')}</h3>
        <div class="shop-grid">${this.PARTIES.map(i => this.cardHTML(i)).join('')}</div>
        <h3>${TKD.t('Picture frame', 'إطار الصورة')}</h3>
        <div class="shop-grid">${this.FRAMES.map(i => this.cardHTML(i)).join('')}</div>
      </div>
    </div>`;
  },
  open() {
    document.getElementById('shop-modal')?.remove();
    document.body.insertAdjacentHTML('beforeend', this.html());
    this.bind();
    AudioKit?.sfx?.('ui-pop', { gain: 0.4 });
  },
  refresh() {
    const m = document.getElementById('shop-modal'); if (!m) return;
    m.outerHTML = this.html();
    this.bind();
  },
  bind() {
    const m = document.getElementById('shop-modal'); if (!m) return;
    m.addEventListener('click', (e) => {
      if (e.target === m || e.target.closest('.shop-close')) { m.remove(); return; }
      const btn = e.target.closest('[data-buy]'); if (!btn) return;
      const id = btn.dataset.buy, item = this.find(id);
      if (!item) return;
      if (this.owns(id)) { this.equip(id); AudioKit?.sfx?.('click', { gain: 0.4 }); }
      else if (this.balance() >= item.cost) {
        this.buy(id);
        AudioKit?.sfx?.('star', { gain: 0.5 });
        TKD.toast(TKD.t(`Bought the ${TKD.t(item.en, item.ar)}!`, `اشتريت ${item.ar}!`), 'success');
      } else {
        TKD.toast(TKD.t('Not enough stars yet — play more kicks!', 'مش معاك نجوم كفاية — كمّل لعب!'), 'info');
        return;
      }
      this.refresh();
    });
  },
  mountEntryPoints() {
    // the map's star badge — cheap to re-mark every time (the map redraws
    // its own DOM after every game, not just on a screen change); the click
    // itself is handled by a delegated listener below so it never goes stale
    const stars = document.querySelector('.jr-stars');
    if (stars && !stars.hasAttribute('role')) { stars.setAttribute('role', 'button'); stars.setAttribute('tabindex', '0'); }
    // the trophy room — where a kid already comes to see what they earned
    const tr = document.querySelector('#trophy-room-screen .game-container');
    if (tr && !tr.querySelector('.shop-open-btn')) {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'shop-open-btn';
      b.innerHTML = `🛍️ ${TKD.t('Star Shop', 'متجر النجوم')}`;
      b.addEventListener('click', () => this.open());
      tr.insertBefore(b, tr.querySelector('.trophy-room-counter') || tr.firstChild.nextSibling);
    }
  },
  init() {
    document.addEventListener('tkd:screen', (e) => {
      const id = e.detail?.screenId;
      if (id === 'trophy-room' || id === 'home') setTimeout(() => this.mountEntryPoints(), 60);
    });
    document.addEventListener('click', (e) => {
      if (e.target.closest('.jr-stars')) this.open();
    });
    document.addEventListener('keydown', (e) => {
      if ((e.key === 'Enter' || e.key === ' ') && e.target.closest('.jr-stars')) { e.preventDefault(); this.open(); }
    });
  }
};
window.Shop = Shop;
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => Shop.init()); else Shop.init();

// #####################################################################
// ## ui/mission.js
// #####################################################################
// ============================================================================
// DAILY MISSION (v31) — a small box on the map: "play 2 things today, get a
// gift". Riding on the existing attempts log and practice streak, not a new
// tracking system. The reward is bonus stars, spendable in the Star Shop.
// ============================================================================
const Mission = {
  TARGET: 2,
  REWARD: 5,

  key() { return `taekwondoJourneyMission:${TKD.pid() || 'guest'}`; },
  data() {
    const d = TKD.read(this.key(), null);
    const today = TKD.dayKey();
    if (d && d.day === today) return d;
    return { day: today, claimed: false, bonusStars: d?.bonusStars || 0 };
  },
  save(d) { TKD.write(this.key(), d); },

  // however many things the child played today, regardless of which
  progressToday() {
    const pid = TKD.pid(), day = TKD.dayKey();
    if (!pid) return 0;
    try { return PlayerSystem.getAttempts().filter(a => a.playerId === pid && TKD.dayKey(a.ts) === day).length; }
    catch (e) { return 0; }
  },
  progress() { return Math.min(this.TARGET, this.progressToday()); },
  isDone() { return this.progressToday() >= this.TARGET; },
  isClaimed() { return this.data().claimed; },
  bonusStars() { return this.data().bonusStars || 0; },

  claim() {
    const d = this.data();
    if (d.claimed || !this.isDone()) return false;
    d.claimed = true; d.bonusStars = (d.bonusStars || 0) + this.REWARD;
    this.save(d);
    return true;
  },

  // ---------------------------------------------------------------- UI
  html() {
    const done = this.isDone(), claimed = this.isClaimed(), p = this.progress();
    const cls = claimed ? 'is-claimed' : done ? 'is-done' : '';
    const body = claimed
      ? `<b>${TKD.t('Today’s mission — done!', 'مهمة اليوم — خلصت!')}</b><small>${TKD.t('Come back tomorrow for a new one', 'تعال بكرة لمهمة جديدة')}</small>`
      : done
        ? `<b>${TKD.t('Mission complete — claim your gift!', 'خلصت المهمة — خد هديتك!')}</b><small>${TKD.t('Tap to collect ⭐ %n stars', 'دوس تاخد ⭐ %n نجوم').replace('%n', TKD.num(this.REWARD))}</small>`
        : `<b>${TKD.t('Today’s mission', 'مهمة اليوم')}</b><small>${TKD.t(`Play ${this.TARGET} things today for a gift`, `العب ${TKD.count(this.TARGET, 'thing', 'ar')} النهارده وخد هدية`)}</small>`;
    return `<button type="button" class="mission-box ${cls}" id="mission-box" ${claimed ? 'disabled' : ''}>
      <span class="mission-ico">${claimed ? '✅' : done ? '🎁' : '📋'}</span>
      <span class="mission-text">${body}</span>
      ${!claimed ? `<span class="mission-dots" aria-hidden="true">${Array.from({ length: this.TARGET }, (_, i) => `<i class="${i < p ? 'on' : ''}"></i>`).join('')}</span>` : ''}
    </button>`;
  },
  mount() {
    const board = document.querySelector('.jr-map .jr-head');
    if (!board || !board.parentNode) return;
    const host = board.parentNode;
    const prev = host.querySelector('#mission-box');
    const wasClaimed = prev?.classList.contains('is-claimed');
    const html = this.html();
    if (prev) { if (prev.outerHTML === html) return; prev.outerHTML = html; }
    else host.insertBefore(document.createRange().createContextualFragment(html), board.nextSibling);
    const box = document.getElementById('mission-box');
    box?.addEventListener('click', () => {
      if (!this.claim()) return;
      AudioKit?.sfx?.('star', { gain: 0.6 });
      TKD.toast(TKD.t(`Gift claimed — +${this.REWARD} stars!`, `أخدت الهدية — +${TKD.count(this.REWARD, 'star', 'ar')}!`), 'success');
      this.mount();
    });
    if (!wasClaimed && this.isDone() && !this.isClaimed()) box?.classList.add('mission-pop');
  },
  init() {
    document.addEventListener('tkd:screen', (e) => { if (e.detail?.screenId === 'home') setTimeout(() => this.mount(), 80); });
    // a game just finished — the mission's progress dots (and gift, once
    // earned) should be there the moment the child gets back to the map
    document.addEventListener('tkd:player-changed', () => this.mount());
  }
};
window.Mission = Mission;
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => Mission.init()); else Mission.init();

// #####################################################################
// ## offline support + update banner
// #####################################################################
// Register the service worker for offline play (kids can keep training
// in the gym even if the wifi/data drops).
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').then((reg) => {
      // A worker installing while we already have a controller means
      // this is an UPDATE (not the first-ever install) — tell the
      // player instead of silently swapping assets under them.
      const notifyIfUpdate = (worker) => {
        if (!navigator.serviceWorker.controller) return;
        worker.addEventListener('statechange', () => {
          if (worker.state === 'installed') showUpdateBanner();
        });
      };
      if (reg.installing) notifyIfUpdate(reg.installing);
      reg.addEventListener('updatefound', () => { if (reg.installing) notifyIfUpdate(reg.installing); });
    }).catch((err) => {
      console.warn('Service worker registration failed:', err);
    });
  });
}

function showUpdateBanner() {
  const banner = document.getElementById('sw-update-banner');
  const text = document.getElementById('sw-update-text');
  if (!banner || banner.dataset.shown) return;
  banner.dataset.shown = '1';
  const ar = (typeof TKD !== 'undefined' && TKD.ar) || (typeof GameStateInstance !== 'undefined' && GameStateInstance.currentLanguage === 'ar');
  text.textContent = ar ? '🎉 فيه نسخة جديدة من اللعبة جاهزة!' : '🎉 A new version of the game is ready!';
  document.getElementById('sw-update-refresh').textContent = ar ? 'حدّث دلوقتي' : 'Refresh now';
  banner.classList.remove('hidden');
}
document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('sw-update-refresh')?.addEventListener('click', () => location.reload());
  document.getElementById('sw-update-dismiss')?.addEventListener('click', () => {
    document.getElementById('sw-update-banner')?.classList.add('hidden');
  });
});

// =====================================================================
// v55 — the Games screen: the 4 main games first. The 8 extra games are
// folded under one button until the child has tried the main 4 of this
// kick (they can still open them any time), so a 6-year-old is not faced
// with 12 cards at once.
// =====================================================================
const BonusFold = {
  key() { return `taekwondoJourneyBonusOpen:${TKD.pid() || 'guest'}`; },
  apply() {
    const scr = document.getElementById('games-screen'); if (!scr) return;
    const grid = scr.querySelector('.game-cards-bonus'), title = scr.querySelector('.games-section-title[data-i18n="bonusGames"]');
    if (!grid || !title) return;
    const gs = TKD.gs(); const sc = gs?.skillGameScores?.[gs.currentSkill] || {};
    const coreTried = ['formControl', 'puzzle', 'performance', 'action'].filter(k => (sc[k] || 0) > 0).length;
    const open = coreTried >= 4 || TKD.read(this.key(), false) === true;
    const n = grid.querySelectorAll('.game-card:not(.hidden)').length;
    grid.classList.toggle('bonus-folded', !open);
    let btn = scr.querySelector('.bonus-unfold');
    if (open) { btn?.remove(); return; }
    if (!btn) {
      btn = document.createElement('button'); btn.type = 'button'; btn.className = 'bonus-unfold';
      btn.addEventListener('click', () => { TKD.write(this.key(), true); gs?.playSound('click'); this.apply(); });
      grid.before(btn);
    }
    btn.innerHTML = `🎯 ${TKD.t(`${n} extra games`, `${TKD.num(n)} ألعاب زيادة`)} <small>${TKD.t(`Try the 4 main games first (${coreTried}/4) — or`, `جرّب الألعاب الأساسية الأول (${TKD.num(coreTried)}/٤) — أو`)}</small> <b>${TKD.t('show them', 'وريني')} ▾</b>`;
  }
};
document.addEventListener('tkd:screen', (e) => { if (e.detail?.screenId === 'games') setTimeout(() => BonusFold.apply(), 30); });
document.addEventListener('tkd:lang', () => setTimeout(() => BonusFold.apply(), 80));
window.BonusFold = BonusFold;

// =====================================================================
// v55 — "TRAIN FOR REAL": the game is a coach, not only a screen.
// The 3D fighter keeps doing the kick slowly; the child does the REAL kick
// in the room and counts it — with a big button, or with a loud "Kihap!"
// that the microphone hears. 10 kicks with the right leg, then 10 with the
// left (the fighter switches legs too). An optional MIRROR shows the
// child's own camera next to the fighter, like the mirror wall of a dojang.
// Nothing is recorded or saved: the camera and mic stay on this device and
// stop the moment the window closes.
// =====================================================================
const RealPractice = {
  GOAL: 10,
  open(skillId) {
    const gs = TKD.gs(); if (!gs) return;
    this.close();
    this.skill = skillId || gs.currentSkill || 'apchagi';
    this.side = 'right'; this.count = { right: 0, left: 0 };
    const ov = document.createElement('div');
    ov.className = 'rp-modal'; ov.id = 'rp-modal'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true');
    document.body.appendChild(ov);
    this.render();
    this.startFighter();
    gs.playSound('click');
  },
  close() {
    this._tok = (this._tok || 0) + 1;
    this.stopMic(); this.stopCam();
    document.getElementById('rp-modal')?.remove();
  },
  t(en, ar) { return TKD.t(en, ar); },
  render() {
    const ov = document.getElementById('rp-modal'); if (!ov) return;
    const n = this.count[this.side], done = this.count.right >= this.GOAL && this.count.left >= this.GOAL;
    ov.innerHTML = `<div class="rp-card">
      <button type="button" class="rp-x" data-a="close" aria-label="${this.t('Close', 'قفل')}">✕</button>
      <h3>🥋 ${this.t('Train for real', 'اتمرّن بجد')} — ${TKD.esc(TKD.skillName(this.skill))}</h3>
      <p class="rp-sub">${done ? this.t('Both legs done — you are a real fighter! 🏆', 'خلّصت الرجلين — إنت بطل بجد! 🏆')
        : this.t(`Stand up, make some room, and do ${this.GOAL} real kicks with your ${this.side === 'right' ? 'RIGHT' : 'LEFT'} leg — like the fighter.`, `قوم اقف، وفضّي مكان حواليك، واعمل ${TKD.count(this.GOAL, 'kick', 'ar')} بجد برجلك ${this.side === 'right' ? 'اليمين' : 'الشمال'} زي اللاعب.`)}</p>
      <div class="rp-stage">
        <canvas class="rp-cv" id="rp-cv" aria-hidden="true"></canvas>
        <video class="rp-cam" id="rp-cam" playsinline muted ${this._cam ? '' : 'hidden'}></video>
      </div>
      <div class="rp-count" aria-live="polite"><b>${TKD.num(n)}</b><span>/ ${TKD.num(this.GOAL)}</span>
        <small>${this.side === 'right' ? this.t('right leg', 'الرجل اليمين') : this.t('left leg', 'الرجل الشمال')}</small></div>
      <div class="rp-meter" id="rp-meter" ${this._mic ? '' : 'hidden'}><i id="rp-level"></i></div>
      <div class="rp-btns">
        ${done ? `<button type="button" class="btn btn-success" data-a="close">✓ ${this.t('Done', 'تمام')}</button>`
          : `<button type="button" class="btn btn-success rp-kick" data-a="kick">🦶 ${this.t('I did a kick!', 'عملت ركلة!')}</button>`}
        <button type="button" class="btn ${this._mic ? 'on' : ''}" data-a="mic">🎤 ${this._mic ? this.t('Kihap counting is ON', 'العدّ بالكياي شغّال') : this.t('Count with my Kihap!', 'عدّ بصوت الكياي!')}</button>
        <button type="button" class="btn ${this._cam ? 'on' : ''}" data-a="cam">🪞 ${this._cam ? this.t('Hide the mirror', 'اقفل المراية') : this.t('Mirror (camera)', 'المراية (الكاميرا)')}</button>
      </div>
      <p class="rp-note">🔒 ${this.t('The camera and microphone stay on this device — nothing is recorded or sent.', 'الكاميرا والمايك بيفضلوا على الجهاز ده — مفيش حاجة بتتسجل ولا بتتبعت.')}</p>
    </div>`;
    ov.querySelectorAll('[data-a]').forEach(b => b.addEventListener('click', () => this.act(b.dataset.a)));
    if (this._cam && this._stream) { const v = document.getElementById('rp-cam'); if (v) { v.srcObject = this._stream; v.play().catch(() => {}); } }
  },
  act(a) {
    const gs = TKD.gs();
    if (a === 'close') { this.close(); return; }
    if (a === 'kick') { this.tally(); return; }
    if (a === 'mic') { this._mic ? this.stopMic() : this.startMic(); return; }
    if (a === 'cam') { this._cam ? this.stopCam() : this.startCam(); return; }
  },
  tally() {
    const gs = TKD.gs();
    if (this.count.right >= this.GOAL && this.count.left >= this.GOAL) return;
    this.count[this.side]++;
    gs?.playSound('strike');
    try { navigator.vibrate?.(30); } catch (e) {}
    this._flash = performance.now();
    if (this.count[this.side] >= this.GOAL) {
      if (this.side === 'right') { this.side = 'left'; TKD.toast(this.t('Great! Now the LEFT leg 🦵', 'جامد! دلوقتي بالرجل الشمال 🦵'), 'success'); window.Voice?.cue('great'); }
      else { gs?.playSound('win'); window.Voice?.cue('bravo'); this.stopMic(); }
    }
    this.render();
  },
  // ---- the fighter, kicking slowly on a loop (mirrored for the left leg)
  async startFighter() {
    const tok = this._tok;
    const gs = TKD.gs(), ch = gs?.playerCharacter === 'girl' ? 'girl' : 'boy';
    const rig = await RigBackend.character(ch).catch(() => null);
    if (!rig || tok !== this._tok) return;
    const anim = RigSupport.animFor(rig.data, this.skill) || ({ apchagi: 'apchagi', narochagi: 'naeryeo', bakchagi3: 'yeop' })[this.skill];
    const A = rig.data.animations[anim]; if (!A) return;
    const sk = RigBackend.newSkeleton(rig); sk.viewYaw = RigBackend.GAME_YAW; sk.viewPitch = 0;
    const dur = A.duration || 1; let t = 0, last = performance.now();
    const loop = (now) => {
      if (tok !== this._tok) return;
      const cv = document.getElementById('rp-cv'); if (!cv) { requestAnimationFrame(loop); return; }
      const dt = Math.min(0.05, (now - last) / 1000); last = now;
      t = (t + dt * 0.45) % (dur + 0.6);                   // slow, with a short pause in the ready stance
      const w = cv.clientWidth || 300, h = cv.clientHeight || 260, dpr = Math.min(2, window.devicePixelRatio || 1);
      if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(h * dpr)) { cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr); }
      const g = cv.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h);
      sk.mirror = this.side === 'left';
      RigBackend.poseAt(rig, sk, anim, Math.min(t, dur), 0);
      const s = Math.min(h * 0.9 / 1300, w / 1300);
      const x = sk.mirror ? w * 0.72 : w * 0.28;
      if (this._flash && now - this._flash < 260) { g.fillStyle = 'rgba(255,209,102,.18)'; g.fillRect(0, 0, w, h); }
      g.fillStyle = 'rgba(0,0,0,.3)'; g.beginPath(); g.ellipse(x, h * 0.93, 70, 8, 0, 0, Math.PI * 2); g.fill();
      sk.draw(g, x, h * 0.93, s);
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  },
  // ---- Kihap counting: a loud shout = one kick (with a short pause so one shout counts once)
  async startMic() {
    if (!navigator.mediaDevices?.getUserMedia) { TKD.toast(this.t('This device has no microphone access.', 'الجهاز ده مش بيدّي إذن للمايك.'), 'warning'); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: false, noiseSuppression: false } });
      const AC = window.AudioContext || window.webkitAudioContext; const ac = new AC();
      const src = ac.createMediaStreamSource(stream), an = ac.createAnalyser(); an.fftSize = 1024; src.connect(an);
      const buf = new Float32Array(an.fftSize); let lastHit = 0; let floor = 0.02;
      this._mic = { stream, ac };
      const tok = this._tok;
      const tick = () => {
        if (!this._mic || tok !== this._tok) return;
        an.getFloatTimeDomainData(buf); let rms = 0; for (let i = 0; i < buf.length; i++) rms += buf[i] * buf[i]; rms = Math.sqrt(rms / buf.length);
        floor = floor * 0.995 + Math.min(rms, 0.05) * 0.005;            // the room's own noise level
        const lvl = document.getElementById('rp-level'); if (lvl) lvl.style.width = `${Math.min(100, Math.round(rms * 400))}%`;
        const now = performance.now();
        if (rms > Math.max(0.12, floor * 6) && now - lastHit > 700) { lastHit = now; this.tally(); }
        requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
      this.render();
      TKD.toast(this.t('Shout "Kihap!" with every kick 🔊', 'اصرخ «كياي!» مع كل ركلة 🔊'), 'info');
    } catch (e) { TKD.toast(this.t('The microphone was not allowed — use the button instead.', 'المايك ماتسمحش — استخدم الزرار بدله.'), 'warning'); }
  },
  stopMic() {
    if (!this._mic) return;
    try { this._mic.stream.getTracks().forEach(t => t.stop()); this._mic.ac.close(); } catch (e) {}
    this._mic = null;
    if (document.getElementById('rp-modal')) this.render();
  },
  // ---- the mirror: the child's own (front) camera, flipped like a real mirror
  async startCam() {
    if (!navigator.mediaDevices?.getUserMedia) { TKD.toast(this.t('This device has no camera access.', 'الجهاز ده مش بيدّي إذن للكاميرا.'), 'warning'); return; }
    try {
      this._stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
      this._cam = true; this.render();
    } catch (e) { TKD.toast(this.t('The camera was not allowed.', 'الكاميرا ماتسمحتش.'), 'warning'); }
  },
  stopCam() {
    try { this._stream?.getTracks().forEach(t => t.stop()); } catch (e) {}
    this._stream = null; this._cam = false;
    if (document.getElementById('rp-modal')) this.render();
  }
};
window.RealPractice = RealPractice;
// entry points: the kick's menu and the end of the lesson
document.addEventListener('tkd:screen', (e) => {
  if (e.detail?.screenId !== 'skill-menu' && e.detail?.screenId !== 'learning') return;
  setTimeout(() => {
    const host = e.detail.screenId === 'skill-menu' ? document.querySelector('#skill-menu-screen .game-container') : document.querySelector('#learning-screen .game-container');
    if (!host || host.querySelector('.rp-open')) { host?.querySelectorAll('.rp-open').forEach(b => { b.textContent = `🥋 ${TKD.t('Train for real — kick in the room!', 'اتمرّن بجد — اركل في الأوضة!')}`; }); return; }
    const b = document.createElement('button'); b.type = 'button'; b.className = 'btn rp-open';
    b.textContent = `🥋 ${TKD.t('Train for real — kick in the room!', 'اتمرّن بجد — اركل في الأوضة!')}`;
    b.addEventListener('click', () => RealPractice.open(TKD.gs()?.currentSkill));
    const back = host.querySelector(':scope > .center-buttons, :scope > .btn.back-btn, :scope > .game-controls');
    if (back) back.before(b); else host.appendChild(b);
  }, 80);
});
document.addEventListener('tkd:screen', () => { if (document.getElementById('rp-modal')) RealPractice.close(); });

// =====================================================================
// v55 — a friendly break after 20 minutes of screen time: get up, kick for
// real, drink some water. Counts only time the game is actually on screen.
// =====================================================================
const BreakReminder = {
  EVERY_MIN: 20,
  start() {
    if (this._iv) return;
    this.mins = 0;
    this._iv = setInterval(() => {
      if (document.visibilityState !== 'visible' || document.body.classList.contains('start-open') || !TKD.pid()) return;
      this.mins++;
      if (this.mins >= this.EVERY_MIN) { this.mins = 0; this.show(); }
    }, 60000);
  },
  show() {
    if (document.getElementById('break-modal') || document.getElementById('rp-modal')) return;
    const ov = document.createElement('div'); ov.className = 'tkd-modal'; ov.id = 'break-modal';
    ov.innerHTML = `<div class="tkd-modal-card break-card"><div class="break-emoji">🧘💧🦵</div>
      <h3>${TKD.t('Time for a little break!', 'وقت راحة صغيرة!')}</h3>
      <p>${TKD.t('You have been playing for 20 minutes. Stand up, drink some water, and do 10 real kicks.', 'بقالك ٢٠ دقيقة بتلعب. قوم اقف، اشرب مية، واعمل ١٠ ركلات بجد.')}</p>
      <div class="tkd-row"><button type="button" class="btn" data-a="ok">${TKD.t('OK!', 'تمام!')}</button><button type="button" class="btn btn-success" data-a="kick">🥋 ${TKD.t('Kick with me', 'اركل معايا')}</button></div></div>`;
    document.body.appendChild(ov);
    ov.querySelector('[data-a="ok"]').addEventListener('click', () => ov.remove());
    ov.querySelector('[data-a="kick"]').addEventListener('click', () => { ov.remove(); RealPractice.open(TKD.gs()?.currentSkill); });
  }
};
window.BreakReminder = BreakReminder;
BreakReminder.start();


// =====================================================================
// v56 — THE CLUB (online). Every device of the gym joins ONE club with a
// 6-letter code from the coach. Each device sends a public profile of its
// players (name, belt, level, medals, this week's points, today's challenge…)
// and receives everybody else's — so the league, today's challenge ranking
// and the heroes wall are the whole gym's, not one phone's.
// Without a server configured (club-config.js) nothing changes: the game
// stays fully offline. With no signal it keeps working and sends later.
// =====================================================================
const Club = {
  KEY: 'taekwondoJourneyClub',             // this device's membership: { clubId, name, role, code, joinedAt, lastSync }
  CACHE: 'taekwondoJourneyClubCache',      // the last club picture: { clubId, players: { id: profile }, club, at }
  status: 'off',                           // off · connecting · online · offline · error
  error: '',
  _sent: {},
  configured() { return !!(window.TKD_CLUB_BACKEND_FACTORY || window.TKD_FIREBASE); },
  usable() { return this.configured() && /^https?:$/.test(location.protocol); },
  info() { return TKD.read(this.KEY, null); },
  joined() { return !!this.info()?.clubId; },
  isCoach() { return this.joined() && this.info().role === 'coach'; },
  cache() { const c = TKD.read(this.CACHE, null); return c && c.clubId === this.info()?.clubId ? c : { clubId: this.info()?.clubId, players: {}, club: null, at: 0 }; },
  device() {
    const ua = navigator.userAgent || '';
    return (/iPad/.test(ua) ? 'iPad' : /iPhone/.test(ua) ? 'iPhone' : /Android/.test(ua) ? (/Mobile/.test(ua) ? 'Android' : 'Android tablet') : /Mac/.test(ua) ? 'Mac' : /Windows/.test(ua) ? 'Windows' : 'Device');
  },
  set(status, error = '') { const ch = this.status !== status || this.error !== error; this.status = status; this.error = error; if (ch) document.dispatchEvent(new CustomEvent('tkd:club', { detail: { status } })); },
  changed() { this._memo = null; document.dispatchEvent(new CustomEvent('tkd:club', { detail: { status: this.status, data: true } })); },
  timeout(p, ms = 15000) { return Promise.race([p, new Promise((_, rej) => setTimeout(() => { const e = new Error('timeout'); e.code = 'timeout'; rej(e); }, ms))]); },
  async be() {
    if (this._be) return this._be;
    if (!this._bep) this._bep = (async () => {
      const f = window.TKD_CLUB_BACKEND_FACTORY;                          // (the automated tests plug a fake server in here)
      const be = f ? await f() : (await import('./assets/lib/cloud/backend.js')).makeBackend(window.TKD_FIREBASE);
      await this.timeout(be.init());
      this._be = be; return be;
    })().catch(e => { this._bep = null; throw e; });
    return this._bep;
  },
  // human words for what went wrong
  why(code) {
    const m = {
      'bad-code': ['That club code does not exist — check the letters.', 'كود النادي ده مش موجود — راجع الحروف.'],
      timeout: ['No answer from the server — is there internet?', 'السيرفر مش بيرد — فيه نت؟'],
      unavailable: ['No internet right now — it will sync when the signal is back.', 'مفيش نت دلوقتي — هيتزامن لما النت يرجع.'],
      'permission-denied': ['Not allowed — this device may have been removed from the club.', 'مش مسموح — يمكن الجهاز ده اتشال من النادي.'],
      'wrong-coach-code': ['That recovery code is not right.', 'كود الاسترجاع ده مش مظبوط.'],
      removed: ['This device was removed from the club by the coach.', 'المدرب شال الجهاز ده من النادي.'],
      // the usual Firebase set-up slips, in plain words (see CLUB_SETUP_AR.md)
      'auth/network-request-failed': ['No internet right now — try again when there is signal.', 'مفيش نت دلوقتي — جرّب تاني لما يبقى فيه شبكة.'],
      'auth/operation-not-allowed': ['Firebase: turn on Anonymous sign-in (Authentication → Sign-in method).', 'Firebase: فعّل الدخول Anonymous (Authentication ← Sign-in method).'],
      'auth/admin-restricted-operation': ['Firebase: turn on Anonymous sign-in (Authentication → Sign-in method).', 'Firebase: فعّل الدخول Anonymous (Authentication ← Sign-in method).'],
      'auth/unauthorized-domain': ['Firebase: add this website to Authentication → Settings → Authorized domains.', 'Firebase: ضيف رابط الموقع ده في Authentication ← Settings ← Authorized domains.'],
      'auth/invalid-api-key': ['The Firebase settings in club-config.js are not right — copy them again.', 'إعدادات Firebase في club-config.js مش مظبوطة — انسخها تاني.'],
      'auth/api-key-not-valid.-please-pass-a-valid-api-key.': ['The Firebase settings in club-config.js are not right — copy them again.', 'إعدادات Firebase في club-config.js مش مظبوطة — انسخها تاني.'],
      'failed-precondition': ['Firebase: create the Firestore database first (Build → Firestore Database).', 'Firebase: اعمل قاعدة بيانات Firestore الأول (Build ← Firestore Database).'],
      'not-found': ['Firebase: create the Firestore database first (Build → Firestore Database).', 'Firebase: اعمل قاعدة بيانات Firestore الأول (Build ← Firestore Database).']
    }[code];
    return m ? TKD.t(m[0], m[1]) : TKD.t(`Something went wrong (${code || '?'})`, `حصلت مشكلة (${code || '?'})`);
  },

  // ---------------------------------------------------------------- joining
  saveInfo(patch) { const i = { ...(this.info() || {}), ...patch }; TKD.write(this.KEY, i); return i; },
  async create(name) {
    const be = await this.be();
    const r = await this.timeout(be.createClub({ name: String(name).trim().slice(0, 40), device: this.device() }));
    this.saveInfo({ clubId: r.clubId, name: r.name, role: 'coach', code: r.code, joinedAt: Date.now(), revoked: false });
    this.connect(); this.pushSoon(500);
    return r;                                                            // r.coachCode is shown ONCE to write down
  },
  async join(code) {
    const be = await this.be();
    const r = await this.timeout(be.joinClub({ code: String(code).toUpperCase().replace(/[^A-Z0-9]/g, ''), device: this.device() }));
    this.saveInfo({ clubId: r.clubId, name: r.name, role: 'device', code: '', joinedAt: Date.now(), revoked: false });
    this.connect(); this.pushSoon(500);
    return r;
  },
  async claimCoach(coachCode) {
    const be = await this.be(), info = this.info();
    try { await this.timeout(be.claimCoach({ clubId: info.clubId, coachCode: String(coachCode).toUpperCase().trim(), device: this.device() })); }
    catch (e) { if (e.code === 'permission-denied') { const x = new Error('wrong-coach-code'); x.code = 'wrong-coach-code'; throw x; } throw e; }
    const club = await be.getClub(info.clubId).catch(() => null);
    this.saveInfo({ role: 'coach', code: club?.joinCode || info.code });
  },
  async leave() {
    const info = this.info(); if (!info) return;
    this.disconnect();
    try { const be = await this.be(); await this.timeout(be.leave(info.clubId), 8000); } catch (e) { /* offline: the coach can remove the device later */ }
    TKD.write(this.KEY, null); try { localStorage.removeItem(this.KEY); localStorage.removeItem(this.CACHE); } catch (e) {}
    this._sent = {}; this.set('off'); this.changed();
  },
  async newCode() {
    const be = await this.be(), info = this.info();
    const code = await this.timeout(be.newJoinCode(info.clubId, info.code));
    this.saveInfo({ code }); return code;
  },

  // ---------------------------------------------------------------- live link
  async connect() {
    if (!this.joined() || !this.usable()) { this.set('off'); return; }
    if (this._unsub) return;
    this.set(navigator.onLine === false ? 'offline' : 'connecting');
    let be; try { be = await this.be(); } catch (e) { this.set(navigator.onLine === false ? 'offline' : 'error', e.code || e.message); this.retry(); return; }
    const info = this.info(); if (!info?.clubId || this._unsub) return;
    const fail = (code) => {
      if (code === 'permission-denied') { this.disconnect(); this.saveInfo({ revoked: true }); this.set('error', 'removed'); return; }
      this.set(navigator.onLine === false ? 'offline' : 'error', code);
    };
    const u1 = be.watchPlayers(info.clubId, (list, meta) => {
      const c = this.cache();
      c.clubId = info.clubId; c.players = {};
      list.forEach(d => { if (d && d.id) c.players[d.id] = this.clean(d); });
      c.at = Date.now(); TKD.write(this.CACHE, c);
      // one of this device's players is missing on the server, or someone else (the coach) wrote it last → send ours again
      if (!meta?.fromCache) {
        const me = be.uid(); let again = false;
        PlayerSystem.getPlayers().forEach(p => { const d = c.players[p.id]; if (!p.clubOff && (!d || (!d.removed && d.by && d.by !== me))) { delete this._sent[p.id]; again = true; } });
        if (again) this.pushSoon(2500);
      }
      if (!meta?.fromCache) { this.saveInfo({ lastSync: Date.now(), revoked: false }); this.set('online'); }
      else if (navigator.onLine === false) this.set('offline');
      this.changed();
    }, fail);
    const u2 = be.watchClub(info.clubId, (club) => {
      if (!club) return;
      const c = this.cache(); c.club = { name: club.name, joinCode: club.joinCode }; TKD.write(this.CACHE, c);
      const patch = { name: club.name }; if (this.isCoach()) patch.code = club.joinCode;
      this.saveInfo(patch); this.changed();
    }, fail);
    this._unsub = () => { try { u1?.(); u2?.(); } catch (e) {} };
  },
  disconnect() { this._unsub?.(); this._unsub = null; clearTimeout(this._rt); },
  retry() { clearTimeout(this._rt); this._rt = setTimeout(() => this.connect(), 20000); },
  // Firestore timestamps → plain milliseconds (so the copy kept on the device is plain JSON)
  clean(d) {
    const at = d.at; const ms = typeof at === 'number' ? at : at?.toMillis ? at.toMillis() : at?.seconds ? at.seconds * 1000 : Date.now();
    return { ...d, at: ms };
  },

  // ---------------------------------------------------------------- the public profile of one player
  snapshot(p) {
    if (!p || !window.Profile) return null;
    const c = Profile.ctx(p.id); if (!c) return null;
    const achs = Profile.achievements(c), trophies = Profile.trophies(c), lv = Profile.level(achs, trophies);
    const wk = TKD.weekKey(), prevW = TKD.addDays(wk, -7), w = League.pointsFor(p.id, wk), pv = League.pointsFor(p.id, prevW);
    const day = TKD.dayKey(), best = Challenge.best(p.id, day);
    const int = (v) => Math.max(0, Math.round(Number(v) || 0));
    const recs = Profile.records(c), rec = (id) => recs.find(r => r.id === id)?.v ?? null;
    return {
      v: 1, id: p.id, name: String(p.name || '?').slice(0, 18), character: p.character === 'girl' ? 'girl' : 'boy',
      belt: c.belt.id, mastered: int(c.mastered), level: Math.max(1, int(lv.level)), tier: Math.min(4, int(League.tierOf(p))),
      ach: Object.fromEntries(achs.filter(a => a.tier > 0).map(a => [a.id, a.tier])),
      trophies: trophies.filter(t => t.ok).map(t => t.id).slice(0, 40),
      mastery: window.DashboardSystem ? DashboardSystem.masteryFor(p.id).map(m => int(m.overall)) : [],
      streak: int(c.weekStreak), days: int(c.days.length), games: int(c.played.length), perfect: int(c.perfect),
      records: { power: rec('power') === null ? null : int(rec('power')), reaction: rec('reaction'), challenge: rec('challenge') === null ? null : int(rec('challenge')) },
      week: { k: wk, pts: Math.min(1000, int(w.total)), ch: int(w.challenge), warm: int(w.warmDays), train: int(w.trainDays), chDays: int(w.challengeDays) },
      prev: { k: prevW, pts: Math.min(1000, int(pv.total)) },
      today: { d: day, ch: best === null ? -1 : int(best), g: Challenge.today(day).gameId },
      badges: int((p.badges || []).length), frame: (() => { try { const f = window.Shop?.frame(p.id); return typeof f === 'string' ? f.slice(0, 24) : null; } catch (e) { return null; } })(),
      removed: false
    };
  },
  // ---------------------------------------------------------------- sending
  pushSoon(delay = 6000) {
    if (!this.joined() || !this.usable() || this.info()?.revoked) return;
    clearTimeout(this._pt); this._pt = setTimeout(() => this.pushNow(), delay);
  },
  async pushNow() {
    if (!this.joined() || !this.usable() || this._pushing) return;
    this._pushing = true;
    try {
      const be = await this.be(), info = this.info(), cache = this.cache();
      const byCoach = (id) => cache.players[id]?.removed && !cache.players[id]?.self;
      const players = PlayerSystem.getPlayers().filter(p => !byCoach(p.id));
      // a player the parent/coach chose not to show → an empty "hidden" profile, once
      players.filter(p => p.clubOff && cache.players[p.id] && !cache.players[p.id].removed && this._sent[p.id] !== 'hidden').forEach(p => {
        this._sent[p.id] = 'hidden';
        be.hidePlayer(info.clubId, p.id, p.name).catch(() => { delete this._sent[p.id]; });
      });
      const docs = players.filter(p => !p.clubOff).map(p => this.snapshot(p)).filter(Boolean);
      for (const d of docs) {                       // one at a time: one refused profile never blocks the others
        const key = JSON.stringify(d); if (this._sent[d.id] === key) continue;
        this._sent[d.id] = key;
        be.putPlayers(info.clubId, [d]).catch(e => { delete this._sent[d.id]; if (e.code === 'permission-denied') this.connect(); });
      }
      if (!this._unsub) this.connect();
    } catch (e) { this.set(navigator.onLine === false ? 'offline' : 'error', e.code || e.message); }
    finally { this._pushing = false; }
  },

  // ---------------------------------------------------------------- reading
  // everybody: this device's players with fresh numbers + everyone else's last profile
  rows() {
    if (this._memo && Date.now() - this._memo.t < 1500) return this._memo.rows;
    const cache = this.cache().players, local = PlayerSystem.getPlayers(), ids = new Set(local.map(p => p.id));
    const rows = local.map(p => ({ ...(this.snapshot(p) || { id: p.id, name: p.name, character: p.character }), local: true, off: !!p.clubOff }));
    Object.values(cache).forEach(d => { if (d && !d.removed && !ids.has(d.id)) rows.push({ ...d, local: false }); });
    this._memo = { t: Date.now(), rows };
    return rows;
  },
  find(id) { return this.rows().find(r => r.id === id) || null; },
  avatar(d, cls = '') {
    if (d.local) { const p = PlayerSystem.getPlayers().find(x => x.id === d.id); if (p) return TKD.avatar(p, cls); }
    const ch = d.character === 'girl' ? 'girl' : 'boy', fr = typeof d.frame === 'string' ? d.frame : null;
    return `<span class="tkd-avatar ${cls}${fr ? (fr === 'rainbow' ? ' tkd-frame-rainbow' : ' tkd-framed') : ''}" data-ch="${ch}"${fr && fr !== 'rainbow' ? ` style="--frame:${TKD.esc(fr)}"` : ''}><img src="${PoseShots.url(ch, 'portrait')}" alt=""></span>`;
  },
  // the league table of one week for the whole club
  leagueRows(week = TKD.weekKey()) {
    const players = PlayerSystem.getPlayers();
    return this.rows().map(d => {
      if (d.local) { const p = players.find(x => x.id === d.id); return { p, tier: League.tierOf(p), ...League.pointsFor(d.id, week), prevTotal: League.pointsFor(d.id, TKD.addDays(week, -7)).total, local: true }; }
      const w = d.week?.k === week ? d.week : null, pv = d.prev?.k === week ? d.prev : null;
      return { p: { id: d.id, name: d.name, character: d.character, remote: true }, tier: d.tier | 0, total: w ? w.pts : pv ? pv.pts : 0,
               challenge: w?.ch || 0, warmDays: w?.warm || 0, trainDays: w?.train || 0, challengeDays: w?.chDays || 0,
               prevTotal: w && d.prev?.k === TKD.addDays(week, -7) ? d.prev.pts : 0, local: false };
    });
  },
  // today's challenge, the other devices' best scores
  remoteToday(day = TKD.dayKey()) {
    const ids = new Set(PlayerSystem.getPlayers().map(p => p.id));
    return Object.values(this.cache().players).filter(d => d && !d.removed && !ids.has(d.id) && d.today?.d === day && d.today.ch >= 0)
      .map(d => ({ pid: d.id, name: d.name, character: d.character, score: d.today.ch, ts: d.at || 0, remote: true }));
  },
  statusLine() {
    if (!this.joined()) return '';
    const last = this.info()?.lastSync;
    const ago = last ? (Date.now() - last < 90e3 ? TKD.t('just now', 'دلوقتي') : new Date(last).toLocaleString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })) : '—';
    const s = { online: ['☁️', TKD.t('Connected to the club', 'متوصل بالنادي')], connecting: ['⏳', TKD.t('Connecting…', 'بيتوصل…')], offline: ['📴', TKD.t('No internet — showing the last update, will sync later', 'مفيش نت — بنعرض آخر تحديث، وهيتزامن بعدين')],
                error: ['⚠️', this.why(this.error)], off: ['☁️', TKD.t('Club', 'النادي')] }[this.status] || ['☁️', ''];
    return `<div class="club-status club-${this.status}"><span>${s[0]} <b>${TKD.esc(this.info()?.name || '')}</b> · ${s[1]}</span><small>${TKD.t('Last update', 'آخر تحديث')}: ${ago}</small></div>`;
  },

  // ---------------------------------------------------------------- a club hero's card (read-only)
  showHero(id) {
    const d = this.find(id); if (!d) return;
    if (d.local) { window.Profile?.open(id); return; }
    const belt = GameState.BELTS.find(b => b.id === d.belt) || GameState.BELTS[0];
    const tierI = Math.min(League.TIERS.length - 1, d.tier | 0), tier = League.TIERS[tierI];
    const medals = (window.Profile ? Profile.ACH : []).filter(a => d.ach?.[a.id]).map(a => `<span class="ch-medal t${d.ach[a.id]}" title="${TKD.esc(TKD.t(a.en, a.ar))}">${a.icon}<small>${['', '🥉', '🥈', '🥇'][d.ach[a.id]] || ''}</small><i>${TKD.esc(TKD.t(a.en, a.ar))}</i></span>`).join('');
    const kicks = GameConfig.SKILL_ORDER.map((sk, i) => `<div class="ch-kick"><span>${TKD.esc(TKD.skillName(sk))}</span><span class="ch-bar"><i style="width:${Math.min(100, d.mastery?.[i] || 0)}%"></i></span><b>${TKD.num(d.mastery?.[i] || 0)}${TKD.ar ? '٪' : '%'}</b></div>`).join('');
    const r = d.records || {};
    const ov = document.createElement('div');
    ov.className = 'tkd-modal club-hero-modal';
    ov.innerHTML = `<div class="tkd-modal-card club-hero" role="dialog" aria-label="${TKD.esc(d.name)}">
      <button type="button" class="rp-x" data-x aria-label="${TKD.t('Close', 'اقفل')}">✕</button>
      <div class="ch-top">${this.avatar(d)}<div><h2>${TKD.esc(d.name)}</h2>
        <p><span class="ch-belt" style="--belt:${belt.color};--belt-2:${belt.accent}"></span>${TKD.esc(TKD.ar ? belt.name.ar : belt.name.en)}</p>
        <p>⭐ ${TKD.t('Level', 'المستوى')} ${TKD.num(d.level || 1)} · ${tier.icon} ${League.tierName(tierI)}</p></div></div>
      <div class="ch-stats">
        <div><b>${TKD.num(d.week?.k === TKD.weekKey() ? d.week.pts : 0)}</b><small>${TKD.t('points this week', 'نقط الأسبوع ده')}</small></div>
        <div><b>${d.today?.d === TKD.dayKey() && d.today.ch >= 0 ? TKD.num(d.today.ch) + (TKD.ar ? '٪' : '%') : '—'}</b><small>${TKD.t("today's challenge", 'تحدي النهارده')}</small></div>
        <div><b>${TKD.num(d.streak || 0)}</b><small>${TKD.t('weeks in a row', 'أسابيع ورا بعض')}</small></div>
        <div><b>${TKD.num(d.days || 0)}</b><small>${TKD.t('training days', 'أيام تمرين')}</small></div>
        <div><b>${TKD.num((d.trophies || []).length)}</b><small>${TKD.t('cups', 'كاسات')}</small></div>
        <div><b>${r.power ? '💪 ' + TKD.num(r.power) : '—'}</b><small>${TKD.t('strongest kick', 'أقوى ركلة')}</small></div>
      </div>
      <h3>🥋 ${TKD.t('Kicks', 'الركلات')}</h3><div class="ch-kicks">${kicks}</div>
      <h3>🏅 ${TKD.t('Medals', 'الميداليات')}</h3>
      ${medals ? `<div class="ch-medals">${medals}</div>` : `<p class="tkd-muted">${TKD.t('No medals yet.', 'لسه مفيش ميداليات.')}</p>`}
      <p class="ch-foot">${TKD.t('Updated', 'آخر تحديث')}: ${d.at ? new Date(d.at).toLocaleString(TKD.ar ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—'}</p>
      <div class="tkd-row"><button type="button" class="btn btn-success" data-x>${TKD.t('Close', 'اقفل')}</button></div></div>`;
    document.body.appendChild(ov);
    ov.addEventListener('click', e => { if (e.target === ov || e.target.closest('[data-x]')) ov.remove(); });
    TKD.gs()?.playSound('click');
  },

  // ---------------------------------------------------------------- the heroes wall (league screen, "club" tab)
  wallHTML() {
    const rows = this.rows();
    const wk = TKD.weekKey();
    const pts = (d) => d.local ? League.pointsFor(d.id, wk).total : (d.week?.k === wk ? d.week.pts : 0);
    const sorted = rows.slice().sort((a, b) => (b.level || 0) - (a.level || 0) || pts(b) - pts(a) || String(a.name).localeCompare(String(b.name)));
    return `${this.statusLine()}
      <p class="tkd-muted club-wall-sub">${TKD.t(`${rows.length} heroes in the club — tap one to see their medals`, `${TKD.count(rows.length, 'hero')} في النادي — دوس على أي حد تشوف ميدالياته`)}</p>
      <div class="club-wall">${sorted.map(d => {
        const belt = GameState.BELTS.find(b => b.id === d.belt) || GameState.BELTS[0];
        const tier = League.TIERS[Math.min(League.TIERS.length - 1, d.tier | 0)];
        const medals = Object.values(d.ach || {}).reduce((s, v) => s + v, 0);
        return `<button type="button" class="club-hero-card ${d.id === TKD.pid() ? 'me' : ''}" data-hero="${d.id}" style="--belt:${belt.color};--belt-2:${belt.accent}">
          ${this.avatar(d)}
          <b>${TKD.esc(d.name)}</b>
          <span class="chc-belt"></span>
          <small>⭐ ${TKD.num(d.level || 1)} · ${tier.icon} · 🏅 ${TKD.num(medals)}</small>
          <small>${TKD.t(TKD.count(pts(d), 'pt', 'en'), TKD.count(pts(d), 'point', 'ar'))} ${TKD.t('this week', 'الأسبوع ده')}</small>
          ${d.local ? `<span class="chc-here">${TKD.t('this device', 'الجهاز ده')}</span>` : ''}
        </button>`;
      }).join('')}</div>`;
  },

  // ---------------------------------------------------------------- coach: the club page
  coachHTML() {
    if (!this.configured()) return `<div class="club-setup"><h3>☁️ ${TKD.t('The online club', 'النادي أونلاين')}</h3>
      <p>${TKD.t('The club lets every device of the gym share the league, today\'s challenge and the heroes wall.', 'النادي بيخلي كل أجهزة الصالة يشوفوا نفس الدوري وتحدي النهارده وحيطة الأبطال.')}</p>
      <p class="co-voice-warn">⚙️ ${TKD.t('It needs a server: put your Firebase settings in club-config.js (see the guide).', 'محتاج سيرفر: حط إعدادات Firebase بتاعتك في ملف club-config.js (شوف الشرح).')}</p></div>`;
    if (!this.usable()) return `<div class="club-setup"><h3>☁️ ${TKD.t('The online club', 'النادي أونلاين')}</h3>
      <p class="co-voice-warn">🌐 ${TKD.t('Open the game from its web link (https://…) — the club cannot work when the game is opened from a folder.', 'افتح اللعبة من الرابط بتاعها على النت (https://…) — النادي مش بيشتغل واللعبة مفتوحة من فولدر.')}</p></div>`;
    if (!this.joined()) return `<div class="club-setup">
      <p>${TKD.t('Join this device to your gym\'s club: the league, today\'s challenge and the heroes wall become the whole gym\'s.', 'وصّل الجهاز ده بنادي الصالة: الدوري وتحدي النهارده وحيطة الأبطال يبقوا للصالة كلها.')}</p>
      <section class="club-box"><h3>🔑 ${TKD.t('Join with the club code', 'ادخل بكود النادي')}</h3>
        <input id="club-code" class="player-name-input club-code-in" maxlength="8" autocomplete="off" autocapitalize="characters" dir="ltr" placeholder="ABC234">
        <button type="button" class="btn btn-success" id="club-join">${TKD.t('Join', 'ادخل')}</button></section>
      <section class="club-box"><h3>🏟️ ${TKD.t('First time? Create the club (coach)', 'أول مرة؟ اعمل النادي (المدرب)')}</h3>
        <input id="club-name" class="player-name-input" maxlength="40" placeholder="${TKD.t('Club name, e.g. Champions Gym', 'اسم النادي، مثلًا: نادي الأبطال')}">
        <button type="button" class="btn" id="club-create">${TKD.t('Create the club', 'اعمل النادي')}</button>
        <p class="tkd-muted">${TKD.t('Make it once, on the coach\'s phone. Every other device joins with the code.', 'بيتعمل مرة واحدة بس، على موبايل المدرب. وباقي الأجهزة تدخل بالكود.')}</p></section>
      <p class="club-msg" id="club-msg" aria-live="polite"></p></div>`;
    const info = this.info(), rows = this.rows(), remote = rows.filter(r => !r.local).length, local = PlayerSystem.getPlayers();
    return `<div class="club-setup">${this.statusLine()}
      ${info.revoked ? `<p class="co-voice-warn">⚠️ ${this.why('removed')}</p>` : ''}
      <div class="club-counts"><span>👥 ${TKD.count(rows.length, 'hero')}</span><span>📱 ${TKD.t(`${local.length} on this device`, `${TKD.num(local.length)} على الجهاز ده`)}</span><span>🌍 ${TKD.t(`${remote} on other devices`, `${TKD.num(remote)} على أجهزة تانية`)}</span></div>
      ${this.isCoach() ? `<section class="club-box"><h3>🔑 ${TKD.t('Club code — type it on every device', 'كود النادي — اكتبه على كل جهاز')}</h3>
          <div class="club-code-big" dir="ltr" data-keep-digits>${TKD.esc(info.code || '······')}</div>
          <button type="button" class="btn btn-small" id="club-newcode">🔁 ${TKD.t('New code (the old one stops working)', 'كود جديد (القديم يبطل)')}</button></section>`
        : `<button type="button" class="btn btn-small" id="club-claim">👩‍🏫 ${TKD.t('I am the coach (I have the recovery code)', 'أنا المدرب (معايا كود الاسترجاع)')}</button>`}
      <section class="club-box"><h3>📱 ${TKD.t('Players of this device in the club', 'لاعبين الجهاز ده في النادي')}</h3>
        <ul class="club-local">${local.map(p => `<li>${TKD.avatar(p, 'sm')}<span>${TKD.esc(p.name)}</span>
          <label class="tkd-check"><input type="checkbox" data-share="${p.id}" ${p.clubOff ? '' : 'checked'}> ${TKD.t('shown in the club', 'ظاهر في النادي')}</label></li>`).join('') || `<li class="tkd-muted">—</li>`}</ul>
        <button type="button" class="btn btn-small btn-success" id="club-sync">🔄 ${TKD.t('Sync now', 'زامن دلوقتي')}</button></section>
      ${this.isCoach() ? `<section class="club-box"><h3>🌍 ${TKD.t('Everyone in the club', 'كل اللي في النادي')}</h3>
          <ul class="club-all">${rows.filter(r => !r.local).map(r => `<li>${this.avatar(r, 'sm')}<span>${TKD.esc(r.name)}</span><button type="button" class="btn btn-small btn-danger" data-rmp="${r.id}">${TKD.t('Remove', 'شيله')}</button></li>`).join('') || `<li class="tkd-muted">${TKD.t('Nobody from other devices yet.', 'لسه مفيش حد من أجهزة تانية.')}</li>`}</ul>
          ${Object.values(this.cache().players).some(d => d.removed && !d.self) ? `<details><summary>${TKD.t('Removed players', 'اللي اتشالوا')}</summary><ul class="club-all">${Object.values(this.cache().players).filter(d => d.removed && !d.self).map(d => `<li><span>${TKD.esc(d.name || d.id)}</span><button type="button" class="btn btn-small" data-backp="${d.id}">${TKD.t('Bring back', 'رجّعه')}</button></li>`).join('')}</ul></details>` : ''}
        </section>
        <section class="club-box"><h3>📱 ${TKD.t('Devices', 'الأجهزة')}</h3><ul class="club-all" id="club-devices"><li class="tkd-muted">…</li></ul></section>` : ''}
      <button type="button" class="btn btn-small btn-danger" id="club-leave">🚪 ${TKD.t('Take this device out of the club', 'طلّع الجهاز ده من النادي')}</button>
      <p class="club-msg" id="club-msg" aria-live="polite"></p></div>`;
  },
  bindCoach(root) {
    const msg = (t, bad) => { const m = TKD.$('club-msg'); if (m) { m.textContent = t; m.classList.toggle('bad', !!bad); } };
    const busy = (b, on) => { if (b) { b.disabled = on; b.classList.toggle('is-busy', on); } };
    TKD.$('club-join')?.addEventListener('click', async (e) => {
      const btn = e.currentTarget;
      const code = TKD.$('club-code').value.replace(/[^A-Za-z0-9]/g, ''); if (code.length < 6) { msg(TKD.t('Type the 6 letters of the club code.', 'اكتب الـ ٦ حروف بتوع كود النادي.'), true); return; }
      busy(btn, true); msg(TKD.t('Joining…', 'بيدخل…'));
      try { const r = await this.join(code); TKD.toast(TKD.t(`✅ This device is now in ${r.name}`, `✅ الجهاز ده دخل ${r.name}`), 'success'); Coach.render(); }
      catch (err) { busy(btn, false); msg(this.why(err.code || err.message), true); }
    });
    TKD.$('club-create')?.addEventListener('click', async (e) => {
      const btn = e.currentTarget;
      const name = TKD.$('club-name').value.trim(); if (!name) { msg(TKD.t('Write the club name first.', 'اكتب اسم النادي الأول.'), true); return; }
      busy(btn, true); msg(TKD.t('Creating…', 'بيتعمل…'));
      try { const r = await this.create(name); Coach.render(); this.showCreated(r); }
      catch (err) { busy(btn, false); msg(this.why(err.code || err.message), true); }
    });
    TKD.$('club-newcode')?.addEventListener('click', async () => {
      if (!(await tkdConfirm(TKD.t('Make a new club code? Devices already in the club stay in; new devices need the new code.', 'تعمل كود جديد؟ الأجهزة اللي دخلت هتفضل جوه، والأجهزة الجديدة هتحتاج الكود الجديد.'), TKD.t('New code', 'كود جديد')))) return;
      try { await this.newCode(); Coach.render(); } catch (err) { msg(this.why(err.code || err.message), true); }
    });
    TKD.$('club-claim')?.addEventListener('click', async () => {
      const code = await this.ask(TKD.t('Type the coach recovery code (you wrote it down when the club was made):', 'اكتب كود استرجاع المدرب (اللي كتبته لما النادي اتعمل):'), 'XXXXX-XXXXX');
      if (!code) return;
      try { await this.claimCoach(code); TKD.toast(TKD.t('👩‍🏫 This device is now a coach device', '👩‍🏫 الجهاز ده بقى جهاز مدرب'), 'success'); Coach.render(); }
      catch (err) { msg(this.why(err.code || err.message), true); }
    });
    root.querySelectorAll('[data-share]').forEach(cb => cb.addEventListener('change', async () => {
      const pid = cb.dataset.share;
      PlayerSystem.updatePlayer(pid, { clubOff: !cb.checked });
      delete this._sent[pid]; this.pushSoon(300); TKD.toast(TKD.t('✅ Saved', '✅ اتحفظ'), 'success');
    }));
    TKD.$('club-sync')?.addEventListener('click', () => { this._sent = {}; this.disconnect(); this.connect(); this.pushNow(); TKD.toast(TKD.t('🔄 Syncing…', '🔄 بيزامن…'), 'info'); });
    root.querySelectorAll('[data-rmp]').forEach(b => b.addEventListener('click', async () => {
      const d = this.cache().players[b.dataset.rmp];
      if (!(await tkdConfirm(TKD.t(`Remove ${d?.name} from the club? (their progress on their own device stays)`, `تشيل ${d?.name} من النادي؟ (تقدّمه على جهازه بيفضل زي ما هو)`), TKD.t('Remove', 'شيله')))) return;
      try { const be = await this.be(); await this.timeout(be.removePlayer(this.info().clubId, b.dataset.rmp, d?.name)); Coach.render(); } catch (err) { msg(this.why(err.code || err.message), true); }
    }));
    root.querySelectorAll('[data-backp]').forEach(b => b.addEventListener('click', async () => {
      const d = this.cache().players[b.dataset.backp];
      try { const be = await this.be();
        // a small valid profile — that child's own device fills in the rest at its next sync
        await this.timeout(be.putPlayers(this.info().clubId, [{ v: 1, id: d.id, name: d.name || '?', character: 'boy', belt: 'white-0', mastered: 0, level: 1, tier: 0, ach: {}, trophies: [], mastery: [], streak: 0, days: 0, games: 0, perfect: 0, records: {}, week: { k: TKD.weekKey(), pts: 0 }, prev: { k: '', pts: 0 }, today: { d: '', ch: -1 }, badges: 0, removed: false }]));
        Coach.render(); } catch (err) { msg(this.why(err.code || err.message), true); }
    }));
    TKD.$('club-leave')?.addEventListener('click', async () => {
      if (!(await tkdConfirm(TKD.t('Take this device out of the club? Its players stay on this device; they just stop showing in the club.', 'تطلّع الجهاز ده من النادي؟ لاعبينه بيفضلوا على الجهاز، بس مش هيظهروا في النادي.'), TKD.t('Take it out', 'طلّعه')))) return;
      await this.leave(); Coach.render();
    });
    if (this.isCoach() && TKD.$('club-devices')) {
      this.be().then(be => {
        this._devUnsub?.();
        this._devUnsub = be.watchMembers(this.info().clubId, (list) => {
          const ul = TKD.$('club-devices'); if (!ul) { this._devUnsub?.(); this._devUnsub = null; return; }
          const me = be.uid();
          ul.innerHTML = list.map(m => `<li><span>${m.role === 'coach' ? '👩‍🏫' : '📱'} ${TKD.esc(m.device || '?')}${m.uid === me ? ` <small>(${TKD.t('this device', 'الجهاز ده')})</small>` : ''}</span>
            ${m.uid === me ? '' : `<button type="button" class="btn btn-small btn-danger" data-rmd="${m.uid}">${TKD.t('Remove', 'شيله')}</button>`}</li>`).join('') || `<li class="tkd-muted">—</li>`;
          ul.querySelectorAll('[data-rmd]').forEach(b => b.addEventListener('click', async () => {
            if (!(await tkdConfirm(TKD.t('Remove this device from the club?', 'تشيل الجهاز ده من النادي؟'), TKD.t('Remove', 'شيله')))) return;
            try { await be.removeMember(this.info().clubId, b.dataset.rmd); } catch (err) { msg(this.why(err.code || err.message), true); }
          }));
        }, () => {});
      }).catch(() => {});
    }
  },
  // the club was just made: the code for the devices + the coach recovery code, to write down ONCE
  showCreated(r) {
    const ov = document.createElement('div'); ov.className = 'tkd-modal';
    ov.innerHTML = `<div class="tkd-modal-card club-created"><h2>🏟️ ${TKD.esc(r.name)}</h2>
      <p>${TKD.t('Club code — type it on every device of the gym:', 'كود النادي — اكتبه على كل أجهزة الصالة:')}</p>
      <div class="club-code-big" dir="ltr" data-keep-digits>${TKD.esc(r.code)}</div>
      <p>🔐 ${TKD.t('Coach recovery code — write it on paper and keep it. It is shown only now; with it you can be the coach again on a new phone:', 'كود استرجاع المدرب — اكتبه في ورقة واحتفظ بيه. بيظهر دلوقتي بس، وبيه تقدر ترجع مدرب على أي موبايل جديد:')}</p>
      <div class="club-code-big club-code-secret" dir="ltr" data-keep-digits>${TKD.esc(r.coachCode)}</div>
      <label class="tkd-check"><input type="checkbox" id="club-wrote"> ${TKD.t('I wrote the recovery code down', 'كتبت كود الاسترجاع')}</label>
      <div class="tkd-row"><button type="button" class="btn btn-success" id="club-ok" disabled>${TKD.t('Done', 'تمام')}</button></div></div>`;
    document.body.appendChild(ov);
    ov.querySelector('#club-wrote').addEventListener('change', e => { ov.querySelector('#club-ok').disabled = !e.target.checked; });
    ov.querySelector('#club-ok').addEventListener('click', () => ov.remove());
  },
  // a small text question (no browser prompt())
  ask(text, placeholder = '') {
    return new Promise(res => {
      const ov = document.createElement('div'); ov.className = 'tkd-modal';
      ov.innerHTML = `<div class="tkd-modal-card"><p class="tkd-confirm-txt">${TKD.esc(text)}</p>
        <input class="player-name-input" id="club-ask" dir="ltr" autocomplete="off" autocapitalize="characters" placeholder="${TKD.esc(placeholder)}">
        <div class="tkd-row"><button type="button" class="btn" data-a="0">${TKD.t('Cancel', 'إلغاء')}</button><button type="button" class="btn btn-success" data-a="1">${TKD.t('OK', 'تمام')}</button></div></div>`;
      document.body.appendChild(ov);
      const inp = ov.querySelector('#club-ask'); inp.focus();
      const done = (ok) => { const v = inp.value.trim(); ov.remove(); res(ok && v ? v : null); };
      ov.querySelectorAll('[data-a]').forEach(b => b.addEventListener('click', () => done(b.dataset.a === '1')));
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') done(true); });
    });
  }
};
window.Club = Club;

// keep the club up to date: after every game, a player change, the week turning, the signal coming back
(function wireClub() {
  const orig = PlayerSystem.logAttempt.bind(PlayerSystem);
  PlayerSystem.logAttempt = (...a) => { const r = orig(...a); Club.pushSoon(); Club._memo = null; return r; };
  document.addEventListener('tkd:player-changed', () => Club.pushSoon(2000));
  window.addEventListener('online', () => { Club.disconnect(); Club.connect(); Club.pushSoon(1500); });
  window.addEventListener('offline', () => { if (Club.joined()) Club.set('offline'); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') Club.pushSoon(3000); });
  // the screens showing club data redraw when new data arrives
  let t = null;
  document.addEventListener('tkd:club', () => {
    clearTimeout(t); t = setTimeout(() => {
      if (document.querySelector('#league-screen.active')) LeagueScreen.render();
      if (document.querySelector('#home-screen.active') && !document.querySelector('.tkd-modal')) HomeHub.render();
      if (document.querySelector('#coach-screen.active') && Coach.unlocked && Coach.view === 'club' && !document.querySelector('.tkd-modal') && !document.activeElement?.closest?.('input')) Coach.render();
    }, 250);
  });
  const start = () => setTimeout(() => { if (Club.joined()) { Club.connect(); Club.pushSoon(4000); } }, 1200);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
